local config = {
  ui_story_5082_50820100_X1_dialog_content = "Reinhardt!",
  ui_story_5082_50820100_X2_dialog_content = "Huh, jadi jiwa-jiwa yang menuntut balas akhirnya padam, ya? Reinhardt, apa jenis \"naga jahat\" yang telah kamu jadikan?",
  ui_story_5082_50820100_X3_dialog_content = "Bebaskan dirimu dari rantai itu, Reinhardt... seperti yang pernah kita lakukan.",
  ui_story_5082_50820100_1_dialog_content = "<color=#e8d9bb>Pada suatu hari yang cerah yang jarang terjadi, kamu memutuskan untuk berbaring di rumput di luar markas sementara dan membiarkan pikiranmu melayang...</color>",
  ui_story_5082_50820100_2_dialog_content = "Ingin mendengar laporan terbaru?!",
  ui_story_5082_50820100_3_dialog_content = "Ahhh! Ph-Philyshy! Dari mana kamu datang?!",
  ui_story_5082_50820100_4_dialog_content = "Meong? Itu bukan pointnya.",
  ui_story_5082_50820100_5_dialog_content = "Petugas Vivian memberi saya pekerjaan untuk dilakukan, ingat? Saya seharusnya menulis Panduan Darurat Dark Zone untukmu.",
  ui_story_5082_50820100_6_dialog_content = "Kamu menyelesaikannya? Wow, saya tidak mengira kamu akan menyelesaikan tugas ini begitu cepat.",
  ui_story_5082_50820100_7_dialog_content = "Benar kan?! Aku menghabiskan seminggu penuh untuk memikirkannya, tapi aku akhirnya selesai! Itulah sebabnya—",
  ui_story_5082_50820100_8_dialog_content = "Saya meminta Komandan Barton untuk mengambil cuti dua hari untuk melakukan beberapa pelatihan tempur khusus dengan kamu!",
  ui_story_5082_50820100_9_dialog_content = "Pelatihan tempur khusus... dengan Barton? Apa yang terjadi dengan Panduan Darurat Dark Zone?",
  ui_story_5082_50820100_10_dialog_content = "Nah, aku telah berpikir panjang dan keras selama berhari-hari dan menyadari bahwa Petugas Vivian sedang mengujiku—pertempuran bukanlah sesuatu yang bisa kamu pelajari dari buku, meong!",
  ui_story_5082_50820100_11_dialog_content = "Kamu hanya mendorong pekerjaanmu ke orang lain, bukan?!",
  ui_story_5082_50820100_12_dialog_content = "Jika saya menjalani jenis pelatihan apa pun dengan Barton sekarang, saya akan mati sebelum bahkan mencapai Dark Zone.",
  ui_story_5082_50820100_13_dialog_content = "Inilah sebabnya mengapa kamu memerlukan latihan, meong!",
  ui_story_5082_50820100_14_dialog_content = "Selain itu, ini juga memberi saya kesempatan untuk menilai keahlian tempurmu—",
  ui_story_5082_50820100_15_dialog_content = "Aku akan pastikan kamu membuat banyak kemajuan yang berarti, yang juga berarti aku akan melakukan pekerjaanku, meong!",
  ui_story_5082_50820100_16_dialog_content = "Mencetuskan ide brilian seperti ini tidak mudah, tahu! Tapi menulis laporan seharusnya jauh lebih mudah sekarang, yang berarti aku juga bisa santai!",
  ui_story_5082_50820100_17_dialog_content = "Tidak adakah batas untuk kemalasanmu, Philyshy?!",
  ui_story_5082_50820100_18_dialog_content = "Tidak, dan sekarang kamu tahu rencananya, tidak ada gunanya memperdebatkannya! Sekarang ikutlah denganku kembali ke Illumina!",
  ui_story_5082_50820100_19_dialog_content = "Jika kita cepat, aku mungkin bahkan punya waktu untuk tidur sebentar... Yaaawn!",
  ui_story_5082_50820100_20_dialog_content = "Jika bermalas-malasan adalah olahraga, dia akan menjadi profesional... H-Hey! Jangan berani-berani tertidur!",
  ui_story_5082_50820100_21_dialog_content = "Setidaknya beri tahu aku tentang apa latihan itu—",
  ui_story_5082_50820100_22_dialog_content = "<color=#e8d9bb>Lapangan Latihan Kota Gannon</color>",
  ui_story_5082_50820100_23_dialog_content = "Dia benar-benar membawaku ke lapangan latihan tanpa tertidur...",
  ui_story_5082_50820100_24_dialog_content = "Maaf Philyshy, saya salah telah meragukanmu. Saya tidak menyadari bahwa kamu juga bisa menjadi pekerja keras.",
  ui_story_5082_50820100_25_dialog_content = "Permintaan maaf dan pujian diterima! Ada alasan saya membawa Anda langsung ke sini, tahu!",
  ui_story_5082_50820100_26_dialog_content = "Sebuah alasan?",
  ui_story_5082_50820100_27_dialog_content = "Hosh... Hosh...",
  ui_story_5082_50820100_28_dialog_content = "Apakah kamu lupa makan atau apa? Eclipsites akan menjadikanmu makanan jika kamu terus berlari dengan lambat!",
  ui_story_5082_50820100_29_dialog_content = "Gali lebih dalam dan berikan aku lima puluh kilometer lagi! Dan lakukan lebih cepat kali ini!",
  ui_story_5082_50820100_30_dialog_content = "Siap, Pak!",
  ui_story_5082_50820100_31_dialog_content = "Ini adalah tim Barton. Sepertinya mereka sedang berada di tengah-tengah latihan.",
  ui_story_5082_50820100_32_dialog_content = "Waktu yang sempurna! Sekarang pergi dan bergabunglah dengan mereka!",
  ui_story_5082_50820100_33_dialog_content = "Tunggu... Aku?",
  ui_story_5082_50820100_34_dialog_content = "Iya, kau!",
  ui_story_5082_50820100_35_dialog_content = "Ini adalah kamp latihan baru Komandan Barton, di mana dia membentuk rekrutan yang tidak berpengalaman menjadi lebih baik! Ini adalah tempat yang sempurna untukmu, PlayerName!",
  ui_story_5082_50820100_36_dialog_content = "Jadi, berusahalah sebaik mungkin untuk mengikuti program latihan mereka, oke? Aku hanya akan berada di sini tidur... Maksudku mengamati!",
  ui_story_5082_50820100_37_dialog_content = "... Kutarik lagi semua yang baru saja aku katakan!",
  ui_story_5082_50820100_38_dialog_content = "Haha, aku suka semangatmu, anak!",
  ui_story_5082_50820100_39_dialog_content = "Tapi jika kamu ingin memiliki peluang melawan musuh kita di Dark Zone, latihan kita di sini tidak akan cukup.",
  ui_story_5082_50820100_40_dialog_content = "Setelah semua pertempuranmu, saya yakin sudah sangat jelas bagi kamu: kalah di sana berarti mati.",
  ui_story_5082_50820100_41_dialog_content = "Itulah sebabnya saya akan melatihmu sampai mati sebelum Dark Zone mengalahkan saya! Mengerti?",
  ui_story_5082_50820100_42_dialog_content = "S-siap, Pak!",
  ui_story_5082_50820100_43_dialog_content = "(Keberadaan Barton sangat luar biasa... Saya bahkan tidak berpikir untuk mengatakan tidak barusan...)",
  ui_story_5082_50820100_44_dialog_content = "Baguslah kalau begitu.",
  ui_story_5082_50820100_45_dialog_content = "Mari kita lihat, bagaimana caranya saya mengubah Caelestite kecil yang lemah menjadi mesin tempur yang gesit dan tangguh dalam waktu yang paling singkat mungkin?",
  ui_story_5082_50820100_46_dialog_content = "Um, kenapa aku tidak bisa melakukan latihan yang sama seperti semua orang lain?",
  ui_story_5082_50820100_47_dialog_content = "Hmph, bicarakanlah dengan orang-orang tua bodoh di Komite itu. Mereka yang bersikeras agar kita menggunakan metode latihan \"ilmiah\" baru mereka.",
  ui_story_5082_50820100_48_dialog_content = "Mereka menyiapkan berbagai jenis acuan dan template, seolah-olah mereka mencoba mengatur setiap detik latihan!",
  ui_story_5082_50820100_49_dialog_content = "Tapi bukankah itu semacam intinya?",
  ui_story_5082_50820100_50_dialog_content = "Mungkin hanya untuk latihan fisik, tentu saja.",
  ui_story_5082_50820100_51_dialog_content = "Tapi saya melatih prajurit sungguhan di sini, bukan sekumpulan boneka produksi massal! Tugas saya adalah mempersiapkan mereka untuk melawan musuh di garis depan!",
  ui_story_5082_50820100_52_dialog_content = "Metode pelatihan yang kaku seperti ini tidak akan pernah menghasilkan prajurit yang benar-benar luar biasa. Itulah pendapat saya.",
  ui_story_5082_50820100_53_dialog_content = "Di masa lalu, Grand Marshal dan saya selalu terlibat dalam latihan tempur langsung dengan orang lain, meskipun kami tidak berada di garis depan.",
  ui_story_5082_50820100_54_dialog_content = "Terlepas dari pangkat atau posisi, kita semua akan masuk ke wilayah yang tidak dikenal dan menguji kekuatan kita satu sama lain.",
  ui_story_5082_50820100_55_dialog_content = "Selain jumlah amunisi dan pasokan yang langka, yang bisa kami andalkan hanyalah tubuh dan akal kami.",
  ui_story_5082_50820100_56_dialog_content = "Dalam keadaan tersebut, orang-orang yang tinggi dan perkasa tidak selalu unggul dalam kompetisi. Bahkan peserta yang paling tidak menonjol pun memiliki peluang untuk menang.",
  ui_story_5082_50820100_57_dialog_content = "Pertempuran, strategi, kekalahan, dan kemenangan.",
  ui_story_5082_50820100_58_dialog_content = "Rasa sakit ditindas ke lumpur oleh yang kuat, dan tekad untuk menang dengan cara apa pun yang diperlukan.",
  ui_story_5082_50820100_59_dialog_content = "Hanya dengan mengalami hal-hal ini secara langsung, seorang prajurit dapat dibentuk menjadi sesuatu yang benar-benar kuat.",
  ui_story_5082_50820100_60_dialog_content = "Skenario pertempuran realistis di mana apa pun bisa terjadi kapan saja adalah cara terbaik untuk mengasah keterampilan seseorang!",
  ui_story_5082_50820100_61_dialog_content = "Kata yang bagus, Barton.",
  ui_story_5082_50820100_62_dialog_content = "Reinhardt! Kamu di sini juga?",
  ui_story_5082_50820100_63_dialog_content = "Aku datang untuk melihat perkembangan prajurit kita sebelum kami memasuki Dark Zone. Sepertinya aku datang tepat waktu.",
  ui_story_5082_50820100_64_dialog_content = "Kita belum berhadapan langsung dalam waktu yang cukup lama, Barton. Bagaimana kalau kita lihat siapa di antara kita yang paling banyak berkembang sejak terakhir kali?",
  ui_story_5082_50820100_65_dialog_content = "Itulah yang bisa saya minta!",
  ui_story_5082_50820100_66_dialog_content = "Tunggu, kalian berdua tidak akan...",
  ui_story_5082_50820100_67_dialog_content = "Itu benar! Kita sedang melakukan latihan tempur langsung, di sini dan sekarang!",
  ui_story_5082_50820100_68_dialog_content = "Tidak boleh kabur, paham, Nak?!",
  ui_story_5082_50820100_69_dialog_content = "A-Aku tidak akan pernah! Aku bukan tipe orang yang menyerah sebelum bahkan memulai!",
  ui_story_5082_50820100_70_dialog_content = "Bagus, maka anggap ini sebagai bagian dari latihan khususmu, PlayerName. Tentu saja, handlermu juga akan berpartisipasi.",
  ui_story_5082_50820100_71_dialog_content = "Bukankah begitu, Intel Chief Philyshy?",
  ui_story_5082_50820100_72_dialog_content = "Sekarang kamu sebut itu, sudah cukup lama aku tidak mendengar dia mengatakan sesuatu... Hei! Kapan kamu pergi ke sana?!",
  ui_story_5082_50820100_73_dialog_content = "Huff... Jika kamu bilang begitu, Grand Marshal.",
  ui_story_5082_50820100_74_dialog_content = "Philyshy telah bergabung dalam pertempuran!",
  ui_story_5082_50820100_75_dialog_content = "<color=#e8d9bb>Beberapa saat kemudian</color>",
  ui_story_5082_50820100_76_dialog_content = "Selamat siang, semua orang. Meskipun ini bukan bagian dari program asli—",
  ui_story_5082_50820100_77_dialog_content = "Atas permintaan Grand Marshal, saya datang untuk bertugas sebagai juri untuk latihan ini.",
  ui_story_5082_50820100_78_dialog_content = "Latihan ini, yang akan berlangsung selama dua hari dan dua malam, akan terdiri dari empat tim dengan dua orang setiap tim. Silakan lihat daftar peserta.",
  ui_story_5082_50820100_79_dialog_content = "Tim 1 adalah Reinhardt dan Philyshy.",
  ui_story_5082_50820100_80_dialog_content = "Barton dan saya berada di Tim 2. Dua tim terakhir terdiri dari para perwira dari 2nd Legion...",
  ui_story_5082_50820100_81_dialog_content = "Jadi, di mana sebenarnya kita bertempur?",
  ui_story_5082_50820100_82_dialog_content = "Itu cukup sederhana untuk dijawab.",
  ui_story_5082_50820100_83_dialog_content = "<color=#e8d9bb>Goyang, goyang, goyang—Gulir—</color>",
  ui_story_5082_50820100_84_dialog_content = "Dia benar-benar membawa dadu untuk simulasi militer bersamanya...?",
  ui_story_5082_50820100_85_dialog_content = "Ha! Sepertinya kita akan membawa kompetisi kecil ini ke Undercity terdekat.",
  ui_story_5082_50820100_86_dialog_content = "Kamu beruntung, anak. Undercity itu telah ditinggalkan selama berabad-abad, dan aku sedang dalam proses mengambil alihnya untuk menjadi tempat latihanku.",
  ui_story_5082_50820100_87_dialog_content = "Ini adalah area yang luas dengan banyak struktur yang ditinggalkan.",
  ui_story_5082_50820100_88_dialog_content = "Tata letak ini sempurna untuk melancarkan serangan mendadak—Meskipun saya yakin lawan kita juga berpikir hal yang sama.",
  ui_story_5082_50820100_89_dialog_content = "Kamu tampak sangat tenang tentang ini. Kamu yakin ini tidak akan menjadi masalah?",
  ui_story_5082_50820100_90_dialog_content = "Eclipsite tidak mempertimbangkan hal-hal ini saat mereka menyerang. Tingkat ketidakpastian ini hanyalah bagian lain dari simulasi pertempuran; saya sarankan kamu untuk terbiasa dengan itu.",
  ui_story_5082_50820100_91_dialog_content = "Tunggu... Sebagai hakim, bukankah seharusnya saya yang menentukan lokasinya?",
  ui_story_5082_50820100_92_dialog_content = "Hahahaha! Maaf, aku jadi terlalu bersemangat sampai-sampai aku malah melakukan pekerjaan Chief of Staff untuknya!",
  ui_story_5082_50820100_93_dialog_content = "...",
  ui_story_5082_50820100_94_dialog_content = "Cukup ikuti pilihan Barton, Vivian.",
  ui_story_5082_50820100_95_dialog_content = "Baiklah. Kalian masing-masing memiliki tiga puluh menit untuk bersiap sebelum memasuki lokasi kontes. Ketika bel berbunyi, pertandingan akan resmi dimulai.",
  ui_story_5082_50820100_96_dialog_content = "Ini adalah kesempatan berharga untuk mendapatkan pengalaman tempur yang berharga, jadi tolong perlakukan ini dengan serius dan bertarunglah dengan semua kekuatan Anda.",
  ui_story_5082_50820100_97_dialog_content = "Paham!",
  ui_story_5082_50820100_98_dialog_content = "Undercity terdekat... Kami hampir tidak memiliki informasi tentang itu. Barton pasti tahu bagaimana memilih pertempurannya.",
  ui_story_5082_50820201_1_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5082_50820201_2_dialog_content = "Hahahaha, tidak buruk! Mari kita lihat Grand Marshal menghentikan kita sekarang setelah bentengnya hancur!",
  ui_story_5082_50820201_3_dialog_content = "*Uhuk*",
  ui_story_5082_50820201_4_dialog_content = "Begitu banyak asap dan puing... Ugh... Ledakan seperti itu pasti akan mengungkapkan posisi kita.",
  ui_story_5082_50820201_5_dialog_content = "Haruskah kita mencoba menjauh dari lokasi ini?",
  ui_story_5082_50820201_6_dialog_content = "Benar. Kita bisa membiarkan yang lain bermain untuk sisa pertandingan.",
  ui_story_5082_50820201_7_dialog_content = "Ayo berpencar dan kumpulkan makanan serta sumber daya apa pun yang bisa kita temukan, PlayerName!",
  ui_story_5082_50820201_8_dialog_content = "Baik!",
  ui_story_5082_50820201_9_dialog_content = "Aku akan pergi ke arah ini... Hah?",
  ui_story_5082_50820201_10_dialog_content = "Rasanya seperti ada seseorang yang memperhatikanku...",
  ui_story_5082_50820201_11_dialog_content = "Sigh... Saya bekerja sangat keras di benteng itu juga.",
  ui_story_5082_50820201_12_dialog_content = "Kamu tidak harus meledakkannya seperti itu, tahu!",
  ui_story_5082_50820201_13_dialog_content = "(Dia sudah kembali?!)",
  ui_story_5082_50820201_14_dialog_content = "(Tapi sepertinya Philyshy sendirian...)",
  ui_story_5082_50820201_15_dialog_content = "Tunggu, Philyshy! Dengarkan dulu apa yang ingin saya katakan!",
  ui_story_5082_50820201_16_dialog_content = "Barton tidak terlalu jauh dari lokasi kita. Jika kamu menyerangku sekarang, dia akan ada di sini sebelum kamu menyadarinya.",
  ui_story_5082_50820201_17_dialog_content = "Bertarung melawan kami berdua sendiri bukanlah kepentingan terbaikmu.",
  ui_story_5082_50820201_18_dialog_content = "Jadi, mengapa tidak mundur untuk saat ini? Jika kamu melakukannya, saya janji kami tidak akan menyerang timmu selama dua jam ke depan.",
  ui_story_5082_50820201_19_dialog_content = "Kami bahkan akan membantu kamu dengan mengalahkan dua tim lainnya! Kamu akan memiliki dua jam penuh untuk melakukan apa pun yang kamu inginkan, bahkan jika itu tidak ada apa-apa!",
  ui_story_5082_50820201_20_dialog_content = "Hmm, itu terdengar bagus.",
  ui_story_5082_50820201_21_dialog_content = "Lalu—",
  ui_story_5082_50820201_22_dialog_content = "Sayangnya, saya tidak pernah membiarkan seekor tikus lepas dari pandangan saya setelah saya menghimpitnya!",
  ui_story_5082_50820201_23_dialog_content = "Oh tidak... Itu Yumi!",
  ui_story_5082_50820201_24_dialog_content = "Sekarang sudah terlambat!",
  ui_story_5082_50820201_25_dialog_content = "(Jika saya tidak bisa bernegosiasi keluar dari ini... Maka saya hanya harus lari!)",
  ui_story_5082_50820201_26_dialog_content = "Tetap diam, maukah kamu?!",
  ui_story_5082_50820201_27_dialog_content = "Aku tidak tahan ketika mangsaku terus berlarian!",
  ui_story_5082_50820201_28_dialog_content = "PlayerName! Tunggu, aku hampir sampai di sana!",
  ui_story_5082_50820201_29_dialog_content = "Hmm? Apakah itu...",
  ui_story_5082_50820201_30_dialog_content = "Cari, PlayerName!",
  ui_story_5082_50820201_31_dialog_content = "!!",
  ui_story_5082_50820201_32_dialog_content = "Itu... Itu Reinhardt! Sekarang aku benar-benar selesai!",
  ui_story_5082_50820201_33_dialog_content = "Aku tahu membangun benteng di tempat yang begitu jelas adalah langkah yang tepat.",
  ui_story_5082_50820201_34_dialog_content = "Maaf PlayerName, tetapi sepertinya latihan khususmu akan dipotong pendek.",
  ui_story_5082_50820201_35_dialog_content = "Awas, anak! Grand Marshal akan membuatmu hancur jika ini terus berlanjut!",
  ui_story_5082_50820201_36_dialog_content = "Cepat dan lari!",
  ui_story_5082_50820201_37_dialog_content = "Kamu bisa berlari secepat yang kamu mau, tapi—",
  ui_story_5082_50820201_38_dialog_content = "Lari!",
  ui_story_5082_50820201_39_dialog_content = "Lari!",
  ui_story_5082_50820201_40_dialog_content = "... Siapa di sana?",
  ui_story_5082_50820201_41_dialog_content = "Jangan biarkan mereka mencuri kekuatanmu—",
  ui_story_5082_50820201_42_dialog_content = "Suara itu...",
  ui_story_5082_50820201_43_dialog_content = "Lari!!!",
  ui_story_5082_50820201_44_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5082_50820201_45_dialog_content = "…!",
  ui_story_5082_50820201_46_dialog_content = "Tidak ada yang lebih buruk daripada kalah dalam pertempuran karena ketidakpastianmu sendiri!",
  ui_story_5082_50820201_47_dialog_content = "Barton— Ah!",
  ui_story_5082_50820201_48_dialog_content = "PlayerName telah diamankan!",
  ui_story_5082_50820201_49_dialog_content = "\"Aman\"? Apa saya ini, sebuah paket?!",
  ui_story_5082_50820201_50_dialog_content = "Apa ini... Sebuah gerobak tambang? Dari mana asalnya ini?!",
  ui_story_5082_50820201_51_dialog_content = "Berikut pelajaran berharga lainnya untukmu, anak: dalam pertempuran, tidak ada benda yang tidak berguna!",
  ui_story_5082_50820201_52_dialog_content = "Dan untuk itu, saya ingin menambahkan beberapa kata dari diri saya sendiri.",
  ui_story_5082_50820201_53_dialog_content = "Dalam pertempuran, tidak ada yang namanya solusi sempurna untuk setiap masalah.",
  ui_story_5082_50820201_54_dialog_content = "Reinhardt sedang mengejar!",
  ui_story_5082_50820201_55_dialog_content = "Meskipun hatinya tidak di dalamnya, saya rasa dia masih Grand Marshal.",
  ui_story_5082_50820201_56_dialog_content = "Beberapa luka lama kembali membara tadi, itu saja. Percayalah padaku, kamu tidak akan mendapatkan kesempatan seperti itu lagi.",
  ui_story_5082_50820201_57_dialog_content = "Tch! Pegang erat-erat, PlayerName!",
  ui_story_5082_50820201_58_dialog_content = "Ekspres Barton sedang berjalan dengan kecepatan penuh!",
  ui_story_5082_50820201_59_dialog_content = "Ahhhhh—",
  ui_story_5082_50820201_60_dialog_content = "Kalau kamu akan memperlakukanku seperti kargo, setidaknya perlakukan aku dengan hati-hati!!!",
  ui_story_5082_50820201_61_dialog_content = "Hahahaha!",
  ui_story_5082_50820201_62_dialog_content = "T-Tunggu, lihat di sana! Itu jalan buntu! Kita akan jatuh—!",
  ui_story_5082_50820201_63_dialog_content = "Maka kita akan meledakkan jalan kita menembusnya!",
  ui_story_5082_50820201_64_dialog_content = "Apa?!",
  ui_story_5082_50820201_65_dialog_content = "Tidak ada waktu untuk menjelaskan! Awas kepalamu!",
  ui_story_5082_50820201_66_dialog_content = "Tunggu—",
  ui_story_5082_50820201_67_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5082_50820201_68_dialog_content = "<color=#e8d9bb>Ping! Bam! Klang, klang, klang!</color>",
  ui_story_5082_50820201_69_dialog_content = "Argh…",
  ui_story_5082_50820201_70_dialog_content = "Akhirnya kita berhenti... Saya pikir saya pasti sudah mati...",
  ui_story_5082_50820201_71_dialog_content = "Apa yang perlu ditakuti? Aku telah menyelamatkanmu dari Grand Marshal, 'kan?",
  ui_story_5082_50820201_72_dialog_content = "Tidak, itu bukan pointnya... Hei Barton?",
  ui_story_5082_50820201_73_dialog_content = "Ya?",
  ui_story_5082_50820201_74_dialog_content = "Kamu benar-benar tidak seharusnya diizinkan untuk mengemudi.",
  ui_story_5082_50820201_75_dialog_content = "?",
  ui_story_5082_50820201_76_dialog_content = "Pokoknya, tempat apa ini?",
  ui_story_5082_50820201_77_dialog_content = "Kami berlari begitu lama sampai-sampai saya kehilangan arah. Mungkin saya harus menggunakan kekuatan saya untuk merasakan sekitar kita.",
  ui_story_5082_50820201_78_dialog_content = "Sebelum kamu melakukan itu, coba amati lingkungan sekitarmu terlebih dahulu.",
  ui_story_5082_50820201_79_dialog_content = "Lingkungan sekitarku?",
  ui_story_5082_50820201_80_dialog_content = "Wow, lihat semua kotak ini! Mungkinkah mereka...?!",
  ui_story_5082_50820201_81_dialog_content = "Mereka adalah! Peti pasokan!",
  ui_story_5082_50820201_82_dialog_content = "Kamu tidak berpikir bahwa aku hanya membawamu dalam perjalanan liar, 'kan?",
  ui_story_5082_50820201_83_dialog_content = "Dalam pertempuran, tidak ada satu tindakan pun yang benar-benar independen dari situasi lainnya.",
  ui_story_5082_50820201_84_dialog_content = "Dapat menyerap segala sesuatu dalam bidang pandang Anda akan membawa Anda selangkah lebih dekat ke kemenangan.",
  ui_story_5082_50820201_85_dialog_content = "Hari pertama kompetisi hampir berakhir. Mengambil alih pasokan ini akan memberi kita salah satu keuntungan terbesar yang mungkin.",
  ui_story_5082_50820201_86_dialog_content = "Sayangnya, keuntungan besar itu juga membuat Anda menjadi target utama bagi semua orang lainnya.",
  ui_story_5082_50820201_87_dialog_content = "Tidak ada bedanya dengan memiliki tombak yang ditujukan ke kepalamu setiap saat.",
  ui_story_5082_50820201_88_dialog_content = "Barton!",
  ui_story_5082_50820201_89_dialog_content = "Tenang, Anak. Kita belum kalah.",
  ui_story_5082_50820201_90_dialog_content = "Ayo sekarang, Grand Marshal. Bahkan anak sekolah tahu bahwa siapa pun yang memiliki makanan ringan terbaik akan selalu menjadi target iri hati.",
  ui_story_5082_50820201_91_dialog_content = "Saya menemukan persediaan ini terlebih dahulu, jadi tidak mungkin saya menyerahkannya begitu saja.",
  ui_story_5082_50820201_92_dialog_content = "PlayerName memegang detonator di tangannya. Satu tekanan tombol, dan bahan peledak berdaya rendah yang telah aku sebarkan di antara persediaan akan meledak, mengubah segalanya menjadi abu.",
  ui_story_5082_50820201_93_dialog_content = "(Hah? Detonator?)",
  ui_story_5082_50820201_94_dialog_content = "Kamu harus tahu persis apa artinya bagi seseorang untuk menghancurkan persediaan mereka sendiri dalam pertempuran.",
  ui_story_5082_50820201_95_dialog_content = "Latihan ini berlangsung selama dua hari penuh. Sebagai Grand Marshal, apakah kamu benar-benar bersedia membiarkan bawahanmu bertarung tanpa makanan di perut mereka?",
  ui_story_5082_50820201_96_dialog_content = "Hahaha, aku hampir lupa bagaimana rasanya menghadapimu di medan pertempuran.",
  ui_story_5082_50820201_97_dialog_content = "Tapi meski itu berarti harus kelaparan—",
  ui_story_5082_50820201_98_dialog_content = "(... Hah? Apa di bumi ini...)",
  ui_story_5082_50820201_99_dialog_content = "(Ini sudah hari kedua dari latihan. Situasi ini... tidak akan berakhir dalam waktu dekat.)",
  ui_story_5082_50820201_100_dialog_content = "(Saya satu-satunya yang menemukan amunisi di hari pertama. Tidak ada orang lain yang saya temui memiliki jatah.)",
  ui_story_5082_50820201_101_dialog_content = "(Aku tidak akan berhasil dengan cara ini...)",
  ui_story_5082_50820201_102_dialog_content = "Jadi, kamu yang mengambil amunisi itu, ya?",
  ui_story_5082_50820201_103_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5082_50820201_104_dialog_content = "Menembak sebelum mengetahui identitas orang lain? Itu tidak baik.",
  ui_story_5082_50820201_105_dialog_content = "Kamu yang menyelinap ke kampku. Kamu tidak berhak atas segala kesopanan.",
  ui_story_5082_50820201_106_dialog_content = "Hahahaha! Jadi mari kita bekerja sama, Reinhardt!",
  ui_story_5082_50820201_107_dialog_content = "Ini seharusnya menjadi latihan tempur nyata. Mengapa saya harus setuju untuk bekerja sama dengan infiltrator seperti kamu?",
  ui_story_5082_50820201_108_dialog_content = "Nah, untuk permulaan, aku telah menahan seranganmu tadi tanpa banyak usaha— Dan kamu tidak menahan diri, bukan?",
  ui_story_5082_50820201_109_dialog_content = "Ada juga keuntungan lain bekerja denganku. Misalnya, ransum.",
  ui_story_5082_50820201_110_dialog_content = "Masih banyak pejuang kuat lainnya dalam latihan ini. Hanya masalah waktu sebelum seorang pemenang ditentukan.",
  ui_story_5082_50820201_111_dialog_content = "Tidak bisa dipungkiri bahwa aku butuh amunisi, dan sesuatu mengatakan padaku bahwa kamu tidak ingin bertarung dengan perut kosong, bukan?",
  ui_story_5082_50820201_112_dialog_content = "Ck...",
  ui_story_5082_50820201_113_dialog_content = "Sepakat.",
  ui_story_5082_50820201_114_dialog_content = "<color=#e8d9bb>Dua hari kemudian</color>",
  ui_story_5082_50820201_115_dialog_content = "Saya tidak menyangka bisa mengalahkan tim lain begitu cepat. Kamu cukup baik.",
  ui_story_5082_50820201_116_dialog_content = "Tentu saja.",
  ui_story_5082_50820201_117_dialog_content = "Sepertinya kita sudah selesai bertarung untuk hari ini. Kamu sudah menggunakan amunisiku, jadi serahkan ranselmu dan—",
  ui_story_5082_50820201_118_dialog_content = "<color=#e8d9bb>Mendera!</color>",
  ui_story_5082_50820201_119_dialog_content = "Argh…",
  ui_story_5082_50820201_120_dialog_content = "Serangan diam-diam... Seharusnya aku tahu.",
  ui_story_5082_50820201_121_dialog_content = "Dia sudah pergi... bersama dengan semua amunisi saya.",
  ui_story_5082_50820201_122_dialog_content = "Ugh... Aku tidak percaya aku tertipu seperti itu.",
  ui_story_5082_50820201_123_dialog_content = "Saya belum makan selama dua hari, dan pertempuran barusan telah menguras banyak energi saya. Semakin sulit untuk bertahan.",
  ui_story_5082_50820201_124_dialog_content = "Aku harus beristirahat di sini sepanjang hari dan menghemat sedikit energi yang masih aku miliki. Ketika besok tiba, aku akan...",
  ui_story_5082_50820201_125_dialog_content = "<color=#e8d9bb>Dua hari lagi kemudian</color>",
  ui_story_5082_50820201_126_dialog_content = "(Kepalaku pusing... Dan tubuhku terasa sangat berat.)",
  ui_story_5082_50820201_127_dialog_content = "(Tapi pertempurannya belum berakhir. Aku harus terus melanjutkan...)",
  ui_story_5082_50820201_128_dialog_content = "(Daripada marah, saya perlu memikirkan langkah selanjutnya—)",
  ui_story_5082_50820201_129_dialog_content = "Wow, kamu masih bisa bergerak?",
  ui_story_5082_50820201_130_dialog_content = "Berani-beraninya kamu, menunjukkan dirimu di sekitarku.",
  ui_story_5082_50820201_131_dialog_content = "Kenapa begitu? Itu salahmu sendiri karena tidak bisa mengetahui motifku lebih cepat.",
  ui_story_5082_50820201_132_dialog_content = "Di akhir hari, saya rasa bahkan siswa teratas pun tidak berarti banyak!",
  ui_story_5082_50820201_133_dialog_content = "Katakan padaku, apa yang lebih sakit sekarang? Lukamu atau rasa laparmu?",
  ui_story_5082_50820201_134_dialog_content = "Cukup diam dan bawa aku keluar. Itulah mengapa kau di sini, kan?",
  ui_story_5082_50820201_135_dialog_content = "Oh, aku mengerti. Kamu hampir tidak bisa berdiri sekarang, bukan? Kasihan sekali.",
  ui_story_5082_50820201_136_dialog_content = "Aku bilang diam!",
  ui_story_5082_50820201_137_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5082_50820201_138_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5082_50820201_139_dialog_content = "Hindar, PlayerName!",
  ui_story_5082_50820201_140_dialog_content = "Barton!",
  ui_story_5082_50820201_141_dialog_content = "Apa ini, ribut sekali... Jadi jatahnya ada di sini selama ini!",
  ui_story_5082_50820201_142_dialog_content = "Lihat itu? Grand Marshal dan Komandan Barton sedang berusaha keras... Apakah kita benar-benar ingin menghalangi itu?",
  ui_story_5082_50820201_143_dialog_content = "...",
  ui_story_5082_50820201_144_dialog_content = "…!",
  ui_story_5082_50820201_145_dialog_content = "(Apakah itu... ingatan saya tadi?)",
  ui_story_5082_50820201_146_dialog_content = "Dan di sini saya pikir Anda sedang melamun... Tapi jika kita serius dalam pertarungan ini, mari kita lihat seberapa jauh Anda telah berkembang, Grand Marshal!",
  ui_story_5082_50820301_1_dialog_content = "... Senang kita memutuskan untuk tidak ikut campur. Serangan barusan pasti akan membunuh kita ratusan kali lipat.",
  ui_story_5082_50820301_2_dialog_content = "Mereka berada di level yang sepenuhnya berbeda, setelah semua. Kamu tidak bisa melihatnya dari melihat Komandan Barton ketika dia bertarung dengan Eclipsite...",
  ui_story_5082_50820301_3_dialog_content = "Grand Marshal Reinhardt baru saja membuatnya terpojok, tapi dia tidak memiliki goresan sedikitpun! Tubuh apa yang dia miliki...?",
  ui_story_5082_50820301_4_dialog_content = "... Apakah rumor itu benar? Mereka mengatakan bahwa Komandan Barton mendapatkan kekuatan besar berkat serangkaian eksperimen khusus.",
  ui_story_5082_50820301_5_dialog_content = "Saya juga mendengar bahwa beberapa rekrutan baru kami, yang paling dekat dengan ilmuwan kami, telah melalui program yang sama. Berapa banyak dari mereka yang ada di Illumina...?",
  ui_story_5082_50820301_6_dialog_content = "Sepertinya kamu cukup tertarik pada mereka.",
  ui_story_5082_50820301_7_dialog_content = "Siapa yang tidak akan? Jika itu benar, semua yang dibutuhkan untuk bergabung dengan pasukan khusus hanyalah beberapa prosedur!",
  ui_story_5082_50820301_8_dialog_content = "Tapi siapa yang tahu jenis eksperimen gila apa yang mereka alami—",
  ui_story_5082_50820301_9_dialog_content = "Setidaknya, aku belum berubah menjadi Eclipsite, iya 'kan?",
  ui_story_5082_50820301_10_dialog_content = "C-C-Commander Barton!!!",
  ui_story_5082_50820301_11_dialog_content = "...",
  ui_story_5082_50820301_12_dialog_content = "Kenapa tiba-tiba diam sekali?",
  ui_story_5082_50820301_13_dialog_content = "Tidak ada aturan yang melarang kamu untuk berbicara apa yang ada di pikiranmu di 2nd Legion, atau di tempat lain di Illumina.",
  ui_story_5082_50820301_14_dialog_content = "Jika ada yang ingin kau katakan kepada komandermu, katakan saja.",
  ui_story_5082_50820301_15_dialog_content = "T-Tapi kamu berbeda dari yang lain, Komandan Barton!",
  ui_story_5082_50820301_16_dialog_content = "Setiap orang mengatakan bahwa Illumina berada dalam bahaya serius saat itu, dan bahwa kamu hanya melakukan pengorbanan itu untuk membalikkan keadaan pertempuran!",
  ui_story_5082_50820301_17_dialog_content = "Tapi yang lain...",
  ui_story_5082_50820301_18_dialog_content = "Apakah mereka bertempur di garis depan?",
  ui_story_5082_50820301_19_dialog_content = "aku, eh...",
  ui_story_5082_50820301_20_dialog_content = "Aku bertanya padamu, prajurit! \"Orang lain\" yang selalu kamu bicarakan ini; apakah mereka bertarung melawan Eclipsite di garis depan?!",
  ui_story_5082_50820301_21_dialog_content = "Siap, Pak!",
  ui_story_5082_50820301_22_dialog_content = "Apakah mereka berjuang melalui pelatihan yang sama pahitnya dengan yang telah kamu jalani?!",
  ui_story_5082_50820301_23_dialog_content = "Siap, Pak!",
  ui_story_5082_50820301_24_dialog_content = "Apakah mereka bisa menikmati hidup yang damai dan bebas hanya karena mereka telah melalui eksperimen tersebut?",
  ui_story_5082_50820301_25_dialog_content = "... Tidak, pak.",
  ui_story_5082_50820301_26_dialog_content = "Maka mereka masih prajurit Illumina, dan kawan senjatamu!",
  ui_story_5082_50820301_27_dialog_content = "Darah dan keringat yang mereka tumpahkan tidak berbeda dengan milikmu!",
  ui_story_5082_50820301_28_dialog_content = "Mereka telah membuat pengorbanan dengan cara yang bahkan tidak bisa kamu bayangkan, semua demi masa depan Illumina.",
  ui_story_5082_50820301_29_dialog_content = "Mereka sama sekali tidak berbeda dari saya dalam hal apapun. Memandang rendah mereka sama saja dengan memandang rendah saya!",
  ui_story_5082_50820301_30_dialog_content = "Tapi jika kamu tidak berniat melihatku sebagai semacam monster, jangan pernah lupakan bahwa mereka masih tetap temanmu.",
  ui_story_5082_50820301_31_dialog_content = "...",
  ui_story_5082_50820301_32_dialog_content = "<color=#e8d9bb>Wuuss—</color>",
  ui_story_5082_50820301_33_dialog_content = "<color=#e8d9bb>Tak ada yang melihat serangan Barton dengan jelas. Yang mereka lihat hanyalah kilatan perak.</color>",
  ui_story_5082_50820301_34_dialog_content = "<color=#e8d9bb>Di saat berikutnya, senjata para prajurit terbelah dua dan jatuh ke tanah.</color>",
  ui_story_5082_50820301_35_dialog_content = "Maaf, tapi kamu telah tereliminasi.",
  ui_story_5082_50820301_36_dialog_content = "Pulanglah dan pikirkan lama dan keras tentang apa yang telah kamu pelajari di sini.",
  ui_story_5082_50820301_37_dialog_content = "Siap, Pak...",
  ui_story_5082_50820301_38_dialog_content = "Dan untukmu, PlayerName.",
  ui_story_5082_50820301_39_dialog_content = "Mengapa wajah panjang? Mereka berbicara tentang kami, prajurit yang dimodifikasi, bukan kamu.",
  ui_story_5082_50820301_40_dialog_content = "Ini karena Anda menerima modifikasi Chord Link untuk melindungi kita semua...",
  ui_story_5082_50820301_41_dialog_content = "Kamu masih terlalu banyak berpikir untuk seseorang yang sangat lelah.",
  ui_story_5082_50820301_42_dialog_content = "Dengar, anak. Aku tidak setuju dengan modifikasi untuk melindungi kalian; aku melakukannya untuk menang.",
  ui_story_5082_50820301_43_dialog_content = "Dan kekuatan yang aku peroleh setelahnya adalah milikku sendiri. Kamu melihat kecepatanku saat aku menghindari serangan Grand Marshal sebelumnya, bukan?",
  ui_story_5082_50820301_44_dialog_content = "Masih sedikit sulit untuk dikendalikan, tapi semua kekuatan datang dengan harga. Menurutku, itu sangat masuk akal.",
  ui_story_5082_50820301_45_dialog_content = "Lagipula, siapa yang bisa bilang aku tidak akan menjadi orang yang membuat Grand Marshal terpojok setelah aku menguasai kekuatan ini? Hahaha!",
  ui_story_5082_50820301_46_dialog_content = "Saya senang tampaknya tidak mempengaruhi Anda... Tapi berbicara tentang Reinhardt...",
  ui_story_5082_50820301_47_dialog_content = "Ada yang tampak aneh tentang dirinya. Dia kehilangan fokus di tengah pertempuran begitu banyak kali hari ini.",
  ui_story_5082_50820301_48_dialog_content = "Tadi juga sama. Kita hanya bisa melarikan diri karena dia tiba-tiba berhenti menyerang.",
  ui_story_5082_50820301_49_dialog_content = "Kamu juga menyadarinya, eh... Kapanpun Grand Marshal masuk ke medan perang, dia cenderung menjadi pusat dari segalanya.",
  ui_story_5082_50820301_50_dialog_content = "Baik itu sekutu atau musuhnya, dia mampu mengendalikan alur pertempuran di sekitarnya.",
  ui_story_5082_50820301_51_dialog_content = "Tapi hari ini berbeda. Meskipun dia terus menyelamatkan situasi di akhir, dia pasti tidak mengendalikan situasi itu. Bahkan, tampaknya sebaliknya.",
  ui_story_5082_50820301_52_dialog_content = "Itu bukan sesuatu yang bisa disebabkan oleh \"kambuhnya\" luka lama.",
  ui_story_5082_50820301_53_dialog_content = "...",
  ui_story_5082_50820301_54_dialog_content = "...",
  ui_story_5082_50820301_55_dialog_content = "Aduh...",
  ui_story_5082_50820301_56_dialog_content = "Ada apa?",
  ui_story_5082_50820301_57_dialog_content = "Kupikir tiba-tiba aku merasakan sesuatu...",
  ui_story_5082_50820301_58_dialog_content = "Di tempat seperti ini?",
  ui_story_5082_50820301_59_dialog_content = "Aku akan mencoba untuk mendapatkan bacaan yang lebih baik!",
  ui_story_5082_50820301_60_option_content = "Pemindaian Psikis!",
  ui_story_5082_50820301_61_dialog_content = "Dimana tadi itu...?",
  ui_story_5082_50820301_62_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_5082_50820301_63_dialog_content = "Tanah... Apakah itu berguncang?",
  ui_story_5082_50820301_64_dialog_content = "Kehadiran yang baru saja aku rasakan... Aku tidak mengenalinya, tapi merasa aneh karena terasa begitu familier.",
  ui_story_5082_50820301_65_dialog_content = "... Itu dia.",
  ui_story_5082_50820301_66_dialog_content = "Ini dia!",
  ui_story_5082_50820301_67_dialog_content = "Kamu siapa? Dan kenapa kamu di sini?",
  ui_story_5082_50820301_68_dialog_content = "Itu gadis itu...",
  ui_story_5082_50820301_69_dialog_content = "Seorang gadis? Siapa yang kamu bicarakan?",
  ui_story_5082_50820301_70_dialog_content = "Gadis dengan seekor naga di belakangnya!",
  ui_story_5082_50820301_71_dialog_content = "Apa yang kamu-",
  ui_story_5082_50820301_72_dialog_content = "Awas, PlayerName!",
  ui_story_5082_50820301_73_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5082_50820302_1_dialog_content = "PlayerName! Apa kamu baik-baik saja?!",
  ui_story_5082_50820302_2_dialog_content = "*batuk* Aku baik-baik saja... Terima kasih, Barton.",
  ui_story_5082_50820302_3_dialog_content = "Tapi apa yang membuat bangunan ini runtuh? Sepanjang yang bisa saya lihat, tidak ada pertempuran di dekat sini.",
  ui_story_5082_50820302_4_dialog_content = "Ayo lihat ini.",
  ui_story_5082_50820302_5_dialog_content = "... Ruang yang sangat luas! Semuanya rusak parah... Pertempuran macam apa yang bisa terjadi di sini?",
  ui_story_5082_50820302_6_dialog_content = "Kami begitu fokus pada latihan sehingga kami tidak pernah menyadarinya.",
  ui_story_5082_50820302_7_dialog_content = "Tetapi jika pertempuran seperti ini terjadi begitu dekat dengan Kota Gannon, tidak mungkin kami melewatkannya.",
  ui_story_5082_50820302_8_dialog_content = "Atau mungkin ini terjadi saat runtuh saat itu...?",
  ui_story_5082_50820302_9_dialog_content = "Benar, aku baru saja merasakan kehadiran yang aneh!",
  ui_story_5082_50820302_10_dialog_content = "Itu terus mengatakan hal-hal yang tidak bisa saya mengerti. Mungkin itu ada hubungannya dengan tempat ini?",
  ui_story_5082_50820302_11_dialog_content = "Aku akan mencoba merasakannya lagi—",
  ui_story_5082_50820302_12_dialog_content = "Silakan tunggu sebentar.",
  ui_story_5082_50820302_13_dialog_content = "... Vivian? Apa yang kamu lakukan di sini?",
  ui_story_5082_50820302_14_dialog_content = "Jangan bilang kami membuat terlalu banyak kebisingan? Ha ha ha! Jangan khawatir, saya sudah menyelesaikan masalahnya.",
  ui_story_5082_50820302_15_dialog_content = "Tapi jika kamu semua di sini, apakah itu berarti kamu mencari pertandingan ulang, Grand Marshal?",
  ui_story_5082_50820302_16_dialog_content = "Mungkin lain kali.",
  ui_story_5082_50820302_17_dialog_content = "Jangan membuat hal-hal menjadi sulit untuk Grand Marshal, Barton.",
  ui_story_5082_50820302_18_dialog_content = "Saya datang untuk berbagi pemberitahuan penting dari markas besar. Saya sudah memberitahu Grand Marshal dan Philyshy tentang hal itu.",
  ui_story_5082_50820302_19_dialog_content = "Bagaimana situasinya?",
  ui_story_5082_50820302_20_dialog_content = "Karena kelalaian dalam pencatatan, kami baru saja menyadari bahwa area ini benar-benar terlarang.",
  ui_story_5082_50820302_21_dialog_content = "Dan mengingat memburuknya luka lama Grand Marshal, kami merasa bahwa melanjutkan latihan akan berakibat pada kerusakan lebih lanjut—",
  ui_story_5082_50820302_22_dialog_content = "Oleh karena itu, dengan menyesal saya informasikan bahwa latihan ini sekarang telah berakhir.",
  ui_story_5082_50820302_23_dialog_content = "Tapi, baru saja aku merasakan...",
  ui_story_5082_50820302_24_dialog_content = "Kami akan menangani sisa masalah ini, jadi harap mengerti, PlayerName. Ini adalah area terbatas, setelah semua.",
  ui_story_5082_50820302_25_dialog_content = "(Reinhardt tampak begitu serius. Apakah sesuatu terjadi kembali di Kota Gannon...?)",
  ui_story_5082_50820302_26_dialog_content = "... Bagus.",
  ui_story_5082_50820302_27_dialog_content = "Apakah benar-benar sudah berakhir? Dan saya baru saja mulai merasa hangat juga!",
  ui_story_5082_50820302_28_dialog_content = "Saya merasa bosan luar biasa menjalankan pasukan saya melalui latihan yang sama setiap hari.",
  ui_story_5082_50820302_29_dialog_content = "Kontes ini merupakan perubahan tempo yang menyenangkan. Menarik steker seperti ini meninggalkan rasa buruk di mulut saya.",
  ui_story_5082_50820302_30_dialog_content = "Saya setuju. Meskipun latihan harus berakhir, saya benci merusak kesenangan semua orang.",
  ui_story_5082_50820302_31_dialog_content = "Karena semua orang sudah ada di sini, kenapa kita tidak merayakan dengan api unggun malam ini saja?",
  ui_story_5082_50820302_32_dialog_content = "Aku bisa meninggalkan persiapan kepada kamu, benar Barton?",
  ui_story_5082_50820302_33_dialog_content = "... Hei, kamu adalah bos di sini, bukan? Tentu saja aku bisa menanganinya! Aku akan meminta bawahan ku untuk mulai memindahkan barang segera!",
  ui_story_5082_50820302_34_dialog_content = "Lalu aku akan pergi dengan—",
  ui_story_5082_50820302_35_dialog_content = "Oh tidak! Kamu harus ikut denganku dulu!",
  ui_story_5082_50820302_36_dialog_content = "H-Hey! Jangan hanya menyeret saya pergi, Philyshy! Dan di mana kamu selama ini, sebenarnya?!",
  ui_story_5082_50820302_37_dialog_content = "Bermalas-malasan, tentu saja... Tapi sepertinya bahkan saya pun belum tahu tentang tempat ini, meong.",
  ui_story_5082_50820302_38_dialog_content = "Aku mendengar mereka berbicara barusan.",
  ui_story_5082_50820302_39_dialog_content = "\"Kami tidak menyembunyikan apa pun dari mereka. Ini hanya bukan waktu yang tepat, itu saja.\" Itulah yang saya dengar Grand Marshal Reinhardt dan Officer Vivian katakan.",
  ui_story_5082_50820302_40_dialog_content = "Sekarang cepat gunakan kekuatan psikismu, PlayerName! Aku ingin mendengar apa yang mereka bicarakan sekarang!",
  ui_story_5082_50820302_41_dialog_content = "Itu bukanlah tujuan dari kekuatanku, Philyshy!",
  ui_story_5082_50820302_42_dialog_content = "Nyeh, kamu ini benar-benar perusak suasana. Baiklah, aku akan melakukannya sendiri!",
  ui_story_5082_50820302_43_dialog_content = "Dan dia sudah pergi... Tidak ada yang bisa menghentikannya saat dia penasaran tentang sesuatu, huh?",
  ui_story_5082_50820302_44_dialog_content = "(Masih, aku bertanya-tanya apa yang terjadi pada Reinhardt...)",
  ui_story_5082_50820401_1_dialog_content = "<color=#e8d9bb>Di tengah malam, saat unggun api...</color>",
  ui_story_5082_50820401_2_dialog_content = "... Ayo.",
  ui_story_5082_50820401_3_dialog_content = "Kehadiran itu... Kamu lagi!",
  ui_story_5082_50820401_4_dialog_content = "Kamu adalah orang yang merasakanku... Caelestite.",
  ui_story_5082_50820401_5_dialog_content = "Kau mengenalku? Siapa kamu? Dan mengapa kamu menghubungi saya?",
  ui_story_5082_50820401_6_dialog_content = "Bantu aku meninggalkan tempat ini.",
  ui_story_5082_50820401_7_dialog_content = "!!!",
  ui_story_5082_50820401_8_dialog_content = "Anda adalah Colossus?!",
  ui_story_5082_50820401_9_dialog_content = "Mereka memanggilku Tombak Utama.",
  ui_story_5082_50820401_10_dialog_content = "Kapan Illumina mendapatkan Colossus yang memiliki kesadaran?!",
  ui_story_5082_50820401_11_dialog_content = "Tunggu sebentar... Sebuah Colossus yang berakal... Apakah itu berarti kamu memiliki Navigator Caelestite seperti aku?",
  ui_story_5082_50820401_12_dialog_content = "&>!#%$^!#$",
  ui_story_5082_50820401_13_dialog_content = "Illumina! Orang-orang mereka tidak bisa dipercaya!",
  ui_story_5082_50820401_14_dialog_content = "Mereka memenjarakanku! Mengubahku! Mereka ingin menjadikanku sebagai senjata perang!",
  ui_story_5082_50820401_15_dialog_content = "Aku mencoba melarikan diri berkali-kali, hanya untuk hancur dalam upaya terakhirku.",
  ui_story_5082_50820401_16_dialog_content = "Itu gadis itu... gadis dengan $^%%$ di belakangnya!",
  ui_story_5082_50820401_17_dialog_content = "(Seorang gadis? Dan ada sesuatu di belakangnya...?)",
  ui_story_5082_50820401_18_dialog_content = "^#!^#%$&&! ^&*tite... Temui aku.",
  ui_story_5082_50820401_19_dialog_content = "Temui aku.",
  ui_story_5082_50820401_20_dialog_content = "Di mana kau?",
  ui_story_5082_50820401_21_dialog_content = "Datang temukan aku. Bantu aku pergi—",
  ui_story_5082_50820401_22_dialog_content = "Tunggu, saya masih punya lebih banyak pertanyaan untuk Anda!",
  ui_story_5082_50820401_23_dialog_content = "Tentang Caelestite dan Eraveil! Tentang Soroz dan—",
  ui_story_5082_50820401_24_dialog_content = "Maka temuilah aku—",
  ui_story_5082_50820401_25_dialog_content = "Hei!",
  ui_story_5082_50820401_26_dialog_content = "Apa yang salah, anak? Sadarkan dirimu!",
  ui_story_5082_50820401_27_dialog_content = "Baru saja, aku...",
  ui_story_5082_50820401_28_dialog_content = "Heh, takut dengan mimpi sendiri eh? Sepertinya kamu benar-benar perlu lebih banyak latihan.",
  ui_story_5082_50820401_29_dialog_content = "Meong... Aku tahu semua tentang tidur yang banyak dan nyenyak. Kamu harus mencoba belajar dariku suatu saat nanti!",
  ui_story_5082_50820401_30_dialog_content = "Tadi... rasanya bukan seperti mimpi...",
  ui_story_5082_50820401_31_dialog_content = "Aku harus pergi mencarinya!",
  ui_story_5082_50820401_32_dialog_content = "Hei, kamu pikir kamu mau ke mana?! Setidaknya tunggu kami—",
  ui_story_5082_50820401_33_dialog_content = "*yawn* Sepertinya Grand Marshal atau Petugas Vivian juga tidak ada di sekitar.",
  ui_story_5082_50820401_34_dialog_content = "Meski aku hampir tidak bisa merasakannya, aku bisa mengatakan bahwa itu ada di arah ini. Reruntuhan tempat latihan kemarin dibatalkan...",
  ui_story_5082_50820401_35_dialog_content = "Huh? Aku mendengar suara-suara di depan...",
  ui_story_5082_50820401_36_dialog_content = "PlayerName? Bukankah sudah kubilang ini adalah area terlarang?",
  ui_story_5082_50820401_37_dialog_content = "Tidak apa-apa, Vivian. PlayerName tidak akan terburu-buru ke sini jika bukan karena alasan yang baik.",
  ui_story_5082_50820401_38_dialog_content = "Reinhardt, Vivian... Aku...",
  ui_story_5082_50820401_39_dialog_content = "Ini adalah rapat yang cukup besar, dan di tengah malam pula. Apakah kita sedang memutuskan apakah akan memulai kembali latihan atau tidak?",
  ui_story_5082_50820401_40_dialog_content = "Saya lebih suka tidur, tapi bukan jika itu berarti melewatkan sesuatu yang penting.",
  ui_story_5082_50820401_41_dialog_content = "Saya merasakan kehadiran Colossus di suatu tempat di dekat sini!",
  ui_story_5082_50820401_42_dialog_content = "!",
  ui_story_5082_50820401_43_dialog_content = "... Aku tahu itu.",
  ui_story_5082_50820401_44_dialog_content = "Katakanlah, ini bukan basis penelitian tempat eksperimen navigator cadangan diadakan, bukan?",
  ui_story_5082_50820401_45_dialog_content = "Basis riset... kamu maksud yang meledak beberapa tahun lalu itu?",
  ui_story_5082_50820401_46_dialog_content = "... Saya ingat Vice mengatakan bahwa dia berpartisipasi dalam sesuatu yang disebut \"Proyek: Navigator.\"",
  ui_story_5082_50820401_47_dialog_content = "Tapi tampaknya proyek itu gagal, dan Vice kehilangan sebagian besar ingatannya dari sebelum dan sesudah waktu itu.",
  ui_story_5082_50820401_48_dialog_content = "Apakah Illumina mencoba melatih seseorang untuk menjadi Navigator Spearhead?",
  ui_story_5082_50820401_49_dialog_content = "Tunggu... Vice pasti masih gadis kecil saat itu terjadi, bukan?",
  ui_story_5082_50820401_50_dialog_content = "Semua dari kamu benar. Selama Krisis Darkover, Illumina meluncurkan program tersebut untuk meningkatkan peluang kita untuk masa depan yang lebih cerah.",
  ui_story_5082_50820401_51_dialog_content = "Tapi kami kehilangan terlalu banyak orang, dan basis penelitian itu tertimbun di bawah tanah. Catatan kami tentang insiden itu juga sedikit dan jarang...",
  ui_story_5082_50820401_52_dialog_content = "Program tersebut membawa malu bagi seluruh Illumina dan bagi saya... Tidak mampu melakukan penyelidikan lanjutan meskipun saya terlibat dalam program itu bahkan lebih memalukan.",
  ui_story_5082_50820401_53_dialog_content = "... Apakah itu berarti kamu berpartisipasi dalam percobaan bersama dengan Vice.",
  ui_story_5082_50820401_54_dialog_content = "Tidak. Akulah yang menghancurkannya.",
  ui_story_5082_50820401_55_dialog_content = "...",
  ui_story_5082_50820401_56_dialog_content = "Mereka bilang aku telah menyelamatkan Vice, tapi sejujurnya, semuanya tidak terasa begitu nyata bagiku.",
  ui_story_5082_50820401_57_dialog_content = "Dan itulah yang saya rasakan hingga pertempuran kemarin dengan Barton. Ketika kita bertarung, kenangan mulai muncul di pikiran saya...",
  ui_story_5082_50820401_58_dialog_content = "Rasanya seperti ada rahasia yang terkubur di sini, jadi aku datang untuk melihat sendiri.",
  ui_story_5082_50820401_59_dialog_content = "Apa yang baru saja kamu katakan telah mengkonfirmasi kecurigaanku, PlayerName.",
  ui_story_5082_50820401_60_dialog_content = "Colossus itu tidak pernah dipindahkan dari tempat ini.",
  ui_story_5082_50820401_61_dialog_content = "—Itu tepat di bawah kaki kita.",
  ui_story_5082_50820401_62_dialog_content = "... Jika memang begitu, maka aku harus pergi melihatnya.",
  ui_story_5082_50820401_63_dialog_content = "Vice tidak pernah mengatakannya, tapi saya yakin siapa pun akan terganggu jika mereka kehilangan ingatan mereka.",
  ui_story_5082_50820401_64_dialog_content = "Dia telah membantu saya banyak sejak kita bertemu. Hanya benar bagi saya untuk melakukan sesuatu untuknya.",
  ui_story_5082_50820401_65_dialog_content = "Karena ini adalah area terbatas, membiarkan kamu masuk akan melanggar peraturan Illumina.",
  ui_story_5082_50820401_66_dialog_content = "Tapi—",
  ui_story_5082_50820401_67_dialog_content = "Namun, Grand Marshal juga hadir.",
  ui_story_5082_50820401_68_dialog_content = "Dengan persetujuannya, kamu mungkin diberikan izin untuk masuk.",
  ui_story_5082_50820401_69_dialog_content = "Aku memang berencana pergi ke sana. Aku tidak keberatan jika PlayerName ikut.",
  ui_story_5082_50820401_70_dialog_content = "Tapi kau harus berjanji sesuatu padaku.",
  ui_story_5082_50820401_71_dialog_content = "Mungkin berbeda dari yang kamu ketahui, tetapi menurut laporan intelijen Illumina selama berabad-abad—",
  ui_story_5082_50820401_72_dialog_content = "Dari Colossi yang telah kamu temui sejauh ini, yang satu ini mungkin jauh lebih bermusuhan daripada yang kamu duga.",
  ui_story_5082_50820401_73_dialog_content = "Saya yakin itu tidak memiliki banyak hal baik untuk dikatakan tentang Illumina saat itu menghubungi kamu.",
  ui_story_5082_50820401_74_dialog_content = "... Benar.",
  ui_story_5082_50820401_75_dialog_content = "Setelah insiden dengan Insinyur, aku bersumpah tidak akan membiarkan kamu merasakan sesuatu yang berbahaya seperti itu lagi.",
  ui_story_5082_50820401_76_dialog_content = "Terutama ketika bahaya ditujukan pada Illumina.",
  ui_story_5082_50820401_77_dialog_content = "Tapi, mengatakan kepada kamu untuk tidak menggunakan kekuatan psikis unikmu sama saja dengan mengatakan kepada kamu untuk tidak bernapas.",
  ui_story_5082_50820401_78_dialog_content = "Yang saya minta hanyalah kamu memberitahu saya saat kamu merasakan sesuatu saat itu juga terjadi.",
  ui_story_5082_50820401_79_dialog_content = "Lalu, bolehkah aku juga membuat permintaan?",
  ui_story_5082_50820401_80_dialog_content = "Silakan, saya mendengarkan.",
  ui_story_5082_50820401_81_dialog_content = "Aku tidak akan mencoba menyembunyikan apa pun yang aku rasakan, tetapi aku ingin semua orang mengikuti aturan yang sama.",
  ui_story_5082_50820401_82_dialog_content = "Apakah ada sesuatu yang terasa aneh, atau jika kamu merasa sedikit aneh...",
  ui_story_5082_50820401_83_dialog_content = "Meskipun kamu berpikir itu bukan masalah besar, tolong beri tahu grup segera. Dengan begitu, kita bisa mencari solusi bersama-sama.",
  ui_story_5082_50820401_84_dialog_content = "Kamu jadi jauh lebih dewasa dari saat kita pertama kali bertemu.",
  ui_story_5082_50820401_85_dialog_content = "Sepakat.",
  ui_story_5082_50820401_86_dialog_content = "Aku tidak terlalu peduli tentang insiden ini, tetapi itu memiliki efek besar dan berkelanjutan pada Illumina. Jika kamu akan menyelidikinya, maka hitunglah aku di dalamnya.",
  ui_story_5082_50820401_87_dialog_content = "Sejujurnya, saya tidak terlalu merasa ingin bergabung dengan semua orang.",
  ui_story_5082_50820401_88_dialog_content = "Tetapi reruntuhan ini menyembunyikan sesuatu yang ingin saya ketahui, jadi saya rasa saya akan ikut juga.",
  ui_story_5082_50820401_89_dialog_content = "Kami hanya kebetulan menuju ke arah yang sama, jadi jangan harap saya akan banyak membantu!",
  ui_story_5082_50820401_90_dialog_content = "Apa yang akan kita lakukan denganmu, Philyshy...",
  ui_story_5082_50820401_91_dialog_content = "Baiklah, cukup berkeliling. Saya akan memimpin jalan, sekarang mari kita pergi!",
  ui_story_5082_50820401_92_dialog_content = "Sepertinya aku harus mencari jalur terlebih dahulu, Barton. Jangan khawatir, aku tidak akan mencoba merasakan Colossus.",
  ui_story_5082_50820401_93_dialog_content = "Aku hanya akan melihat sekeliling kita untuk memastikan mereka aman sebelum kita melanjutkan.",
  ui_story_5082_50820401_94_dialog_content = "*Uhuk* Ruang di bawah kita ini luas, tapi sebagian besar hanya puing-puing...",
  ui_story_5082_50820401_95_dialog_content = "<color=#e8d9bb>Hancur...</color>",
  ui_story_5082_50820401_96_dialog_content = "Waow! Barusan aku hampir tersandung.",
  ui_story_5082_50820401_97_dialog_content = "Tanahnya dipenuhi kabel. Perhatikan langkahmu, semuanya.",
  ui_story_5082_50820401_98_dialog_content = "<color=#e8d9bb>Bzzz—</color>",
  ui_story_5082_50820401_99_dialog_content = "Suara apa itu?",
  ui_story_5082_50820401_100_dialog_content = "Meong! Ada sesuatu yang terbang ke arah kita!",
  ui_story_5082_50820401_101_dialog_content = "Ngungg—",
  ui_story_5082_50820401_102_dialog_content = "Hindari itu, PlayerName!",
  ui_story_5082_50820401_103_dialog_content = "—!",
  ui_story_5082_50820401_104_dialog_content = "...",
  ui_story_5082_50820401_105_dialog_content = "PlayerName? PlayerName!",
  ui_story_5082_50820401_106_dialog_content = "Saya pikir saya mendengar seseorang meneriakkan namaku.",
  ui_story_5082_50820501_1_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820501_2_dialog_content = "Itu... terompet?",
  ui_story_5082_50820501_3_dialog_content = "Aku bersumpah aku mendengar seorang gadis berteriak barusan... Huh?",
  ui_story_5082_50820501_4_dialog_content = "Apakah ini... akademi militer?",
  ui_story_5082_50820501_5_dialog_content = "Whoa! Reinhardt menang lagi!!",
  ui_story_5082_50820501_6_dialog_content = "Reinhardt?",
  ui_story_5082_50820501_7_dialog_content = "Ada orang lain yang merasa ingin melangkah?",
  ui_story_5082_50820501_8_dialog_content = "Berhenti sejenak, Reinhardt. Kamu sudah mengalahkan semua orang di sekolah ini; tidak ada yang cukup bodoh untuk menantangmu lagi.",
  ui_story_5082_50820501_9_dialog_content = "Ya, tapi kamu masih belum menyerah, kan?",
  ui_story_5082_50820501_10_dialog_content = "Aku hanya tidak merasa seperti mengalahkanmu dalam sesuatu yang sebodoh panco.",
  ui_story_5082_50820501_11_dialog_content = "Instruktur kami mengatakan bahwa kita akan menjalani lintasan halangan setelah kelas hari ini. Itulah saatnya aku akhirnya akan menempatkanmu pada posisimu.",
  ui_story_5082_50820501_12_dialog_content = "Reinhardt lagi-lagi mendapatkan tempat pertama di lintasan rintangan! Orang di tempat kedua bahkan lebih lambat lebih dari sepuluh detik!",
  ui_story_5082_50820501_13_dialog_content = "Itu tidak mengherankan. Kapan dia TIDAK ada di tempat pertama?",
  ui_story_5082_50820501_14_dialog_content = "Jadi, siapa yang datang kedua? Jangan bilang itu Wrath lagi?",
  ui_story_5082_50820501_15_dialog_content = "Pastilah itu!",
  ui_story_5082_50820501_16_dialog_content = "Selalu seperti ini sejak saya bergabung dengan akademi dan menjadi teman sekelas mereka. Setiap kontes selalu berakhir sama persis untuk mereka.",
  ui_story_5082_50820501_17_dialog_content = "Sejujurnya, aku merasa sangat tidak berguna dibandingkan dengan mereka.",
  ui_story_5082_50820501_18_dialog_content = "Cologne, Vaughn.",
  ui_story_5082_50820501_19_dialog_content = "Apakah aku mendengar halusinasi, atau apakah Reinhardt baru saja menyebut nama kita?",
  ui_story_5082_50820501_20_dialog_content = "Aku cukup yakin aku juga mendengarnya.",
  ui_story_5082_50820501_21_dialog_content = "Itu karena saya yang memanggil kalian, sekarang ke sini!",
  ui_story_5082_50820501_22_dialog_content = "Ke-Kenapa...",
  ui_story_5082_50820501_23_dialog_content = "Mengapa Reinhardt tahu nama-nama kita?!",
  ui_story_5082_50820501_24_dialog_content = "Saya baru saja menonton pertempuran simulasi kelas Anda.",
  ui_story_5082_50820501_25_dialog_content = "Cologne, keterampilan logistikmu adalah salah satu yang paling efektif yang pernah aku lihat dalam setahun ini.",
  ui_story_5082_50820501_26_dialog_content = "Dan Vaughn, kecepatan reaksimu juga bukan hal yang bisa ditertawakan.",
  ui_story_5082_50820501_27_dialog_content = "Jadi, saya pikir saya akan datang dan menyapa. Jika ada kesempatan, saya sangat ingin bekerja sama dengan kalian berdua.",
  ui_story_5082_50820501_28_dialog_content = "Reinhardt! Pengajar memerintahkan kita untuk berkumpul!",
  ui_story_5082_50820501_29_dialog_content = "Aku harus pergi! Sampai jumpa nanti, teman-teman!",
  ui_story_5082_50820501_30_dialog_content = "Reinhardt... mengatakan dia terkesan dengan kita.",
  ui_story_5082_50820501_31_dialog_content = "Hei... Haruskah kita lari beberapa putaran di sekitar lintasan?",
  ui_story_5082_50820501_32_dialog_content = "Ya! Mari kita lakukan! Sekarang juga!",
  ui_story_5082_50820501_33_dialog_content = "Masuk!",
  ui_story_5082_50820501_34_dialog_content = "Kalian semua telah ditugaskan untuk misi yang mendesak.",
  ui_story_5082_50820501_35_dialog_content = "Baru-baru ini, sejumlah Undercity, termasuk Undercity 38, 42, dan 59, telah diserang secara bersamaan oleh jenis baru Eclipsite.",
  ui_story_5082_50820501_36_dialog_content = "Eclipsite baru ini tidak terlalu kuat, tetapi mereka menutupi kekurangan itu dengan jumlah mereka yang luar biasa banyak dan masih terus bertambah. Kondisi hidup dan produktivitas Undercity ini sudah sangat terpengaruh!",
  ui_story_5082_50820501_37_dialog_content = "Kamu akan dibagi menjadi tiga tim kecil dan dikirim ke Undercity berikut untuk memberikan dukungan.",
  ui_story_5082_50820501_38_dialog_content = "Siap, Pak!",
  ui_story_5082_50820501_39_dialog_content = "...",
  ui_story_5082_50820501_40_dialog_content = "<color=#e8d9bb>Setelah krisis berakhir</color>",
  ui_story_5082_50820501_41_dialog_content = "Reinhardt!",
  ui_story_5082_50820501_42_dialog_content = "Perintahmu adalah memimpin timmu ke Undercity 42 dan memberikan bala bantuan! Apa yang kamu lakukan di Undercity 28?!",
  ui_story_5082_50820501_43_dialog_content = "Pak! Ketika kami diberi tugas, saya perhatikan bahwa Undercity yang dimaksud cukup jauh satu sama lain.",
  ui_story_5082_50820501_44_dialog_content = "Untuk jenis Eclipsite yang sama muncul di setiap Undercity pada saat yang sama, itu harus berarti ada semacam koneksi di antara mereka.",
  ui_story_5082_50820501_45_dialog_content = "Setelah tiba di Undercity 42 dan mengusir para Eclipsite di sana, saya menentukan bahwa mereka sangat rentan terhadap serangan.",
  ui_story_5082_50820501_46_dialog_content = "Namun, saya menemukan keberadaan Eclipsite unik di tengah mereka, satu yang bergerak cepat dan tampaknya mampu melakukan regenerasi dengan cepat!",
  ui_story_5082_50820501_47_dialog_content = "Setelah observasi lebih lanjut, saya mengkonfirmasi bahwa jenis Eclipsite ini memiliki beberapa karakteristik yang sama dengan tanaman spor.",
  ui_story_5082_50820501_48_dialog_content = "Dan setelah merujuk peta saya, saya menyadari bahwa semua Undercity ini langsung terhubung melalui jalur kereta api, dengan Undercity 28 di pusat mereka.",
  ui_story_5082_50820501_49_dialog_content = "Ini membuat saya percaya bahwa Eclipsite ini menyebar ke setiap Undercity yang terpengaruh melalui kereta rel kami, dan bahwa tubuh utama berada di suatu tempat di Undercity 28.",
  ui_story_5082_50820501_50_dialog_content = "Jadi saya membawa tim saya ke sini untuk memburu dan menghancurkan sumber dari invasi tersebut!",
  ui_story_5082_50820501_51_dialog_content = "Setelah itu, saya menerima konfirmasi dari Undercities lainnya bahwa jumlah Eclipsite tidak lagi bertambah.",
  ui_story_5082_50820501_52_dialog_content = "... Kamu menemukan! Kamu menentukan! Kamu mengamati!",
  ui_story_5082_50820501_53_dialog_content = "Saya tidak menanyakan apa yang telah kamu lakukan, Reinhardt! Saya menanyakan kenapa kamu melakukannya!!",
  ui_story_5082_50820501_54_dialog_content = "Apakah kau menganggap atasanmu itu sekumpulan orang bodoh? Apakah kau merasa menjadi prajurit terpintar di Illumina hanya karena kau berhasil mengungkap kebenaran?!",
  ui_story_5082_50820501_55_dialog_content = "Meninggalkan misimu, bertindak sendiri, dan mengabaikan perintah mendesak untuk mundur! Dan kau menyebut dirimu seorang prajurit?",
  ui_story_5082_50820501_56_dialog_content = "Saya sadar akan konsekuensi dari tindakan saya, dan siap menerima hukuman apa pun! Namun, saya masih percaya bahwa mencari sumber invasi Eclipsite secepat mungkin adalah pilihan tindakan terbaik!",
  ui_story_5082_50820501_57_dialog_content = "Keluar dari sini!!!",
  ui_story_5082_50820501_58_dialog_content = "!",
  ui_story_5082_50820501_59_dialog_content = "Apakah kamu menungguku atau sesuatu?",
  ui_story_5082_50820501_60_dialog_content = "Aku baru saja datang untuk menyerahkan laporan kerjaku kepada pengajar.",
  ui_story_5082_50820501_61_dialog_content = "... Apakah kamu baik-baik saja?",
  ui_story_5082_50820501_62_dialog_content = "Kenapa tidak? Aku baru saja dimarahi, itu saja.",
  ui_story_5082_50820501_63_dialog_content = "Aku berharap aku tahu mengapa instruktur itu menentangku.",
  ui_story_5082_50820501_64_dialog_content = "Benarkah itu yang ada di pikiranmu? Sudahlah.",
  ui_story_5082_50820501_65_dialog_content = "Di akhir hari, kita berdua dikirim ke Undercities untuk memberikan bantuan, tetapi saya gagal mencari tahu kebenaran di balik Eclipsite tersebut. Sepertinya kamu menang lagi, Reinhardt.",
  ui_story_5082_50820501_66_dialog_content = "Tapi catat kata-kataku! Aku tidak akan kalah darimu kali berikutnya!",
  ui_story_5082_50820501_67_dialog_content = "Tentu.",
  ui_story_5082_50820501_68_dialog_content = "... Apa itu? Saya menantang Anda, dan itu semua yang harus Anda katakan?",
  ui_story_5082_50820501_69_dialog_content = "Kamu menantang saya setiap hari, bukan?",
  ui_story_5082_50820501_70_dialog_content = "Itulah sebabnya aku selalu siap untuk apa pun.",
  ui_story_5082_50820501_71_dialog_content = "Jangan... Jangan coba-coba meremehkan tantanganku!",
  ui_story_5082_50820501_72_dialog_content = "Kau satu-satunya orang yang layak menjadi sainganku, jadi sampai aku mengalahkanmu, kau tidak boleh kalah dari orang lain!",
  ui_story_5082_50820501_73_dialog_content = "Haha, aku akan melakukan yang terbaik.",
  ui_story_5082_50820501_74_dialog_content = "(Jadi ini terjadi di masa lalu.)",
  ui_story_5082_50820501_75_dialog_content = "(Reinhardt dan Wrath sangat dekat selama hari-hari akademi mereka...)",
  ui_story_5082_50820501_76_dialog_content = "Kapten! Ini adalah darurat—",
  ui_story_5082_50820501_77_dialog_content = "(Adegan itu berubah lagi...)",
  ui_story_5082_50820501_78_dialog_content = "Hah…?",
  ui_story_5082_50820501_79_dialog_content = "Berhenti-!",
  ui_story_5082_50820501_80_dialog_content = "Latihan hari ini sudah selesai, sekarang kembali ke barakmu! Jam malam sudah berlaku, jadi tidak boleh keluar setelah gelap!",
  ui_story_5082_50820501_81_dialog_content = "Fiuh, senang itu sudah berakhir. Aku dipukul...",
  ui_story_5082_50820501_82_dialog_content = "Ini masih sedikit terlalu dini, bukan? Biasanya pengajar menambahkan latihan ekstra jika kita selesai secepat ini.",
  ui_story_5082_50820501_83_dialog_content = "Siapa peduli? Ini hanya berarti kita mendapatkan lebih banyak waktu untuk bersantai! Benar, Reinhardt?",
  ui_story_5082_50820501_84_dialog_content = "... Reinhardt?",
  ui_story_5082_50820501_85_dialog_content = "Hei! Kemana kamu pergi?",
  ui_story_5082_50820501_86_dialog_content = "Untuk masuk ke dalam masalah yang lebih besar.",
  ui_story_5082_50820501_87_dialog_content = "Lalu aku juga datang.",
  ui_story_5082_50820501_88_dialog_content = "Tidakkah kamu mendengar apa yang baru saja saya katakan?",
  ui_story_5082_50820501_89_dialog_content = "Apakah kamu meremehkanku?",
  ui_story_5082_50820501_90_dialog_content = "Jika kamu benar-benar sembrono dan tidak peduli, saya tidak akan menganggapmu sebagai saingan tidak peduli sekuat apa kamu.",
  ui_story_5082_50820501_91_dialog_content = "Pengajar itu menatapmu tajam barusan, dan namun kamu masih bertekad keras untuk menyelinap keluar. Mengapa? Apa yang kamu temukan?",
  ui_story_5082_50820501_92_dialog_content = "Invasi Eclipsite.",
  ui_story_5082_50820501_93_dialog_content = "Apa?!",
  ui_story_5082_50820501_94_dialog_content = "Auuuum!",
  ui_story_5082_50820501_95_dialog_content = "Komandan! Eclipsite terus datang, tetapi kita tidak memiliki cukup tentara untuk menahan mereka! Meminta—",
  ui_story_5082_50820501_96_dialog_content = "Tahan mereka meskipun itu menghabiskan nyawa kalian!",
  ui_story_5082_50820501_97_dialog_content = "Dari mana di dunia ini semua Eclipsite ini datang—",
  ui_story_5082_50820501_98_dialog_content = "Groar!",
  ui_story_5082_50820501_99_dialog_content = "Ah—",
  ui_story_5082_50820501_100_dialog_content = "Pertahankan barisan!",
  ui_story_5082_50820501_101_dialog_content = "Monster kotor sialan!",
  ui_story_5082_50820501_102_dialog_content = "Tembus semuanya!",
  ui_story_5082_50820501_103_dialog_content = "Serang! Richthofen!",
  ui_story_5082_50820501_104_dialog_content = "Sedang apa kau di sini?!",
  ui_story_5082_50820501_105_dialog_content = "Seperti yang sudah aku katakan, aku tak akan kalah darimu!",
  ui_story_5082_50820501_106_dialog_content = "Graaah...",
  ui_story_5082_50820501_107_dialog_content = "Murid-murid?",
  ui_story_5082_50820501_108_dialog_content = "Mahasiswa Akademi Militer Illumina Reinhardt, melapor untuk tugas dukungan!",
  ui_story_5082_50820501_109_dialog_content = "Mahasiswa Akademi Militer Illumina Wrath, melapor untuk tugas dukungan!",
  ui_story_5082_50820501_110_dialog_content = "Berhenti bermain-main dan kembali!",
  ui_story_5082_50820501_111_dialog_content = "Aku akan melaporkan secara pribadi kepada pengajarku setelah ini selesai, tetapi sebagai warga Illumina, aku menolak untuk berdiam diri sementara Eclipsite menyerang rumah kita!",
  ui_story_5082_50820501_112_dialog_content = "Tolong tugaskan saya untuk pertahanan sayap kiri!",
  ui_story_5082_50820501_113_dialog_content = "Dan tolong tugaskan saya ke yang benar!",
  ui_story_5082_50820501_114_dialog_content = "Kalian berdua? Ini semacam lelucon?!",
  ui_story_5082_50820501_115_dialog_content = "Kita bisa menang, aku janji.",
  ui_story_5082_50820501_116_dialog_content = "Juga, kami bukan satu-satunya yang di sini untuk membantu.",
  ui_story_5082_50820501_117_dialog_content = "Dua Eclipsite mencoba menyergap kita dari lubang jam satu! Serahkan mereka padaku!",
  ui_story_5082_50820501_118_dialog_content = "Legiun Medis akan menangani yang terluka parah! Kami akan memberikan pertolongan pertama pada luka ringan di sini!",
  ui_story_5082_50820501_119_dialog_content = "Izinkan saya memperkenalkan teman sekelas dan kawan seperjuangan saya: Vaughn dan Cologne.",
  ui_story_5082_50820501_120_dialog_content = "Sepertinya ini adalah kesempatan kita untuk akhirnya bekerja sama, Reinhardt!",
  ui_story_5082_50820501_121_dialog_content = "Mohon maaf, komandan, tetapi setiap prajurit memiliki tugas untuk mempertahankan Illumina, termasuk prajurit yang sedang dalam pelatihan!",
  ui_story_5082_50820501_122_dialog_content = "Haha, simpan saja permintaan maafmu untuk nanti!",
  ui_story_5082_50820501_123_dialog_content = "Ambillah senjatamu dan bersiaplah untuk menghadapi Eclipsites!",
  ui_story_5082_50820501_124_dialog_content = "Baik!",
  ui_story_5082_50820501_125_dialog_content = "Dan sejak kapan kamu dipromosikan menjadi komandan, hah?!",
  ui_story_5082_50820501_126_dialog_content = "... Reinhardt.",
  ui_story_5082_50820501_127_dialog_content = "<color=#e8d9bb>Hari berikutnya</color>",
  ui_story_5082_50820501_128_dialog_content = "Berkumpul dan mulailah pelatihan!",
  ui_story_5082_50820501_129_dialog_content = "Siap, Pak!",
  ui_story_5082_50820501_130_dialog_content = "Tidak mungkin. Apakah pengajar benar-benar membiarkan kita lolos setelah bencana kemarin?",
  ui_story_5082_50820501_131_dialog_content = "Reinhardt dan Wrath tampaknya juga tidak dalam masalah, tetapi itu malah membuatku semakin gelisah...",
  ui_story_5082_50820501_132_dialog_content = "Tunggu, lihat! Bukankah itu Commander 1st Legion? Apa yang dia lakukan di sini?!",
  ui_story_5082_50820501_133_dialog_content = "Siswa Akademi Reinhardt! Mundur dan laporkan ke kantor pengajarmu!",
  ui_story_5082_50820501_134_dialog_content = "Siap, Pak!",
  ui_story_5082_50820501_135_dialog_content = "...",
  ui_story_5082_50820501_136_dialog_content = "<color=#e8d9bb>Ruang Perang No. 3</color>",
  ui_story_5082_50820501_137_dialog_content = "Salam, Komandan!",
  ui_story_5082_50820501_138_dialog_content = "Karena kinerja individu Anda yang luar biasa, kami telah menyiapkan serangkaian eksperimen pelatihan khusus hanya untuk Anda.",
  ui_story_5082_50820501_139_dialog_content = "Groar!",
  ui_story_5082_50820501_140_dialog_content = "Eclipsite subjek uji ini adalah bagian penting dari pelatihan.",
  ui_story_5082_50820501_141_dialog_content = "Dalam beberapa saat, saya akan melepaskan mereka ke area pertempuran. Saya ingin kamu melawan mereka dengan menggunakan seluruh kekuatanmu.",
  ui_story_5082_50820501_142_dialog_content = "Tch... Orang-orang ini memukul cukup keras.",
  ui_story_5082_50820501_143_dialog_content = "Eclipsite yang sedang kamu hadapi saat ini adalah spesimen terlemah dalam eksperimen.",
  ui_story_5082_50820501_144_dialog_content = "Pelatihan ini dirancang untuk membentuk kamu menjadi prajurit paling kuat Illumina. Jika kamu tidak mampu mengalahkan mereka, kami harus mempertimbangkan kembali kandidatmu untuk program ini.",
  ui_story_5082_50820501_145_dialog_content = "Prajurit terkuat Illumina, huh? Heh... Siapa bilang aku tidak bisa mengalahkan mereka?!",
  ui_story_5082_50820501_146_dialog_content = "Ayo, lagi!",
  ui_story_5082_50820502_1_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5082_50820502_2_dialog_content = "Kamu menyebut itu pukulan?! Berhenti menahan diri sudah!",
  ui_story_5082_50820502_3_dialog_content = "Hahaha, maaf. Ayo kita coba lagi.",
  ui_story_5082_50820502_4_dialog_content = "Kamu itu... Tunggu, apa yang terjadi dengan tanganmu?!",
  ui_story_5082_50820502_5_dialog_content = "Ini dari kemarin—",
  ui_story_5082_50820502_6_dialog_content = "Siswa Akademi Reinhardt! Mundur dan laporkan ke fasilitas pelatihan khusus!",
  ui_story_5082_50820502_7_dialog_content = "Siap, Jenderal.",
  ui_story_5082_50820502_8_dialog_content = "Pengajar! Tangan Reinhardt terluka parah sehingga tidak bisa melanjutkan latihan! Tolong beri dia waktu sehari untuk pulih!",
  ui_story_5082_50820502_9_dialog_content = "Siswa Akademi Reinhardt! Laporkan diri ke fasilitas pelatihan khusus!",
  ui_story_5082_50820502_10_dialog_content = "Pengajar—",
  ui_story_5082_50820502_11_dialog_content = "Wrath.",
  ui_story_5082_50820502_12_dialog_content = "Pengajar! Mohon maaf mengganggu, tapi berapa lama lagi pelatihan khusus Reinhardt akan berlanjut?",
  ui_story_5082_50820502_13_dialog_content = "Seorang prajurit bersumpah untuk menjalankan perintah mereka. Dia akan melanjutkan latihannya selama perintahnya menentukan!",
  ui_story_5082_50820502_14_dialog_content = "... Baik, Pak.",
  ui_story_5082_50820502_15_dialog_content = "(Tangannya... Apakah ini bisa jadi \"luka lama\" Reinhardt yang disebutkan sebelumnya?)",
  ui_story_5082_50820502_16_dialog_content = "(Tidak peduli seberapa spesial latihan itu, tidak sebanding dengan melakukan ini pada tubuhmu sendiri.)",
  ui_story_5082_50820502_17_dialog_content = "(Eclipsite tak peduli tanganmu terluka.)",
  ui_story_5082_50820502_18_dialog_content = "(Itukah suara pengajar itu?)",
  ui_story_5082_50820502_19_dialog_content = "(... Akademi mendapatkan bagian dari pengacau setiap tahun, tetapi ini adalah pertama kalinya saya melihat siswa yang menjanjikan mengabaikan perintah dengan impunitas absolut...)",
  ui_story_5082_50820502_20_dialog_content = "(Kamu pantas ditempatkan pada posisimu lebih dari siapa pun! Jika kamu sangat suka melawan Eclipsite, kami akan membiarkan kamu melawan mereka sampai puas!)",
  ui_story_5082_50820502_21_dialog_content = "(Orang ini buruk sekali!)",
  ui_story_5082_50820502_22_dialog_content = "—!",
  ui_story_5082_50820502_23_dialog_content = "(Itu teriakan gadis itu lagi.)",
  ui_story_5082_50820502_24_dialog_content = "(Siapa mungkin dia—)",
  ui_story_5082_50820502_25_dialog_content = "!",
  ui_story_5082_50820601_1_dialog_content = "Woah!",
  ui_story_5082_50820601_2_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5082_50820601_3_dialog_content = "Sebuah batu besar...",
  ui_story_5082_50820601_4_dialog_content = "Itu nyaris saja! Jika PlayerName menyadarinya satu detik lebih cepat, kita semua akan sejatuh pancake sekarang ini!",
  ui_story_5082_50820601_5_dialog_content = "Aku akan pergi mengintai di depan. Kalian semua tunggu di sini untukku.",
  ui_story_5082_50820601_6_dialog_content = "Aku akan pergi denganmu.",
  ui_story_5082_50820601_7_dialog_content = "Apa itu, PlayerName? Kamu tampak seperti memiliki sesuatu untuk dikatakan.",
  ui_story_5082_50820601_8_dialog_content = "Batu besar itu barusan... Aku sama sekali tidak menyadarinya.",
  ui_story_5082_50820601_9_dialog_content = "Aku merasakan ada gadis tadi... Atau setidaknya aku pikir begitu. Bagaimanapun juga, dia membuatku terkejut hingga melompat ke samping.",
  ui_story_5082_50820601_10_dialog_content = "Apakah dia... Bercahaya merah, mungkin?",
  ui_story_5082_50820601_11_dialog_content = "Kok kau tahu?",
  ui_story_5082_50820601_12_dialog_content = "Karena aku melihatnya dalam ingatanku kemarin.",
  ui_story_5082_50820601_13_dialog_content = "...",
  ui_story_5082_50820601_14_dialog_content = "Kau punya sesuatu untuk diberitahukan kepadaku sejak kemarin, bukan?",
  ui_story_5082_50820601_15_dialog_content = "Bukan hanya aku.",
  ui_story_5082_50820601_16_dialog_content = "Barton, Philyshy... Semua orang mengkhawatirkanmu.",
  ui_story_5082_50820601_17_dialog_content = "Apakah benar-benar begitu jelas bahwa ada sesuatu yang salah denganku?",
  ui_story_5082_50820601_18_dialog_content = "Saya menghargai kepedulianmu, tetapi tidak perlu khawatir seperti ini, PlayerName.",
  ui_story_5082_50820601_19_dialog_content = "Aku tidak punya waktu untuk membuang-buang pada sentimentalitas, dan bukan berarti aku tidak bisa memberitahumu tentang apa yang terjadi.",
  ui_story_5082_50820601_20_dialog_content = "Selama latihan kemarin, aku tiba-tiba teringat banyak hal yang sama sekali tidak kuingat.",
  ui_story_5082_50820601_21_dialog_content = "Orang-orang, tempat-tempat, emosi... semuanya terasa begitu asing.",
  ui_story_5082_50820601_22_dialog_content = "Sayangnya, kenangan itu berkelebat di pikiranku begitu cepat sehingga aku tidak bisa memastikan... Apakah aku benar-benar menembak mati gadis itu atau tidak.",
  ui_story_5082_50820601_23_dialog_content = "M-Membunuhnya...?! Apakah ini \"rahasia terpendam\" yang kamu bicarakan? Jadi itu teriakan yang kudengar sebelumnya...",
  ui_story_5082_50820601_24_dialog_content = "Kenangan-kenangan itu masih terlalu terpecah-pecah untuk aku mengerti... Aku bahkan tidak bisa mengingat namanya.",
  ui_story_5082_50820601_25_dialog_content = "Yang aneh, mengingat aku ingat setiap orang yang menghadiri akademi bersamaku.",
  ui_story_5082_50820601_26_dialog_content = "Akademi? Itu benar. Saya juga memiliki beberapa kenangan dari hari-hari pelatihan Anda.",
  ui_story_5082_50820601_27_dialog_content = "Tapi gadis itu tidak pernah muncul di mana pun.",
  ui_story_5082_50820601_28_dialog_content = "Ah! M-Maaf, saya tidak bermaksud mengungkit masa lalu Anda seperti itu.",
  ui_story_5082_50820601_29_dialog_content = "Tidak masalah, aku tidak terlalu peduli. Meski begitu, aku penasaran mendengar tentang apa yang kamu lihat di ingatanku.",
  ui_story_5082_50820601_30_dialog_content = "Nah, ada bagian di mana kamu beradu tenaga dalam gulat tangan dengan orang-orang di lapangan latihan... Dan ada bagian di mana kamu menyelamatkan beberapa Undercity dengan tidak mematuhi perintah komandamu...",
  ui_story_5082_50820601_31_dialog_content = "Aku juga melihat apa yang terjadi padamu selama \"latihan khusus\"mu...",
  ui_story_5082_50820601_32_dialog_content = "Haha, sepertinya aku memang ingat semua hal itu terjadi.",
  ui_story_5082_50820601_33_dialog_content = "Saya masih muda dan sombong saat itu. Saya pikir saya bisa menyelesaikan setiap masalah sendiri.",
  ui_story_5082_50820601_34_dialog_content = "Apakah kamu yakin tidak melihat gadis itu di salah satu memori tersebut?",
  ui_story_5082_50820601_35_dialog_content = "Saya yakin...",
  ui_story_5082_50820601_36_dialog_content = "Mengapa tidak mencoba bertanya kepada teman baikmu Philyshy tentang hal itu? Lagipula, saya sering berurusan dengan hal semacam ini!",
  ui_story_5082_50820601_37_dialog_content = "Kami telah melewati berbagai jenis petualangan bersama, namun entah bagaimana orang-orang berhasil melupakan Yumi.",
  ui_story_5082_50820601_38_dialog_content = "Saya pikir situasi Reinhardt sedikit berbeda, Philyshy.",
  ui_story_5082_50820601_39_dialog_content = "Saya pikir Komite mungkin tahu lebih banyak tentang kenangan-kenangan ini... Lagipula, mereka berhutang banyak kepadaku.",
  ui_story_5082_50820601_40_dialog_content = "Lihat ini, Grand Marshal. Robot-robot aneh yang baru saja menyerang kita sekarang bergerak dalam formasi.",
  ui_story_5082_50820601_41_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_5082_50820601_42_dialog_content = "Kami melihat yang menyerang kami sebelumnya. Dari desainnya, tampaknya itu adalah jenis droid tempur.",
  ui_story_5082_50820601_43_dialog_content = "Tapi yang benar-benar unik tentang strukturnya, adalah tampaknya mampu bergabung dengan mesin lain. Saya bertanya-tanya apakah mereka meneliti jenis teknologi ini di sini?",
  ui_story_5082_50820601_44_dialog_content = "Pola penerbangan mereka sepenuhnya terkoordinasi. Sepertinya mereka bergerak lebih dalam ke reruntuhan.",
  ui_story_5082_50820601_45_dialog_content = "Mari kita ikuti mereka.",
  ui_story_5082_50820601_46_dialog_content = "Aku akan mengintai di depan.",
  ui_story_5082_50820601_47_option_content = "Pemindaian Psikis—",
  ui_story_5082_50820601_48_dialog_content = "%^ mencari kekuatan adalah $!#￥ untuk mencari kehancuran... $%^#$#^!$",
  ui_story_5082_50820601_49_dialog_content = "Spearhead! Apakah kamu di dekat sini? Saya perlu tahu lebih banyak tentang apa yang terjadi di sini—",
  ui_story_5082_50820601_50_dialog_content = "—!",
  ui_story_5082_50820601_51_dialog_content = "Itu dia...!",
  ui_story_5082_50820601_52_option_content = "Force Boost!",
  ui_story_5082_50820601_53_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_54_dialog_content = "Ada trompet itu lagi.",
  ui_story_5082_50820601_55_dialog_content = "Mengapa aku terus-menerus terseret ke dalam kenangan-kenangan ini setiap kali aku mencoba untuk berkontak dengan gadis itu?",
  ui_story_5082_50820601_56_dialog_content = "Ada Reinhardt dan Wrath.",
  ui_story_5082_50820601_57_dialog_content = "Itu adalah terompet. Kamu harus pergi bergabung dengan mereka dalam formasi.",
  ui_story_5082_50820601_58_dialog_content = "Sementara kamu pergi untuk lebih banyak \"latihan khusus\"mu?",
  ui_story_5082_50820601_59_dialog_content = "Apakah program pelatihan itu bahkan resmi? Atau itu hanya sesuatu yang mereka buat khusus untukmu?",
  ui_story_5082_50820601_60_dialog_content = "Kamu terus kembali dengan luka segar setiap hari. Bahkan prajurit yang kembali dari garis depan tidak muncul dengan cedera seperti milikmu.",
  ui_story_5082_50820601_61_dialog_content = "... A-Aku bukan khawatir padamu atau apa pun! Aku hanya tidak ingin ada yang mengganggu tantangan kita!",
  ui_story_5082_50820601_62_dialog_content = "Kamu terlalu banyak berpikir. Saya baru saja meningkatkan level latihan saya, jadi saya masih membiasakan diri.",
  ui_story_5082_50820601_63_dialog_content = "Tidak ada latihan yang sia-sia. Setiap keterampilan dan pengalaman yang saya peroleh akan menambah kekuatan saya sendiri.",
  ui_story_5082_50820601_64_dialog_content = "Reinhardt! Kamu pikir kamu bisa mengabaikan tugas harianmu hanya karena latihan khususmu?!",
  ui_story_5082_50820601_65_dialog_content = "Baiklah, tidak di jam tangan saya, sekarang beri saya sepuluh putaran lagi!",
  ui_story_5082_50820601_66_dialog_content = "Pengajar, tolong! Reinhardt terlalu lelah untuk melanjutkan! Dia butuh istirahat!",
  ui_story_5082_50820601_67_dialog_content = "Apakah kalian berdua lupa hal pertama yang saya ajarkan? Seorang prajurit selalu mengikuti perintah!",
  ui_story_5082_50820601_68_dialog_content = "Itu lima lap lagi untukmu, Wrath!",
  ui_story_5082_50820601_69_dialog_content = "Buatlah sepuluh, pak!",
  ui_story_5082_50820601_70_dialog_content = "Anda tidak perlu terus mengikuti saya kemana-mana.",
  ui_story_5082_50820601_71_dialog_content = "\"Tidak ada latihan yang sia-sia.\" Kamu sendiri yang mengatakannya, bukan?",
  ui_story_5082_50820601_72_dialog_content = "Baiklah, tapi aku tidak berterima kasih padamu untuk ini.",
  ui_story_5082_50820601_73_dialog_content = "Tak ada yang meminta maafmu juga.",
  ui_story_5082_50820601_74_dialog_content = "(Dari saat itu, setiap hari adalah sama untuk Reinhardt.)",
  ui_story_5082_50820601_75_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_76_dialog_content = "<color=#e8d9bb>Seruan terompet pagi.</color>",
  ui_story_5082_50820601_77_dialog_content = "Siswa Akademi Reinhardt! Laporkan diri ke fasilitas pelatihan khusus!",
  ui_story_5082_50820601_78_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_79_dialog_content = "<color=#e8d9bb>Seruan terompet malam.</color>",
  ui_story_5082_50820601_80_dialog_content = "Akhirnya kamu kembali, Reinhardt! Tanganmu...",
  ui_story_5082_50820601_81_dialog_content = "Maaf, aku sedikit lelah jadi aku akan langsung tidur.",
  ui_story_5082_50820601_82_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_83_dialog_content = "Reinhardt, melapor untuk tugas.",
  ui_story_5082_50820601_84_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_85_dialog_content = "Reinhardt—",
  ui_story_5082_50820601_86_dialog_content = "Nng... Hah? Ada yang bisa kubantu...?",
  ui_story_5082_50820601_87_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820601_88_dialog_content = "(Reinhardt langsung pergi dari kamarnya ke fasilitas latihan khusus dan kembali, hanya berhenti cukup lama untuk makan beberapa suap ransumnya.)",
  ui_story_5082_50820601_89_dialog_content = "(Life-nya sepenuhnya berpusat pada latihan dan tidur, keduanya ditentukan oleh suara trompet.)",
  ui_story_5082_50820601_90_dialog_content = "Kami telah mengumpulkan cukup data dari bagian program ini, yang berarti kamu siap untuk tahap berikutnya: latihan kekuatan eksplosif.",
  ui_story_5082_50820601_91_dialog_content = "Untuk fase ini dari pelatihan Anda, Anda akan bertarung melawan droid tempur yang telah dimodifikasi berdasarkan atribut spesifik Anda.",
  ui_story_5082_50820601_92_dialog_content = "Saat melibatkan mereka dalam pertempuran, kamu akan merasa seolah-olah kamu sedang bertarung dengan dirimu sendiri.",
  ui_story_5082_50820601_93_dialog_content = "Gunakan kekuatan penuhmu untuk melampaui batasmu dan menghancurkan mereka.",
  ui_story_5082_50820601_94_dialog_content = "Aku mengerti.",
  ui_story_5082_50820602_1_dialog_content = "(Sakit sekali... Mereka benar-benar meningkatkan tingkat kesulitan untuk latihan \"kekuatan ledakan\" yang disebut-sebut ini.)",
  ui_story_5082_50820602_2_dialog_content = "Menarik. Tanda-tanda vitalnya sempat benar-benar hilang barusan, namun dia mampu memulihkan kesadaran dan melanjutkan perjuangan...",
  ui_story_5082_50820602_3_dialog_content = "Apa katamu?",
  ui_story_5082_50820602_4_dialog_content = "Subjek uji yang baik, tentu saja. Data yang telah kita kumpulkan sepenuhnya melampaui harapan kita.",
  ui_story_5082_50820602_5_dialog_content = "Dan meski kerusakan fisik pada tubuhnya relatif tinggi, itu masih dalam parameter yang dapat diterima.",
  ui_story_5082_50820602_6_dialog_content = "Nah, sekarang saatnya beralih ke tahap berikutnya...",
  ui_story_5082_50820602_7_dialog_content = "May Boleh aku bertanya?",
  ui_story_5082_50820602_8_dialog_content = "Oh, itu saja untuk pelatihan hari ini. Kau diberhentikan.",
  ui_story_5082_50820602_9_dialog_content = "Mempertimbangkan kalkulasi awal kita...",
  ui_story_5082_50820602_10_dialog_content = "Pelatihan khusus ini... Apakah aku satu-satunya kandidat, atau ada orang lain seperti aku?",
  ui_story_5082_50820602_11_dialog_content = "Parameter yang diperlukan adalah...",
  ui_story_5082_50820602_12_dialog_content = "...",
  ui_story_5082_50820602_13_dialog_content = "<color=#e8d9bb>Laboratorium Rahasia</color>",
  ui_story_5082_50820602_14_dialog_content = "Lukamu telah ditangani. Cobalah untuk tidak membasahi mereka dalam beberapa hari ke depan.",
  ui_story_5082_50820602_15_dialog_content = "Aku akan menyiapkan beberapa obat untukmu sebelum kau pergi. Ingatlah untuk mengganti perbanmu setiap hari, dan makanlah yang banyak—",
  ui_story_5082_50820602_16_dialog_content = "Kamu bisa simpan semua omongan dokter itu, Helios. Tidak akan ada perbedaan.",
  ui_story_5082_50820602_17_dialog_content = "Setiap kali dia berpikir sesuatu perlu dilakukan, dia mengejarnya dengan penuh tenaga tanpa mendengarkan orang lain.",
  ui_story_5082_50820602_18_dialog_content = "Denier…",
  ui_story_5082_50820602_19_dialog_content = "Aku hanya mengatakan yang sebenarnya. Ini sama seperti bagaimana kita sepakat untuk bertemu di sini sekali seminggu.",
  ui_story_5082_50820602_20_dialog_content = "Dan masih saja, sudah empat minggu penuh sejak dia terakhir kali menampakkan wajahnya di sini.",
  ui_story_5082_50820602_21_dialog_content = "Dia hampir tidak bisa menepati janjinya, dan setiap kali dia muncul, dia tidak sadar dan penuh luka.",
  ui_story_5082_50820602_22_dialog_content = "Suatu hari nanti, kamu harus membayar kembali semua peralatan yang telah kamu rusak karena pingsan di mana-mana!",
  ui_story_5082_50820602_23_dialog_content = "Cukup, Denier! Usahakan jangan salah paham, Reinhardt. Saya yakin apa yang dia coba katakan...",
  ui_story_5082_50820602_24_dialog_content = "Adalah bahwa ada banyak bahan mudah terbakar dan bahan peledak yang berserakan, dan dia tidak ingin kamu melukai diri sendiri.",
  ui_story_5082_50820602_25_dialog_content = "...",
  ui_story_5082_50820602_26_dialog_content = "Saya minta maaf, Denier. Saya tahu saya membuatmu khawatir dengan tidak muncul selama ini.",
  ui_story_5082_50820602_27_dialog_content = "Nanti aku akan pastikan mendapatkan peralatan laboratorium baru untukmu.",
  ui_story_5082_50820602_28_dialog_content = "...",
  ui_story_5082_50820602_29_dialog_content = "Lihat, selesai kan? Masalah terselesaikan!",
  ui_story_5082_50820602_30_dialog_content = "...",
  ui_story_5082_50820602_31_dialog_content = "Sementara kita membahas ini, saya tahu kita membangun laboratorium ini sendiri...",
  ui_story_5082_50820602_32_dialog_content = "Tapi agak kurang ventilasi, menurutmu? Jika Denier ingin melanjutkan eksperimennya...",
  ui_story_5082_50820602_33_dialog_content = "Bukankah tempat ini menimbulkan risiko mati lemas?",
  ui_story_5082_50820602_34_dialog_content = "...",
  ui_story_5082_50820602_35_dialog_content = "Ada yang salah, Reinhardt?",
  ui_story_5082_50820602_36_dialog_content = "...",
  ui_story_5082_50820602_37_dialog_content = "... Hah? Maaf, aku tadi melamun.",
  ui_story_5082_50820602_38_dialog_content = "Saya baru saja memikirkan sesi latihan terakhir saya. Entah kenapa, tiba-tiba saya merasa seperti tenggelam...",
  ui_story_5082_50820602_39_dialog_content = "Apakah Anda yakin Anda baik-baik saja?",
  ui_story_5082_50820602_40_dialog_content = "Tentu saja! Kalian berdua tahu betapa cepatnya aku pulih; mungkin sekarang ini aku penuh dengan luka, tapi mereka akan sembuh dalam waktu singkat.",
  ui_story_5082_50820602_41_dialog_content = "Akhir-akhir ini, aku semakin banyak berlatih, jadi semakin sulit untuk hadir. Aku akan berusaha untuk tidak terlambat lagi.",
  ui_story_5082_50820602_42_dialog_content = "Kamu menghindari topik, Reinhardt.",
  ui_story_5082_50820602_43_dialog_content = "Kamu tidak peduli tentang dirimu sendiri, atau apapun itu. Yang kamu pedulikan hanyalah latihan bodohmu.",
  ui_story_5082_50820602_44_dialog_content = "Apakah kamu tahu apa yang sedang kamu lakukan? Tujuan utama dari pelatihan adalah untuk meningkatkan potensi tempur seorang prajurit dalam batas tertentu.",
  ui_story_5082_50820602_45_dialog_content = "Ini bukan untuk memecahkan batas tersebut dengan mengorbankan tubuh Anda sendiri.",
  ui_story_5082_50820602_46_dialog_content = "Akhirnya kamu memberitahuku apa yang sebenarnya ada di pikiranmu, Denier. Aku senang.",
  ui_story_5082_50820602_47_dialog_content = "Kamu...",
  ui_story_5082_50820602_48_dialog_content = "Jangan khawatir. Aku tahu apa yang sedang kulakukan.",
  ui_story_5082_50820602_49_dialog_content = "Bagaimanapun juga, suatu hari nanti aku akan menjadi Grand Marshal. Bagaimana aku bisa memimpin seluruh Illumina jika aku bahkan tidak bisa menyelesaikan pelatihan akademiku?",
  ui_story_5082_50820602_50_dialog_content = "Hmph. Ingat saja untuk mendapatkan lab yang lebih besar untukku saat kamu akhirnya menjadi Grand Marshal.",
  ui_story_5082_50820602_51_dialog_content = "Aku tak tahan melihat Eclipsite di medan perang, jadi lebih baik aku menjadi peneliti terhebat di Illumina dan mempelajarinya dari meja operasiku.",
  ui_story_5082_50820602_52_dialog_content = "Saya tidak memiliki aspirasi besar seperti kalian berdua. Selama saya bisa menjadi pengintai yang baik, itu sudah cukup bagi saya.",
  ui_story_5082_50820602_53_dialog_content = "Apa yang tidak hebat tentang itu?",
  ui_story_5082_50820602_54_dialog_content = "Setiap prajurit memainkan peran penting dalam memberdayakan Illumina.",
  ui_story_5082_50820602_55_dialog_content = "Apakah itu pengintai kita, peneliti kita, atau bahkan Grand Marshal, kita semua merupakan darah kehidupan Illumina.",
  ui_story_5082_50820602_56_dialog_content = "Pokoknya, cukup sulit bagi kita untuk bertemu seperti ini, jadi mari kita bicara tentang sesuatu yang menyenangkan untuk sekali ini.",
  ui_story_5082_50820602_57_dialog_content = "Lebih baik sesuatu yang bisa kita masukkan dalam memoar kita untuk dibaca oleh seluruh dunia.",
  ui_story_5082_50820602_58_dialog_content = "Seorang calon Marsekal Agung, seorang calon ilmuwan top, dan seorang calon pemimpin pengintai—",
  ui_story_5082_50820602_59_dialog_content = "Rekan terbaik yang bisa diminta oleh siapa pun.",
  ui_story_5082_50820700_1_dialog_content = "Apakah droid petarung itu mencoba membawa kita ke sana? Taktik yang buruk sekali!",
  ui_story_5082_50820700_2_dialog_content = "Dari ekspresimu, aku asumsikan kamu baru saja merasakan sesuatu?",
  ui_story_5082_50820700_3_dialog_content = "Saya melakukannya. Kita semakin dekat dan dekat dengan gadis bercahaya merah itu.",
  ui_story_5082_50820700_4_dialog_content = "Kamu merasakan kehadirannya lagi?",
  ui_story_5082_50820700_5_dialog_content = "Dia selalu muncul mengikuti teriakan itu, tetapi setiap kali aku mencoba untuk melakukan kontak dengan dia, aku melihat semakin banyak dan banyak dari...",
  ui_story_5082_50820700_6_dialog_content = "Masa laluku?",
  ui_story_5082_50820700_7_dialog_content = "Ya...",
  ui_story_5082_50820700_8_dialog_content = "Kali ini, aku melihat bagian dari latihan kekuatan ledakanmu.",
  ui_story_5082_50820700_9_dialog_content = "Itu menjelaskan ekspresimu.",
  ui_story_5082_50820700_10_dialog_content = "Itu... Cukup brutal untuk ditonton.",
  ui_story_5082_50820700_11_dialog_content = "Seperti mereka mencoba membuatmu meninggalkan segala hal yang membuatmu menjadi manusia, dan mengubahmu menjadi senjata hidup.",
  ui_story_5082_50820700_12_dialog_content = "Anda adalah orang yang baik, PlayerName.",
  ui_story_5082_50820700_13_dialog_content = "Namun, perang hanya brutal karena tidak banyak tempat di mana kebaikan bisa ada di medan perang.",
  ui_story_5082_50820700_14_dialog_content = "Apakah kamu setuju atau tidak, kami tidak punya pilihan selain maju melalui kebrutalan itu.",
  ui_story_5082_50820700_15_dialog_content = "Dulu, saya ingin menjadi tentara terhebat dan terkuat di Federasi. Tentu saja, untuk mencapai itu berarti saya harus melewati neraka hidup.",
  ui_story_5082_50820700_16_dialog_content = "Tapi... Bukankah kamu merasa itu tidak adil? Apakah kamu tidak pernah ingin berhenti, atau bahkan melawan?",
  ui_story_5082_50820700_17_dialog_content = "Tentu saja saya lakukan. Bahkan setiap hari.",
  ui_story_5082_50820700_18_dialog_content = "Saat ini, Illumina memiliki beberapa pemimpin terbaik dalam sejarahnya, tetapi saya tidak berpikir itu terjadi begitu saja. Dulu, tidak ada satupun dari kami yang memiliki kehidupan yang mudah.",
  ui_story_5082_50820700_19_dialog_content = "Marsekal Agung, masih ingat apa yang terjadi di Undercities 13 dan 19?",
  ui_story_5082_50820700_20_dialog_content = "...",
  ui_story_5082_50820700_21_dialog_content = "<color=#e8d9bb>Federasi Illumina, Kota Gannon, Tahun 1986</color>",
  ui_story_5082_50820700_22_dialog_content = "Komandan masih belum kembali?",
  ui_story_5082_50820700_23_dialog_content = "Belum, Letnan Reinhardt! Marsekal Agung meminta kehadirannya untuk sebuah pertemuan!",
  ui_story_5082_50820700_24_dialog_content = "Komandan telah memerintahkan untuk siaga sampai ada pemberitahuan lebih lanjut. Tanpa pengecualian.",
  ui_story_5082_50820700_25_dialog_content = "Perintah siaga lagi? Tapi semua orang lainnya telah dikerahkan untuk mempertahankan posisi kunci... Apa yang dia pikirkan sebenarnya?",
  ui_story_5082_50820700_26_dialog_content = "Undercity 13 dan 19 telah jatuh ke tangan serangan Eclipsite, dan semua komunikasi telah diputus. Satu-satunya pesuruh yang berhasil melarikan diri meminta bala bantuan.",
  ui_story_5082_50820700_27_dialog_content = "... Di mana tepatnya kau belajar tentang itu?",
  ui_story_5082_50820700_28_dialog_content = "Itu tidak penting. Yang penting adalah dua Undercity kita berada di ambang kehancuran.",
  ui_story_5082_50820700_29_dialog_content = "Sementara Eclipsite merajalela di rumah kita, Grand Marshal dan komandan sibuk bermain-main jari dalam pertemuan!",
  ui_story_5082_50820700_30_dialog_content = "Komandan memerintahkan kita untuk siaga.",
  ui_story_5082_50820700_31_dialog_content = "Berdiam diri sekarang sama saja dengan membiarkan mereka mati. Kamu, dari semua orang, seharusnya tahu itu.",
  ui_story_5082_50820700_32_dialog_content = "...",
  ui_story_5082_50820700_33_dialog_content = "Ada apa? Pikir kamu masih bisa menutup kepala di pasir dan berpura-pura tidak tahu?",
  ui_story_5082_50820700_34_dialog_content = "Kamu sama saja seperti para komandan yang sombong itu, selalu bersedia berpura-pura bahwa semuanya baik-baik saja selama darah tidak mencapai tanganmu.",
  ui_story_5082_50820700_35_dialog_content = "...",
  ui_story_5082_50820700_36_dialog_content = "Letnan Reinhardt? Kemana kamu pergi?",
  ui_story_5082_50820700_37_dialog_content = "Hanya jalan-jalan, itu saja.",
  ui_story_5082_50820700_38_dialog_content = "<color=#e8d9bb>Pintu ruang pertemuan pusat terbuka lebar saat 2nd Legion Commander Pango dan Deputy Battalion Commander Barton keluar dengan marah.</color>",
  ui_story_5082_50820700_39_dialog_content = "Hei, kalian berdua. Saya mengerti jika hal-hal tidak berjalan terlalu baik di sana?",
  ui_story_5082_50820700_40_dialog_content = "Dengan pengecut itu memimpin 1st Legion? Tentu saja tidak!",
  ui_story_5082_50820700_41_dialog_content = "Jangan pergi dulu! Saya di sini untuk mengantarkan pesanan baru.",
  ui_story_5082_50820700_42_dialog_content = "\"Dengan segera, 2nd Legion harus dikerahkan ke Undercities 13 dan 19 untuk memberikan bala bantuan, dengan Letnan Reinhardt dan sebagian dari 1st Legion juga memberikan dukungan.\"",
  ui_story_5082_50820700_43_dialog_content = "Itu kurang lebih intinya. Bagaimana menurutmu?",
  ui_story_5082_50820700_44_dialog_content = "Kamu serius berpikir untuk memalsukan perintah militer?",
  ui_story_5082_50820700_45_dialog_content = "Jika kamu tidak mau membantu, maka kami akan menanganinya sendiri.",
  ui_story_5082_50820700_46_dialog_content = "Saya bisa mengirimkan beberapa skuad dari 1st Legion; sisanya lebih dari mampu untuk mempertahankan Gannon City bersama dengan 3rd Legion.",
  ui_story_5082_50820700_47_dialog_content = "Kita mungkin tidak memiliki banyak pengaruh di sini, tetapi kehadiran kita di Undercities tersebut bisa berarti perbedaan antara hidup dan mati.",
  ui_story_5082_50820700_48_dialog_content = "Sayangnya, aku tidak memiliki cukup banyak prajurit untuk misi ini. Itulah sebabnya aku ingin meminta bantuan dari 2nd Legion.",
  ui_story_5082_50820700_49_dialog_content = "Kamu tahu apa yang akan terjadi pada dirimu jika kita ikuti ini, 'kan?",
  ui_story_5082_50820700_50_dialog_content = "Aku menghargai kekhawatiranmu, commander... Tapi, menyelamatkan orang-orang masih lebih penting bagiku.",
  ui_story_5082_50820700_51_dialog_content = "... Kamu hanya letnan rendahan. Apa yang memberimu kepercayaan diri untuk mendekati kami dengan aksi seperti ini?",
  ui_story_5082_50820700_52_dialog_content = "Percayaanku adalah bahwa kalian berdua tidak akan pernah meninggalkan rekan-rekanmu.",
  ui_story_5082_50820700_53_dialog_content = "Apakah Anda masih belum memutuskan, Komandan Pango? Karena saya akan pergi dengannya bagaimanapun juga.",
  ui_story_5082_50820700_54_dialog_content = "Pertama kau melanggar perintah, dan sekarang kau memalsukannya? Kau benar-benar berani, Reinhardt.",
  ui_story_5082_50820700_55_dialog_content = "Itu saja yang harus kamu katakan setelah mengikutiku sejauh ini?",
  ui_story_5082_50820700_56_dialog_content = "Hah! Kamu pikir aku hanya akan berdiri dan membiarkanmu melakukan apa saja yang kamu mau?",
  ui_story_5082_50820700_57_dialog_content = "Menarik... Sepertinya kita bukan satu-satunya yang muak dengan atasan, bukan? Bagus! Sudah saatnya kita yang memegang kendali di sini!",
  ui_story_5082_50820700_58_dialog_content = "Sulit rasanya percaya bahwa itu benar-benar terjadi... Meskipun itu memang terdengar seperti kamu, Reinhardt.",
  ui_story_5082_50820700_59_dialog_content = "Sayangnya, kita masih belum berhasil tepat waktu.",
  ui_story_5082_50820700_60_dialog_content = "Undercity 13 hampir saja dihancurkan, dan kondisi Undercity 19 juga tidak jauh lebih baik.",
  ui_story_5082_50820700_61_dialog_content = "Setidaknya, kami berhasil menyelamatkan beberapa orang... Dan meskipun banyak orang memuji tindakan kami, kami juga menarik perhatian Komite.",
  ui_story_5082_50820700_62_dialog_content = "Ironisnya, hasil dari tindakan kami mencegah kami dituduh melakukan pembangkangan. Bahkan, Wrath dan saya cukup beruntung untuk dipromosikan menjadi Komandan Batalyon!",
  ui_story_5082_50820700_63_dialog_content = "Keberuntungan tidak ada hubungannya dengan jenis hal ini. Tidak di Illumina.",
  ui_story_5082_50820700_64_dialog_content = "Komandan Pango telah melatihmu untuk mengambil tempatnya dalam waktu yang lama. Insiden itu hanya memaksanya untuk mempercepat rencananya untukmu.",
  ui_story_5082_50820700_65_dialog_content = "Kamu masih sangat muda saat itu, dan kamu belum memiliki banyak prestasi. Saya yakin kamu juga memiliki bagianmu sendiri dari kesulitan saat itu, 'kan?",
  ui_story_5082_50820700_66_dialog_content = "Kamu adalah orang yang memiliki kesulitan lebih dari siapa pun, Reinhardt. Tindakanmu yang tidak sah dan perintah palsu benar-benar membuat marah komandan 1st Legion saat itu.",
  ui_story_5082_50820700_67_dialog_content = "Mereka menurunkan pangkat Anda ke pangkat terendah yang mungkin, mencabut semua wewenang Anda dan mengirim Anda untuk pelatihan dasar lagi dari awal.",
  ui_story_5082_50820700_68_dialog_content = "Hahaha! Tapi bahkan sekarang, setiap kali aku memikirkan kamu yang berhadapan dengan atasan kita demi diriku—",
  ui_story_5082_50820700_69_dialog_content = "Ini selalu membuat darahku bergejolak, seperti dulu! Kamu bahkan datang dengan sekelompok orang yang berteriak, \"Keagungan Illumina\"!",
  ui_story_5082_50820700_70_dialog_content = "…?",
  ui_story_5082_50820700_71_dialog_content = "Tunggu... Orang yang bertabrakan dengan atasanmu...",
  ui_story_5082_50820700_72_dialog_content = "<color=#e8d9bb>Federasi Illumina, Kota Gannon, Tahun 1986</color>",
  ui_story_5082_50820700_73_dialog_content = "Hei, Reinhardt! Peralatan latihan ini masih penuh debu! Kamu tidak sedang malas, bukan?!",
  ui_story_5082_50820700_74_dialog_content = "Aku akan mengelapnya lagi.",
  ui_story_5082_50820700_75_dialog_content = "Botol minumku juga kosong. Isilah sambil berjalan.",
  ui_story_5082_50820700_76_dialog_content = "Segera.",
  ui_story_5082_50820700_77_dialog_content = "Hei... Bukankah kita sudah terlalu jauh dengan ini?",
  ui_story_5082_50820700_78_dialog_content = "Apa yang kamu bicarakan? Dia memalsukan perintah hanya untuk membuat namanya dikenal, dan kamu masih berpikir dia pantas mendapatkan yang lebih baik?",
  ui_story_5082_50820700_79_dialog_content = "Komandan juga setuju...",
  ui_story_5082_50820700_80_dialog_content = "Orang-orang itu benar-benar berlebihan!",
  ui_story_5082_50820700_81_dialog_content = "Jangan terlalu marah tentang ini, Cologne. Aku melanggar aturan, dan sekarang aku membayar harganya.",
  ui_story_5082_50820700_82_dialog_content = "Terseret ke bawah karena diriku tidak sebanding, jadi biarkan saja.",
  ui_story_5082_50820700_83_dialog_content = "Bagaimana kamu bisa mengatakan itu, Reinhardt?! Kita semua tahu kebenaran ketika kita setuju untuk pergi bersamamu!",
  ui_story_5082_50820700_84_dialog_content = "Kamu tidak seharusnya satu-satunya yang dihukum, dan itu persis yang akan saya katakan kepada komandan!",
  ui_story_5082_50820700_85_dialog_content = "Hei, bukankah mereka dari 2nd Legion? Aku tidak ingat harus berbagi lapangan latihan dengan para pecundang itu hari ini?",
  ui_story_5082_50820700_86_dialog_content = "Serius? Betapa membosankan.",
  ui_story_5082_50820700_87_dialog_content = "Dan orang baru itu masih menjadi Komandan Batalyon. Saya mendengar dia bersekutu dengan Reinhardt ketika semua itu terjadi.",
  ui_story_5082_50820700_88_dialog_content = "Mereka adalah orang-orang yang merampok gudang peralatan! Banyak orang terluka karena mereka ingin menguasai semua kemuliaan!",
  ui_story_5082_50820700_89_dialog_content = "Ya, tapi mereka juga menyelamatkan Undercity 19... Apakah kamu pikir rumor lain tentang mereka itu benar?",
  ui_story_5082_50820700_90_dialog_content = "Jika mereka bukan, Grand Marshal pasti sudah menjelaskan semuanya sekarang. Itu berarti apa pun yang kita dengar tentang mereka sekarang mungkin benar.",
  ui_story_5082_50820700_91_dialog_content = "Rumor itu mulai tidak terkendali, komandan. Bukankah kita harus melakukan sesuatu tentang itu?",
  ui_story_5082_50820700_92_dialog_content = "Sama sekali tidak. Mereka telah membawa ini pada diri mereka sendiri, setelah semua.",
  ui_story_5082_50820700_93_dialog_content = "Aku tak pernah berpikir bahwa prajurit paling menjanjikan dari 2nd Legion akan seperti ini...",
  ui_story_5082_50820700_94_dialog_content = "Mereka bilang Komandan Pango secara pribadi mempromosikannya, tapi pada akhirnya...",
  ui_story_5082_50820700_95_dialog_content = "...",
  ui_story_5082_50820700_96_dialog_content = "Aku tahu kamu bisa mendengarnya, Commander Barton! 1st Legion benar-benar keluar dari barisan!",
  ui_story_5082_50820700_97_dialog_content = "Hanya terus bergerak.",
  ui_story_5082_50820700_98_dialog_content = "...",
  ui_story_5082_50820700_99_dialog_content = "Apa-apaan ini, sedang apa kau?",
  ui_story_5082_50820700_100_dialog_content = "Apakah kamu hanya akan berdiri dan menonton saja?",
  ui_story_5082_50820700_101_dialog_content = "Apakah semua ini benar-benar adil dan dapat diterima?",
  ui_story_5082_50820700_102_dialog_content = "...",
  ui_story_5082_50820700_103_dialog_content = "... Hmm!",
  ui_story_5082_50820700_104_dialog_content = "Barton!",
  ui_story_5082_50820700_105_dialog_content = "Kami tidak melakukan kesalahan apapun!",
  ui_story_5082_50820700_106_dialog_content = "?",
  ui_story_5082_50820700_107_dialog_content = "<color=#e8d9bb>Di tengah hening yang tiba-tiba, dia berjalan melalui kerumunan dengan kepala tegak dan berdiri di tengah keramaian.</color>",
  ui_story_5082_50820700_108_dialog_content = "Kalian semua adalah sekelompok boneka yang tidak berharga.",
  ui_story_5082_50820700_109_dialog_content = "Jika ada yang bersalah melakukan kesalahan, itu adalah kalian!",
  ui_story_5082_50820700_110_dialog_content = "Apakah saya salah karena tidak ingin meninggalkan rekan-rekan saya?",
  ui_story_5082_50820700_111_dialog_content = "Apakah salah jika aku ingin menyelamatkan orang-orang yang dibiarkan mati?!",
  ui_story_5082_50820700_112_dialog_content = "Anda-",
  ui_story_5082_50820700_113_dialog_content = "Gunakan kepalamu dan pikirkan apa yang seharusnya kamu lakukan! Atau kalian semua sudah kehilangan kemampuan untuk melakukan itu?",
  ui_story_5082_50820700_114_dialog_content = "Kita berjuang untuk mengalahkan Eclipsite dan melindungi sekutu kita.",
  ui_story_5082_50820700_115_dialog_content = "Dan masih saja, beberapa orang berpikir kita harus dihukum karena melakukan apa yang selalu mereka takuti untuk lakukan.",
  ui_story_5082_50820700_116_dialog_content = "Satu-satunya hal yang bisa kalian lakukan sekarang adalah patuh.",
  ui_story_5082_50820700_117_dialog_content = "Itulah mengapa hanya butuh satu perintah untuk membuatmu berbalik melawan kawan senjatamu dan mengirim mereka ke ajal mereka.",
  ui_story_5082_50820700_118_dialog_content = "...",
  ui_story_5082_50820700_119_dialog_content = "Aku akan mengatakannya lagi.",
  ui_story_5082_50820700_120_dialog_content = "Kami tidak melakukan kesalahan apapun.",
  ui_story_5082_50820700_121_dialog_content = "Dan jika kita harus melakukannya lagi dari awal, kita akan membuat pilihan yang sama persis.",
  ui_story_5082_50820700_122_dialog_content = "Itu karena kamu atau saya bisa jadi orang selanjutnya yang terjebak dalam situasi tanpa harapan.",
  ui_story_5082_50820700_123_dialog_content = "Tapi selama kita sekutu, tidak ada satu pun dari kita yang memiliki hak atau alasan untuk membelakangi satu sama lain tanpa mencoba!",
  ui_story_5082_50820700_124_dialog_content = "Aku akan mengatakannya untuk terakhir kalinya!",
  ui_story_5082_50820700_125_dialog_content = "Ya, kami melanggar perintah kami, tapi kami—",
  ui_story_5082_50820700_126_dialog_content = "Tidak melakukan kesalahan!",
  ui_story_5082_50820700_127_dialog_content = "...",
  ui_story_5082_50820700_128_dialog_content = "Ada hal lain yang ingin kamu katakan, Barton?",
  ui_story_5082_50820700_129_dialog_content = "Hmph.",
  ui_story_5082_50820700_130_dialog_content = "<color=#e8d9bb>Tanpa sepatah kata pun, Barton berjalan melalui kerumunan yang memisahkan dirinya, dan berdiri di seberangnya.</color>",
  ui_story_5082_50820700_131_dialog_content = "Aku tidak sebaik kamu dalam berbicara, tetapi sekarang, tidak ada kebutuhan untuk kata-kata lagi.",
  ui_story_5082_50820700_132_dialog_content = "<color=#e8d9bb>Barton membuncitkan dadanya.</color>",
  ui_story_5082_50820700_133_dialog_content = "Jayalah Illumina!",
  ui_story_5082_50820700_134_dialog_content = "Heh, tidak perlu kata-kata lagi, huh?",
  ui_story_5082_50820700_135_dialog_content = "<color=#e8d9bb>Dia mengambil napas dalam-dalam, dan menyesuaikan intensitasnya dengan panggilan miliknya sendiri.</color>",
  ui_story_5082_50820700_136_dialog_content = "Jayalah Illumina!",
  ui_story_5082_50820700_137_dialog_content = "<color=#e8d9bb>Prajurit yang mengelilingi mereka saling pandang, tidak yakin apa yang harus mereka lakukan. Kedua orang itu terus bertahan, seolah-olah langit itu sendiri tidak bisa membuat mereka beranjak.</color>",
  ui_story_5082_50820700_138_dialog_content = "<color=#e8d9bb>Sebelum siapa pun sadar, dua sosok lagi muncul dari kerumunan.</color>",
  ui_story_5082_50820700_139_dialog_content = "Jayalah Illumina!",
  ui_story_5082_50820700_140_dialog_content = "<color=#e8d9bb>Setelah mereka, mereka yang bertempur dalam pertempuran itu melangkah maju.</color>",
  ui_story_5082_50820700_141_dialog_content = "Jayalah Illumina!",
  ui_story_5082_50820700_142_dialog_content = "<color=#e8d9bb>Tak lama kemudian, semakin banyak orang yang bergabung dalam teriakan.",
  ui_story_5082_50820700_143_dialog_content = "Jayalah Illumina!",
  ui_story_5082_50820700_144_dialog_content = "<color=#e8d9bb>Ruang yang dulunya memisahkan kerumunan kini telah diisi oleh prajurit yang bersatu di bawah satu tujuan.</color>",
  ui_story_5082_50820700_145_dialog_content = "<color=#e8d9bb>Orang-orang yang pernah bertempur bersama, dan orang-orang yang tidak.</color>",
  ui_story_5082_50820700_146_dialog_content = "<color=#e8d9bb>Orang-orang yang mengenal satu sama lain dengan nama dan orang-orang yang sama sekali asing.</color>",
  ui_story_5082_50820700_147_dialog_content = "<color=#e8d9bb>Setiap prajurit berdiri dengan bangga di antara rekan-rekan mereka.</color>",
  ui_story_5082_50820700_148_dialog_content = "Jayalah Illumina!",
  ui_story_5082_50820700_149_dialog_content = "Jayalah Illumina!!!",
  ui_story_5082_50820700_150_dialog_content = "Apa yang harus kita lakukan, komandan? Kerumunan akan lepas kendali dengan kecepatan ini.",
  ui_story_5082_50820700_151_dialog_content = "... Jadi sekarang dia berperan sebagai pahlawan, ya?",
  ui_story_5082_50820700_152_dialog_content = "Tenanglah, kalian semua!!!",
  ui_story_5082_50820700_153_dialog_content = "...",
  ui_story_5082_50820700_154_dialog_content = "Komandan Batalyon Barton! Perlakuan istimewa Pango terhadap Anda tidak berlaku di luar 2nd Legion, jadi tolong jangan mengganggu latihan 1st Legion lagi.",
  ui_story_5082_50820700_155_dialog_content = "Perhatian, semua anggota 1st Legion! Sebagai hukuman atas tindakan kalian hari ini, kalian ditugaskan untuk membersihkan setiap lapangan latihan di Kota Gannon, efektif segera!",
  ui_story_5082_50820700_156_dialog_content = "Hukuman itu benar-benar tidak masuk akal!",
  ui_story_5082_50820700_157_dialog_content = "Kamu akan mengikuti perintahmu, prajurit!!!",
  ui_story_5082_50820700_158_dialog_content = "Setelah pembersihan selesai, seluruh 1st Legion akan diorganisir ulang dan dilarang berpartisipasi dalam acara militer di masa depan.",
  ui_story_5082_50820801_1_dialog_content = "Ketika aku mengingatnya... Semua orang hanya mengikuti arus, tetapi dia adalah orang yang mengucapkan kata-kata yang ada di hati mereka.",
  ui_story_5082_50820801_2_dialog_content = "Tunggu sebentar, apa maksudmu dengan itu?",
  ui_story_5082_50820801_3_dialog_content = "Saya tidak ingat ada gadis berpakaian merah saat itu!",
  ui_story_5082_50820801_4_dialog_content = "Aku tidak akan pernah lupa satu momen pun dari apa yang terjadi hari itu. Orang yang mengatakan semua kata-kata itu adalah kamu, Reinhardt!",
  ui_story_5082_50820801_5_dialog_content = "... Aku?",
  ui_story_5082_50820801_6_dialog_content = "Kamu tidak kehilangan ingatanmu dalam ledakan laboratorium itu, bukan? Dalam semua tahun aku mengenalmu, aku belum pernah melihat orang seperti yang kamu deskripsikan.",
  ui_story_5082_50820801_7_dialog_content = "Tapi kenangan-kenangan ini... Semakin jauh kita masuk ke dalam basis ini, semakin banyak mereka muncul kembali... Dan mereka sama sekali tidak terlihat palsu.",
  ui_story_5082_50820801_8_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5082_50820801_9_dialog_content = "Aduh, sialan...",
  ui_story_5082_50820801_10_dialog_content = "Perhatikan langkahmu! Tempat ini dipenuhi oleh elektronik lama dan rusak, jadi coba untuk tidak tersandung pada mereka.",
  ui_story_5082_50820801_11_dialog_content = "Ini, perhatikan dengan baik! Lain kali saat kamu hampir jatuh, cukup melompat ke depan seperti ini, dan...",
  ui_story_5082_50820801_12_dialog_content = "Terima kasih Philyshy, tapi aku cukup yakin hanya kucing yang bisa melakukannya...",
  ui_story_5082_50820801_13_dialog_content = "Hei, benda ini yang aku tersandung... Kenapa sepertinya itu seharusnya dikenakan di kepalamu?",
  ui_story_5082_50820801_14_dialog_content = "Meong! Aku pernah melihat ini sebelumnya!",
  ui_story_5082_50820801_15_dialog_content = "Dokter Chandra menggunakan benda ini untuk mengobati saya dan Yumi di awal. Dia bilang itu juga cukup berharga.",
  ui_story_5082_50820801_16_dialog_content = "Tampaknya tidak banyak seperti itu, dan mereka digunakan untuk melatih prajurit elit Illumina.",
  ui_story_5082_50820801_17_dialog_content = "Ada satu di sini juga. Mereka rusak sampai tak bisa diperbaiki, tetapi desain aslinya masih bisa dilihat dari bagian yang tersisa.",
  ui_story_5082_50820801_18_dialog_content = "Biar kulihat...",
  ui_story_5082_50820801_19_dialog_content = "Tunggu...",
  ui_story_5082_50820801_20_dialog_content = "<color=#e8d9bb>Kelompok ini hanya sempat melihat perangkat itu sebentar sebelum Barton menginjak-injaknya hingga hancur.</color>",
  ui_story_5082_50820801_21_dialog_content = "... Tidak mungkin sesuatu seperti ini bisa digunakan untuk melatih prajurit elit, bukan?",
  ui_story_5082_50820801_22_dialog_content = "Apakah barang-barang ini benar-benar langka dan berharga? Karena kita sudah berhasil menemukan tiga dari mereka di sini.",
  ui_story_5082_50820801_23_dialog_content = "Yang ini masih sebagian besar utuh, tapi sudah dipenuhi karat... Hah?",
  ui_story_5082_50820801_24_dialog_content = "Mesin ini...",
  ui_story_5082_50820801_25_dialog_content = "... Aku bisa merasakan kehidupan mengalir melaluinya.",
  ui_story_5082_50820801_26_dialog_content = "!",
  ui_story_5082_50820801_27_dialog_content = "Ugh...",
  ui_story_5082_50820801_28_dialog_content = "Reinhard?!",
  ui_story_5082_50820801_29_option_content = "Force Boost!",
  ui_story_5082_50820801_30_dialog_content = "...",
  ui_story_5082_50820801_31_dialog_content = "Tanda-tanda vital tidak lagi terdeteksi...",
  ui_story_5082_50820801_32_dialog_content = "<color=#e8d9bb>Glub, glub, glub...</color>",
  ui_story_5082_50820801_33_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50820801_34_dialog_content = "Terompet... Waktunya latihan.",
  ui_story_5082_50820801_35_dialog_content = "Groar!",
  ui_story_5082_50820801_36_dialog_content = "Grand Marshal!",
  ui_story_5082_50820801_37_dialog_content = "Mesin ini... Aku pernah melihatnya... Aku pernah memakainya...",
  ui_story_5082_50820801_38_dialog_content = "Tapi... Kenapa...",
  ui_story_5082_50820801_39_dialog_content = "Tetap bertahan, Grand Marshal!",
  ui_story_5082_50820801_40_dialog_content = "PlayerName! Buang benda itu!",
  ui_story_5082_50820801_41_dialog_content = "Tunggu, kehadiran itu barusan... Apakah kamu ingat sesuatu, Reinhardt?",
  ui_story_5082_50820801_42_dialog_content = "Ini samar, tetapi pasti ada hubungannya dengan hal itu... Sekarang terserah kamu, PlayerName...",
  ui_story_5082_50820801_43_dialog_content = "Marsekal Agung...!",
  ui_story_5082_50820801_44_dialog_content = "Ini sangat penting bagi saya, Vivian.",
  ui_story_5082_50820801_45_dialog_content = "Tetap waspada, semuanya. Saya butuh kamu untuk menjauhkan monster-monster itu dari kita.",
  ui_story_5082_50820801_46_dialog_content = "Saya akan memasuki kesadaran Reinhardt untuk mencari tahu apa yang ada di balik perangkat aneh ini.",
  ui_story_5082_50820901_1_dialog_content = "(Sepertinya aku berada di laboratorium Illumina, tapi rasanya sangat menekan di sini.)",
  ui_story_5082_50820901_2_dialog_content = "Subjek #1, silakan masuk ke ruangan satu hingga tiga dan gunakan Luminatics-mu sesuai dengan instruksi mereka.",
  ui_story_5082_50820901_3_dialog_content = "Aku mengerti.",
  ui_story_5082_50820901_4_dialog_content = "Subjek #2, silakan masuk ke ruangan satu hingga tiga dan gunakan Luminatics-mu sesuai dengan instruksi mereka.",
  ui_story_5082_50820901_5_dialog_content = "...",
  ui_story_5082_50820901_6_dialog_content = "(Apa yang mereka lakukan?)",
  ui_story_5082_50820901_7_dialog_content = "Subjek #2, harap patuhi perintah Anda.",
  ui_story_5082_50820901_8_dialog_content = "Aku ingin tahu tujuan sebenarnya dari eksperimen ini.",
  ui_story_5082_50820901_9_dialog_content = "Jika penguasaan saya atas Luminatics menjadi subjek pengujian, saya harus diberi tahu tentang lingkungan pengujian agar dapat membuat penyesuaian yang diperlukan.",
  ui_story_5082_50820901_10_dialog_content = "Ini akan lebih disukai daripada saya hanya melepaskan Lumina saya di ruangan gelap tanpa tujuan yang jelas dalam pikiran.",
  ui_story_5082_50820901_11_dialog_content = "Ketahuilah bahwa eksperimen ini akan membantu kamu dalam perjalananmu menjadi seorang peneliti, Denier.",
  ui_story_5082_50820901_12_dialog_content = "...",
  ui_story_5082_50820901_13_dialog_content = "Subjek #3, silakan masuk ke ruangan satu hingga tiga dan gunakan Luminatics Anda sesuai dengan instruksi mereka.",
  ui_story_5082_50820901_14_dialog_content = "Tidak ada yang memberitahuku tentang perubahan latihan ku hari ini.",
  ui_story_5082_50820901_15_dialog_content = "Kami tidak memiliki kewajiban untuk mengungkapkan informasi apa pun kepada kamu. Ini tidak lebih dari serangkaian tes kecil, sekarang tolong patuhi.",
  ui_story_5082_50820901_16_dialog_content = "Kurasa aku berhak mengetahui apa saja yang berkaitan dengan diriku.",
  ui_story_5082_50820901_17_dialog_content = "PlayerName?",
  ui_story_5082_50820901_18_dialog_content = "Apakah kamu merasa lebih baik? Kamu benar-benar membuatku takut barusan...",
  ui_story_5082_50820901_19_dialog_content = "Eksperimen macam apa itu? Dan mengapa kalian bertiga ada di sana?",
  ui_story_5082_50820901_20_dialog_content = "\"Semua kita bertiga\"? Apa yang kamu maksud?",
  ui_story_5082_50820901_21_dialog_content = "Kamu tidak melihat dirimu sendiri barusan? Kamu berdiri tepat di sini...",
  ui_story_5082_50820901_22_dialog_content = "Tidak...",
  ui_story_5082_50820901_23_dialog_content = "<color=#e8d9bb>Reinhardt berhenti sejenak, alisnya berkerut dalam pikiran. Dia mengambil dua langkah maju dan berdiri di tempat dia berdiri dalam ingatannya.</color>",
  ui_story_5082_50820901_24_dialog_content = "Apa yang kaulihat, PlayerName?",
  ui_story_5082_50820901_25_dialog_content = "Aku melihatmu dan juga dirimu di masa lalu dalam seragam akademi miliknya.",
  ui_story_5082_50820901_26_dialog_content = "Tapi saya melihat orang lain.",
  ui_story_5082_50820901_27_dialog_content = "Seorang gadis dengan rambut hitam pendek dan berantakan, matanya yang tajam seolah-olah siap untuk menantang siapa saja.",
  ui_story_5082_50820901_28_dialog_content = "Dia memiliki bekas luka di seluruh tangan dan lengannya, tetapi dia sama sekali tidak berusaha menutupinya. Dia mengenakan kemeja merah dan mantel yang dikenakannya seperti jubah di atas bahunya.",
  ui_story_5082_50820901_29_dialog_content = "Dia tampak begitu liar dan tak terikat, seperti api yang mengamuk yang mengancam untuk membakar segala sesuatu di jalannya. Pemandangan yang menakutkan—",
  ui_story_5082_50820901_30_dialog_content = "Dan entah bagaimana rasanya begitu membebaskan.",
  ui_story_5082_50820901_31_dialog_content = "Jadi gadis bercahaya merah yang kamu sebutkan sebelumnya...",
  ui_story_5082_50820901_32_dialog_content = "Benar.",
  ui_story_5082_50820901_33_dialog_content = "Sejujurnya, saya juga kesulitan mempercayainya. Tapi setelah melihat ingatan ini, tidak ada lagi yang bisa menyangkalnya.",
  ui_story_5082_50820901_34_dialog_content = "Gadis itu—",
  ui_story_5082_50820901_35_dialog_content = "Aku.",
  ui_story_5082_50820901_36_dialog_content = "(Adegan itu berubah lagi.)",
  ui_story_5082_50820901_37_dialog_content = "Semua subjek tes, harap lakukan penyesuaian yang diperlukan pada peralatan Anda dan konsentrasi.",
  ui_story_5082_50820901_38_dialog_content = "Tiga mesin itu... Mereka tampak seperti yang baru saja kita temukan.",
  ui_story_5082_50820901_39_dialog_content = "Jadi kalian pernah memakainya di masa lalu. Tidak heran Philyshy mengatakan mereka digunakan untuk melatih prajurit elit.",
  ui_story_5082_50820901_40_dialog_content = "Tapi kenapa aku sama sekali tidak ingat tentang hal-hal ini...?",
  ui_story_5082_50820901_41_dialog_content = "Urgh... Kenapa kepala ini sakit sekali? Apakah ini ada hubungannya dengan mesin-mesin ini?",
  ui_story_5082_50820901_42_dialog_content = "Perangkat yang merangsang otak untuk memicu potensi tersembunyi...",
  ui_story_5082_50820901_43_dialog_content = "Jika mereka bermain-main dengan otakku, mereka sebaiknya siap untuk membayarnya—!",
  ui_story_5082_50820901_44_dialog_content = "Tunggu sebentar, ini bukan detak jantungku! Emosi rumit ini juga bukan milikku... Apakah aku mendengar sesuatu? Tidak... Aku merasakannya...",
  ui_story_5082_50820901_45_dialog_content = "Aku merasakan kehadiran orang lain.",
  ui_story_5082_50820901_46_dialog_content = "... Saudari?",
  ui_story_5082_50820901_47_dialog_content = "... Denier.",
  ui_story_5082_50820901_48_dialog_content = "Aku tak pernah menyangka akan berbicara denganmu seperti ini.",
  ui_story_5082_50820901_49_dialog_content = "Atau memiliki itu di sini, dari semua tempat... Apa yang kamu lakukan di sini?",
  ui_story_5082_50820901_50_dialog_content = "Kemampuan untuk merasakan pikiran dan emosi orang lain... Apakah mereka mencoba meniru kekuatan Caelestites?",
  ui_story_5082_50820901_51_dialog_content = "Tapi jika kamu di sini, itu berarti seharusnya ada orang lain juga di sini.",
  ui_story_5082_50820901_52_dialog_content = "Apa ini?!",
  ui_story_5082_50820901_53_dialog_content = "Sepertinya saya benar.",
  ui_story_5082_50820901_54_dialog_content = "... Mereka mengatakan mereka ingin menguji kendali kita atas Luminatics, tetapi ini tidak ada hubungannya dengan itu.",
  ui_story_5082_50820901_55_dialog_content = "Mungkin mereka mencoba meningkatkan efisiensi tempur kita sebagai unit yang solid?",
  ui_story_5082_50820901_56_dialog_content = "Andai saja semudah itu. Apakah kalian tidak penasaran mengapa mereka memilih kita bertiga?",
  ui_story_5082_50820901_57_dialog_content = "...",
  ui_story_5082_50820901_58_dialog_content = "Juga, para peneliti mungkin menyebutkan bahwa akan ada lebih banyak tes seperti ini, bukan?",
  ui_story_5082_50820901_59_dialog_content = "Aku belum lupa bagaimana Reinhardt terlihat setelah dia kembali dari \"tes\" yang disebut-sebut itu.",
  ui_story_5082_50820901_60_dialog_content = "Kita tidak sekuat Reinhardt, jadi mungkin tes kita tidak akan begitu... Urgh!",
  ui_story_5082_50820901_61_dialog_content = "Helios?!",
  ui_story_5082_50820901_62_dialog_content = "Aku tidak merasakan kesadarannya lagi. Mungkin dia—Ack!",
  ui_story_5082_50820901_63_dialog_content = "Denier! Apa yang terjadi?!",
  ui_story_5082_50820901_64_dialog_content = "Groar!",
  ui_story_5082_50820901_65_dialog_content = "... Kalian adalah bagian selanjutnya dari \"seri kecil tes\" mereka, bukan?",
  ui_story_5082_50820902_1_dialog_content = "(Setelah hari itu, saya menyadari bahwa saya terus-menerus diikuti, tidak peduli kemana saya pergi.)",
  ui_story_5082_50820902_2_dialog_content = "...",
  ui_story_5082_50820902_3_dialog_content = "Fiuh, kontestan hari ini cukup tangguh.",
  ui_story_5082_50820902_4_dialog_content = "Melihat? Sudah kubilang dia akan baik-baik saja. Dia bilang dia tidak akan mengecewakan kita lagi, ingat?",
  ui_story_5082_50820902_5_dialog_content = "Jadi, apakah kamu menemui masalah apa pun, Reinhardt?",
  ui_story_5082_50820902_6_dialog_content = "Nah, hanya seperti biasa selalu diawasi. Bagaimana dengan kalian berdua? Sejak eksperimen berakhir, saya belum pernah melihat kalian berbicara satu sama lain.",
  ui_story_5082_50820902_7_dialog_content = "...",
  ui_story_5082_50820902_8_dialog_content = "Jika ada sesuatu di pikiranmu, kamu harus membicarakannya. Mengetahui kebenaran adalah satu-satunya cara kita dapat membuat keputusan yang tepat.",
  ui_story_5082_50820902_9_dialog_content = "... Kamu benar. Kami tumbuh bersama, dan kita tidak seharusnya menyimpan rahasia tentang ini satu sama lain.",
  ui_story_5082_50820902_10_dialog_content = "Sebenarnya, kepala saya sudah mulai sakit sejak eksperimen hari itu.",
  ui_story_5082_50820902_11_dialog_content = "Entah kenapa, saya tidak pernah lagi dilibatkan dalam kegiatan kelompok untuk latihan pengintai saya. Bahkan komandan saya tidak memberi saya jawaban langsung ketika saya bertanya tentang hal itu.",
  ui_story_5082_50820902_12_dialog_content = "Apakah kamu sudah memeriksakan dirimu?",
  ui_story_5082_50820902_13_dialog_content = "Mereka bilang tidak ada yang salah dengan saya, dan saya tidak perlu khawatir karena ini tidak berdampak serius pada hidup atau kemampuan bertarung saya.",
  ui_story_5082_50820902_14_dialog_content = "Bagaimana dengan kamu, Denier?",
  ui_story_5082_50820902_15_dialog_content = "... Tempat ini telah ditemukan.",
  ui_story_5082_50820902_16_dialog_content = "!",
  ui_story_5082_50820902_17_dialog_content = "Ini salahku.",
  ui_story_5082_50820902_18_dialog_content = "Aku membutuhkan beberapa material, jadi aku mengajukan proposal untuk proyek yang sedang aku kerjakan kepada atasan, tapi mereka mengabaikanku.",
  ui_story_5082_50820902_19_dialog_content = "Dan kemudian hanya beberapa hari yang lalu, proyek saya tiba-tiba ditolak sepenuhnya. Mereka melacak saya sampai ke sini karena curiga melakukan eksperimen berbahaya.",
  ui_story_5082_50820902_20_dialog_content = "Saya diperintahkan untuk menutup laboratorium dan menyerahkan semua peralatan dan penelitian saya.",
  ui_story_5082_50820902_21_dialog_content = "Itu bukan masalah. Kami telah membangun tempat ini sebelumnya, dan kami bisa membangunnya lagi.",
  ui_story_5082_50820902_22_dialog_content = "Kehilangan penelitianmu adalah kerugian yang sebenarnya di sini... Yang mengingatkan saya, apa sebenarnya yang sedang Anda kerjakan di sini?",
  ui_story_5082_50820902_23_dialog_content = "... Kami memiliki sesuatu yang lebih penting untuk dibicarakan sekarang.",
  ui_story_5082_50820902_24_dialog_content = "\"Tidak ada subjek tes yang berhasil menyelesaikan program ini, tetapi data Anda mungkin menjadi kunci untuk terobosan ilmiah bagi Illumina.\"",
  ui_story_5082_50820902_25_dialog_content = "\"Tuliskan semua yang kamu alami selama eksperimen ini... Apa yang kamu dengar... Apa yang kamu rasakan...\"",
  ui_story_5082_50820902_26_dialog_content = "\"Apakah kamu mencari promosi atau akses ke teknologi paling mutakhir yang tersedia, semua akan berada dalam jangkauanmu.\"",
  ui_story_5082_50820902_27_dialog_content = "Kalian berdua juga diberitahu sesuatu sejenis ini setelah eksperimen itu, 'kan?",
  ui_story_5082_50820902_28_dialog_content = "...",
  ui_story_5082_50820902_29_dialog_content = "Jadi sekarang saatnya untuk memutuskan. Semua yang setuju untuk menolak janji mereka tentang kehebatan dan sengaja gagal dalam eksperimen mereka, angkat tangan.",
  ui_story_5082_50820902_30_dialog_content = "Apa yang dikatakan Denier hari itu membuatku menyadari bahwa kami bertiga terhubung oleh eksperimen ini.",
  ui_story_5082_50820902_31_dialog_content = "Aku tidak tahu apa tujuan mereka, tapi aku khawatir hasilku akan membahayakan kalian berdua.",
  ui_story_5082_50820902_32_dialog_content = "Itu sebabnya saya tidak bisa dan tidak akan membuat keputusan tentang ini sendiri.",
  ui_story_5082_50820902_33_dialog_content = "<color=#e8d9bb>Helios mengangkat tangannya.</color>",
  ui_story_5082_50820902_34_dialog_content = "Saya juga masih memiliki lebih banyak untuk dikatakan.",
  ui_story_5082_50820902_35_dialog_content = "Tunggu sebentar, sekarang giliran saya berbicara. Saya adalah ahli dalam hal \"dites,\" jadi banyak hal ini sekarang menjadi sifat kedua bagi saya.",
  ui_story_5082_50820902_36_dialog_content = "Selama kamu terus menunjukkan batas-batasmu kepada mereka, mereka akan terus mendorongmu untuk melampaui batas tersebut.",
  ui_story_5082_50820902_37_dialog_content = "Mereka bahkan akan menyeret teman-temanmu ke dalamnya. Tidak ada harga yang terlalu besar di mata mereka, bahkan tidak dengan nyawa kita sekalipun.",
  ui_story_5082_50820902_38_dialog_content = "<color=#e8d9bb>Reinhardt mengangkat tangannya.</color>",
  ui_story_5082_50820902_39_dialog_content = "Aku telah melakukan sedikit penyelidikan sendiri beberapa hari ini.",
  ui_story_5082_50820902_40_dialog_content = "Untuk meningkatkan kekuatan militer Illumina, mereka akan mulai melakukan eksperimen untuk mengaktifkan Colossus yang dikenal sebagai \"Spearhead.\"",
  ui_story_5082_50820902_41_dialog_content = "Colossus...",
  ui_story_5082_50820902_42_dialog_content = "Kamu sudah mendengar tentang itu, kan? Mereka menggali itu dari salah satu Undercity terdekat. Rupanya, itu bahkan lebih tua dari Colossus Eraveil.",
  ui_story_5082_50820902_43_dialog_content = "Mungkin tujuan dari eksperimen itu adalah untuk menemukan pilot yang cocok untuk Colossus.",
  ui_story_5082_50820902_44_dialog_content = "Tapi saya tidak ingin membuang waktu untuk eksperimen yang tidak penting, dan saya pasti tidak ingin mereka mengganggu pertemuan harian kita.",
  ui_story_5082_50820902_45_dialog_content = "Jadi—",
  ui_story_5082_50820902_46_dialog_content = "<color=#e8d9bb>Denier mengangkat tangannya.</color>",
  ui_story_5082_50820902_47_dialog_content = "Kita semua sependapat.",
  ui_story_5082_50820902_48_dialog_content = "Selamat, setiap orang. Eksperimen pemilihan Navigator sudah gagal total.",
  ui_story_5082_50820902_49_dialog_content = "Yang berarti kita bebas melakukan apa yang harus kita lakukan sekarang. Mari kita sebut saja untuk hari ini.",
  ui_story_5082_50820902_50_dialog_content = "Bisakah saya minta sedikit waktu lagi? Saya masih memiliki banyak hal untuk dikatakan, dan saya pikir itu mungkin berhubungan dengan situasi kita.",
  ui_story_5082_50820902_51_dialog_content = "Belakangan ini aku tidak banyak melakukan hal, dan aku sedang memikirkan tentang eksperimen itu, jadi aku memutuskan untuk menyelidiki laboratorium itu.",
  ui_story_5082_50820902_52_dialog_content = "Tes yang mereka lakukan pada kami hanya di bagian kecil dari lab. Seluruh fasilitas jauh lebih besar dari yang kami bayangkan.",
  ui_story_5082_50820902_53_dialog_content = "Itu menjelaskan mengapa mereka harus membangunnya di salah satu Undercity tetangga. Selain sektor penelitian, lab ini memiliki pusat medis yang sangat lengkap dan peralatan yang berfungsi penuh.",
  ui_story_5082_50820902_54_dialog_content = "Keamanan sangat ketat, jadi saya tidak bisa melihat lebih jelas ke dalam.",
  ui_story_5082_50820902_55_dialog_content = "Tapi melihat dari jumlah makanan yang dialokasikan untuk fasilitas itu, tebakan saya adalah mereka menjaga banyak pasien di sana.",
  ui_story_5082_50820902_56_dialog_content = "Jadi, Anda mengatakan bahwa sakit kepala Anda bukan hanya milik Anda, dan bahwa orang lain mungkin perlu dirawat di rumah sakit untuk gejala mereka sendiri?",
  ui_story_5082_50820902_57_dialog_content = "Mungkin, tapi yang paling ingin kutunjukkan...",
  ui_story_5082_50820902_58_dialog_content = "Saya telah melihat orang-orang membawa anak-anak masuk dan keluar dari ruang asuh di sana.",
  ui_story_5082_50820902_59_dialog_content = "Menakutkan untuk dipikirkan, tetapi karena kegagalan berulang-ulang dari subjek tes dewasa, mungkin mereka telah mulai mengarahkan penelitian mereka ke arah yang berbeda...",
  ui_story_5082_50820902_60_dialog_content = "Maksudmu mereka sekarang melakukan percobaan pada anak-anak yatim?!",
  ui_story_5082_50820902_61_dialog_content = "Duduklah, Reinhardt.",
  ui_story_5082_50820902_62_dialog_content = "Semua yang kita bicarakan hari ini seharusnya tetap dirahasiakan.",
  ui_story_5082_50820902_63_dialog_content = "Kamu tahu bagaimana keadaan sekarang; kita tidak punya ruang untuk bermain jadi pahlawan ketika kita bahkan tidak bisa menjamin keselamatan kita sendiri.",
  ui_story_5082_50820902_64_dialog_content = "Jadi, tenanglah. Eksperimen hari itu memberi saya beberapa ide tentang bagaimana melanjutkan penelitian saya dan menyelesaikan masalah kita.",
  ui_story_5082_50820902_65_dialog_content = "Dengan sedikit keberuntungan, dia akan bisa melindungi kita, bahkan bisa membawa kita keluar dari tempat ini untuk selamanya. Tapi sekarang...",
  ui_story_5082_50820902_66_dialog_content = "Sebagai seseorang yang telah melalui tak terhitung jumlah sesi \"latihan khusus\", saya tahu dari pengalaman pribadi bahwa tidak ada orang biasa yang bisa bertahan dalam jenis neraka ini!",
  ui_story_5082_50820902_67_dialog_content = "Mereka membawa saya ke berbagai lokasi tersembunyi untuk \"tes\" saya, termasuk bangunan yang ditinggalkan dan medan perang lama..",
  ui_story_5082_50820902_68_dialog_content = "Saya akan menandai lokasi tepat mereka di peta. Kamu mungkin bisa menggunakan salah satu tempat tersebut sebagai lab sementara.",
  ui_story_5082_50820902_69_dialog_content = "Tapi mungkin kamu harus pergi ke sana sendirian.",
  ui_story_5082_50820902_70_dialog_content = "Apakah kamu tidak mendengar apa pun yang baru saja saya katakan?",
  ui_story_5082_50820902_71_dialog_content = "Sangat mungkin bahwa \"latihan\" Anda bertujuan untuk mencapai tujuan yang lebih besar—",
  ui_story_5082_50820902_72_dialog_content = "Meski begitu!",
  ui_story_5082_50820902_73_dialog_content = "Kakak…",
  ui_story_5082_50820902_74_dialog_content = "Saya mengerti kekhawatiranmu, Denier. Tetapi melarikan diri tidak akan menyelesaikan apa pun.",
  ui_story_5082_50820902_75_dialog_content = "Apakah kamu bersedia membantu saya melakukan sedikit lebih banyak penyelidikan, Helios?",
  ui_story_5082_50820902_76_dialog_content = "Anda bahkan tidak perlu bertanya. Tetapi jika asumsi kita benar, apa yang Anda siapkan untuk melakukannya?",
  ui_story_5082_50820902_77_dialog_content = "Bagaimana menurutmu?",
  ui_story_5082_50820902_78_dialog_content = "K-Katakan kita berhasil menyelamatkan orang-orang di dalam... Lalu apa?",
  ui_story_5082_50820902_79_dialog_content = "Saya belum merencanakan sejauh itu.",
  ui_story_5082_50820902_80_dialog_content = "Tapi jika saya hanya berdiam diri, mengetahui hal-hal buruk ini terjadi...",
  ui_story_5082_50820902_81_dialog_content = "Lalu apa gunanya semua usaha saya sampai saat ini?",
  ui_story_5082_50820902_82_dialog_content = "Aku ingin menjadi Grand Marshal dan menjadi prajurit terkuat di Illumina suatu hari nanti. Setiap kali bencana menyerang, aku ingin berada di garis depan pertempuran dan melindungi setiap orang.",
  ui_story_5082_50820902_83_dialog_content = "Aku tidak ingin menjadi seseorang yang ragu-ragu ketika sekutunya dalam bahaya, atau merunduk di hadapan ancaman baru—",
  ui_story_5082_50820902_84_dialog_content = "Dan aku menolak untuk terlibat dalam skema pengagungan diri orang-orang yang bereksperimen pada anak-anak kecil.",
  ui_story_5082_50820902_85_dialog_content = "Jika semua pemimpin Illumina seperti ini, maka saya perlu bertanya kepada mereka...",
  ui_story_5082_50820902_86_dialog_content = "Ketika mereka bersorak Jayalah Illumina sambil mengirim prajurit garis depan kami menuju kematian, atau menculik dan menyiksa orang-orang yang tidak bersalah...",
  ui_story_5082_50820902_87_dialog_content = "Apakah hanya untuk memastikan stabilitas kepentingan mereka?",
  ui_story_5082_50820902_88_dialog_content = "Tunggu, Reinhardt! Apakah kamu bahkan tahu apa yang sedang kamu katakan?",
  ui_story_5082_50820902_89_dialog_content = "Para petinggi sudah melihatmu sebagai ekstrimis dan ancaman setelah kamu memalsukan perintah terakhir kali.",
  ui_story_5082_50820902_90_dialog_content = "Apakah kamu benar-benar akan mengkhianati Illumina kali ini?!",
  ui_story_5082_50820902_91_dialog_content = "Mengkhianati? Sama sekali tidak.",
  ui_story_5082_50820902_92_dialog_content = "Pengkhianat yang sebenarnya adalah pengecut yang memimpin militer dan orang bodoh yang menuruti mereka.",
  ui_story_5082_50820902_93_dialog_content = "Pengkhianat yang sebenarnya adalah orang-orang yang melakukan percobaan pada anak-anak yang tidak bersalah, serta orang-orang yang hanya berdiri dan membiarkannya terjadi.",
  ui_story_5082_50820902_94_dialog_content = "Aku menolak untuk mengikuti ini, dan aku menolak untuk hanya memikirkan keselamatanku sendiri.",
  ui_story_5082_50820902_95_dialog_content = "Denier, Helios, aku minta maaf telah menyeret kalian berdua ke dalam masalah ini.",
  ui_story_5082_50820902_96_dialog_content = "Tapi jika saya mengorbankan idealisme saya untuk mempertahankan keadaan seperti itu, saya tidak akan pernah mencapai impian saya.",
  ui_story_5082_50820902_97_dialog_content = "Inilah sebabnya saya akan melakukan segala yang ada dalam kekuasaan saya untuk menggulingkan sistem busuk dan munafik ini.",
  ui_story_5082_50821001_1_dialog_content = "Tidak bisa percaya... Grand Marshal sendiri sebenarnya pernah mencoba untuk menggulingkan Illumina di masa lalu?!",
  ui_story_5082_50821001_2_dialog_content = "Hubungan telepati yang aneh antara ketiga prajurit yang ditingkatkan itu bukanlah kebetulan sama sekali...",
  ui_story_5082_50821001_3_dialog_content = "Mereka berpikir mereka akan aman selama mereka menyembunyikan hasil penelitian mereka, tetapi itu hanya menarik perhatian atasan mereka bahkan lebih banyak.",
  ui_story_5082_50821001_4_dialog_content = "Menggulingkan Illumina... adalah usaha yang berani, setidaknya itu yang bisa dikatakan...",
  ui_story_5082_50821001_5_dialog_content = "Namun ketika dia menyadari bahwa potensinya itu nyata, dan bahwa kekuatannya adalah hasil dari rencana yang disusun dengan hati-hati, dia tahu dia bisa melakukannya.",
  ui_story_5082_50821001_6_dialog_content = "... Kamu berbicara tentang dirimu di masa lalu seolah-olah dia adalah orang yang benar-benar berbeda.",
  ui_story_5082_50821001_7_dialog_content = "Itu karena sejauh yang saya ketahui, dia adalah orang yang sama sekali berbeda.",
  ui_story_5082_50821001_8_dialog_content = "Akademi, pelatihan dan eksperimen, asrama... Selama ini, aku berpikir kenangan tentang hal-hal ini sudah lengkap.",
  ui_story_5082_50821001_9_dialog_content = "Saya akan menyadari kecilnya kekosongan dalam ingatan saya dari waktu ke waktu, tetapi saya tidak pernah tahu ada begitu banyak detail asing yang tersembunyi di dalamnya.",
  ui_story_5082_50821001_10_dialog_content = "Terutama tes yang kami lalui bertiga. Sepertinya kenangan tentang hari itu telah sepenuhnya terhapus.",
  ui_story_5082_50821001_11_dialog_content = "Bisakah jadi ingatanku tentang masa lalu sangat berbeda dari apa yang sebenarnya terjadi...?",
  ui_story_5082_50821001_12_dialog_content = "Aku yakin Vice juga merasa begitu tentang hal itu...",
  ui_story_5082_50821001_13_dialog_content = "Baguslah kita bisa menggali sedikit kebenaran dari mesin-mesin ini, bukan?",
  ui_story_5082_50821001_14_dialog_content = "Karena kamu juga dipilih untuk eksperimen mereka, kemungkinan kamu kehilangan ingatanmu karena alasan yang serupa.",
  ui_story_5082_50821001_15_dialog_content = "Tidak begitu. Setelah melihat masa laluku, kamu seharusnya tahu bahwa saya tidak dipilih untuk mengemudikan Colossus. Kenangan saya tidak menunjukkan sebaliknya.",
  ui_story_5082_50821001_16_dialog_content = "Meski begitu, aku sangat ingin tahu apa yang terjadi padanya selanjutnya.",
  ui_story_5082_50821001_17_dialog_content = "Sebagian besar firasatmu benar.",
  ui_story_5082_50821001_18_dialog_content = "Menurut laporan terbaru dari lab, mereka secara resmi siap untuk mengaktifkan Colossus Spearhead.",
  ui_story_5082_50821001_19_dialog_content = "Pilot yang mereka pilih saat ini adalah seorang gadis berusia empat tahun dari taman kanak-kanak—",
  ui_story_5082_50821001_20_dialog_content = "Kecocokannya dengan sistem cadangan adalah yang tertinggi di antara subjek uji lainnya.",
  ui_story_5082_50821001_21_dialog_content = "Kau bercanda padaku? Mereka memaksa seorang gadis kecil untuk melakukan ini?!",
  ui_story_5082_50821001_22_dialog_content = "Jangan meremehkan dia karena usianya.",
  ui_story_5082_50821001_23_dialog_content = "Sebelum proyek ini, tampaknya Komite telah melatihnya selama setahun penuh. Mungkin dia bahkan memiliki pengalaman lebih banyak daripada kita semua.",
  ui_story_5082_50821001_24_dialog_content = "Dia bahkan mencapai tingkat keberhasilan 20% pada percobaan awalnya.",
  ui_story_5082_50821001_25_dialog_content = "Denier, kamu...",
  ui_story_5082_50821001_26_dialog_content = "... Jangan mengatakannya seperti itu.",
  ui_story_5082_50821001_27_dialog_content = "Saya hanya realistis. Sudahkah kamu melihat bagaimana pertempuran kita melawan Eclipsite berlangsung?",
  ui_story_5082_50821001_28_dialog_content = "Mengingat status saat ini dari eksperimen, mengambil risiko nyawa satu anak kecil demi kepentingan banyak orang lainnya memberikan probabilitas sukses yang tinggi.",
  ui_story_5082_50821001_29_dialog_content = "Itu masih bukan alasan untuk bermain-main dengan kehidupan anak kecil! Kita tidak bisa menunggu lebih lama lagi; kita harus melakukan sesuatu!",
  ui_story_5082_50821001_30_dialog_content = "Menyisihkan pertanyaan tentang di mana harus memulai, Anda baru saja mendapatkan kembali hak istimewa komando Anda. Denier dan saya juga sedang diisolasi dari Anda, yang berarti Anda tidak memiliki orang lain untuk diandalkan.",
  ui_story_5082_50821001_31_dialog_content = "Meskipun aku hanya mendapatkan kembali beberapa hak istimewa sebelumnya, bukan berarti aku memulai dari awal.",
  ui_story_5082_50821001_32_dialog_content = "Prajurit terkuat dari 1st Legion sudah setuju untuk mengikutiku.",
  ui_story_5082_50821001_33_dialog_content = "Aku akan berusaha sebaik mungkin untuk menghindari pengawasan dan mengatur korespondensi di salah satu Undercity terdekat.",
  ui_story_5082_50821001_34_dialog_content = "Hubungi Barton jika kamu perlu menghubungi saya. Dia telah setuju untuk membantu kita juga.",
  ui_story_5082_50821001_35_dialog_content = "Kamu mungkin terisolasi sekarang, tetapi itu hanya berarti kamu memiliki lebih banyak kebebasan untuk mengumpulkan informasi.",
  ui_story_5082_50821001_36_dialog_content = "Denier dapat menangani kemajuan lab. Sementara itu, Helios, kami membutuhkan kamu untuk mencari tahu berapa banyak lagi eksperimen rahasia ini yang sedang dilakukan di Illumina.",
  ui_story_5082_50821001_37_dialog_content = "Baik itu tingkatan atas militer atau para peneliti, kita harus siap untuk skenario terburuk yang mungkin terjadi. Kita sedang berperang, setelah semua.",
  ui_story_5082_50821001_38_dialog_content = "Dan ketika aku menjadi Grand Marshal, tugas pertamaku adalah berjuang untuk kehidupan setiap korban tak bersalah dari eksperimen ini.",
  ui_story_5082_50821001_39_dialog_content = "Tapi kita masih belum tahu seberapa kuat Komite saat ini. Menurutmu, ini terlalu berisiko, bukan?",
  ui_story_5082_50821001_40_dialog_content = "Jika mereka memiliki Reinhardt lainnya yang siap sedia di suatu tempat, peluang keberhasilan kita akan semakin tipis.",
  ui_story_5082_50821001_41_dialog_content = "Maka kita akan pergi dengan Rencana B.",
  ui_story_5082_50821001_42_dialog_content = "Aurorian bisa bertahan hampir di mana saja, bahkan di Undercity yang terbengkalai...",
  ui_story_5082_50821001_43_dialog_content = "Selama ada cukup makanan, air, ruang, dan cahaya, pemukiman untuk Aurorian dapat dibangun.",
  ui_story_5082_50821001_44_dialog_content = "Dan di mana pun Aurorian berkumpul, selalu ada kebutuhan untuk Grand Marshal.",
  ui_story_5082_50821001_45_dialog_content = "Hahaha! Kamu berpikir terlalu jauh ke depan, Denier. Saya tidak berniat membiarkan hal-hal sampai ke titik itu.",
  ui_story_5082_50821001_46_dialog_content = "Setelah semua, tujuan awal kami adalah untuk menyediakan tempat perlindungan bagi setiap Aurorian yang dilanda krisis...",
  ui_story_5082_50821001_47_dialog_content = "Untuk melindungi anak-anak yang, seperti kami, tidak memiliki ingatan tentang orang tua mereka sendiri dan harus mengandalkan tinju mereka untuk bertahan hidup.",
  ui_story_5082_50821001_48_dialog_content = "...",
  ui_story_5082_50821001_49_dialog_content = "Banyak orang di Illumina yang memiliki cerita yang sama, huh...",
  ui_story_5082_50821001_50_dialog_content = "Sebelumnya, saya hanya tahu tentang Vice, tetapi setelah melihat ini... Saya merasa sangat menyesal untuk semua orang...",
  ui_story_5082_50821001_51_dialog_content = "Tidak ada yang lebih baik dari siapa pun saat itu. Aku bertaruh banyak orang memiliki pengalaman serupa dengan gadis berusia empat tahun itu.",
  ui_story_5082_50821001_52_dialog_content = "Mengenai Vice, aku mulai berpikir... Bahwa kenangan-kenangannya tentang eksperimen ini mungkin tidak sepenuhnya nyata.",
  ui_story_5082_50821001_53_dialog_content = "Kamu, di sisi lain, tampaknya sangat bersimpati dengan gadis itu.",
  ui_story_5082_50821001_54_dialog_content = "... Jadi, apakah rencana kalian berhasil pada akhirnya?",
  ui_story_5082_50821001_55_dialog_content = "Jika kamu harus bertanya, maka yang bisa kulakukan hanyalah mengingatkanmu bahwa sekarang aku adalah Grand Marshal di Illumina.",
  ui_story_5082_50821001_56_dialog_content = "Apakah kita masih membicarakan tentang kamu yang sama? Atau Illumina yang sama, sejauh itu?",
  ui_story_5082_50821001_57_dialog_content = "Apakah itu benar-benar penting? Sudah jelas bahwa \"rencana\" dia akhirnya gagal, bukan?",
  ui_story_5082_50821001_58_dialog_content = "Saya pikir itu sangat penting.",
  ui_story_5082_50821001_59_dialog_content = "Aku penasaran ingin tahu hasilnya, meskipun itu semua adalah masa lalu.",
  ui_story_5082_50821001_60_dialog_content = "Tapi apa yang kamu katakan sekarang terdengar seperti itu datang dari Reinhardt hari ini.",
  ui_story_5082_50821001_61_dialog_content = "Sebagian darinya mengisyaratkan kemenanganmu atas \"dia,\" sementara sisanya mengisyaratkan kegagalan \"dia\" terhadap Illumina.",
  ui_story_5082_50821001_62_dialog_content = "Jadi saya harus bertanya: dimana tepatnya kamu berdiri sekarang, Reinhardt?",
  ui_story_5082_50821001_63_dialog_content = "Apakah akan membunuhmu untuk lebih langsung kadang-kadang?",
  ui_story_5082_50821001_64_dialog_content = "Saya hanya mempersulit karena ini tentang kamu yang kita bicarakan.",
  ui_story_5082_50821001_65_dialog_content = "Maka sepertinya aku perlu lebih jujur padamu.",
  ui_story_5082_50821001_66_dialog_content = "Untuk mengatakan yang sebenarnya, saya sedikit bingung sendiri. Menurutmu, apakah \"Reinhardt\" lebih mirip saya, atau saya lebih mirip dia?",
  ui_story_5082_50821001_67_dialog_content = "Aku…",
  ui_story_5082_50821001_68_dialog_content = "Kamu tidak perlu menghindar dari pertanyaan. Aku tidak akan marah apa pun yang kamu katakan, aku janji.",
  ui_story_5082_50821001_69_dialog_content = "I-Itu bukan yang ada di pikiranku.",
  ui_story_5082_50821001_70_dialog_content = "Dia tampak jauh lebih bebas dan tak terkekang, dan...",
  ui_story_5082_50821001_71_dialog_content = "Maaf, aku benar-benar tidak tahu bagaimana cara terbaik untuk menggambarkannya saat ini.",
  ui_story_5082_50821001_72_dialog_content = "Jangan khawatir. Anda sudah benar sekali.",
  ui_story_5082_50821001_73_dialog_content = "Seperti yang bisa kamu lihat, kita sangat berbeda satu sama lain.",
  ui_story_5082_50821001_74_dialog_content = "Pada saat apapun, bisa jadi ada seseorang di Illumina yang sedang mengalami neraka yang sama seperti yang pernah aku alami dulu.",
  ui_story_5082_50821001_75_dialog_content = "Kamu pikir setelah bertahun-tahun melihat kekejaman Zona Gelap dengan mata kepala sendiri, saya tidak berubah karena itu?",
  ui_story_5082_50821001_76_dialog_content = "Kupikir aku tidak. Dengan sepenuh hati, aku berharap aku tidak.",
  ui_story_5082_50821001_77_dialog_content = "Ketika saya masih muda, saya berpikir saya bisa melindungi seluruh Federasi sendirian.",
  ui_story_5082_50821001_78_dialog_content = "Tapi setelah kehilangan begitu banyak rekan, saya mulai bertanya pada diri sendiri, \"Meskipun saya bisa melindungi setiap orang sendirian, berapa lama itu bisa bertahan?\"",
  ui_story_5082_50821001_79_dialog_content = "Kalau sekarang ada orang muda dan marah seperti dia di depanku dan memanggilku tidak berguna dan korup...",
  ui_story_5082_50821001_80_dialog_content = "Dan bersumpah untuk meruntuhkanku dan membangun dunia baru yang cerah di tempatku...",
  ui_story_5082_50821001_81_dialog_content = "Aku tidak tahu apakah aku akan menghentikannya, mendukungnya...",
  ui_story_5082_50821001_82_dialog_content = "Atau bahkan...",
  ui_story_5082_50821001_83_dialog_content = "Mungkin aku tidak mengerti beban kepemimpinan seperti yang kamu alami, tapi sebagai temanmu, aku tahu pasti bahwa kamu bukan orang seperti itu...",
  ui_story_5082_50821001_84_dialog_content = "Kamu juga jauh dari satu-satunya yang mendukung Illumina.",
  ui_story_5082_50821001_85_dialog_content = "Aku tahu apa yang coba kamu katakan, tapi setelah melihatnya dan mengingat semua yang terjadi dulu... Aku tak bisa tidak merasa sedikit tidak puas.",
  ui_story_5082_50821001_86_dialog_content = "Meski begitu, aku tidak takut untuk berbagi hal-hal ini denganmu. Melihatku seperti ini pasti sedikit mengecewakan, ya?",
  ui_story_5082_50821001_87_dialog_content = "Sama sekali tak tahu…",
  ui_story_5082_50821001_88_dialog_content = "Ayo kita kembali. Yang lain pasti sudah lelah menunggu kita sampai sekarang.",
  ui_story_5082_50821001_89_dialog_content = "... Jadi Grand Marshal melihat dirinya sendiri dalam kenangan masa lalunya?",
  ui_story_5082_50821001_90_dialog_content = "... Bagaimana dengan kamu, Barton? Seberapa banyak yang kamu ketahui tentang apa yang terjadi saat itu?",
  ui_story_5082_50821001_91_dialog_content = "Pemahamanku adalah bahwa Reinhardt, Forsakin, dan Helios diam-diam merencanakan sesuatu saat itu.",
  ui_story_5082_50821001_92_dialog_content = "...",
  ui_story_5082_50821001_93_dialog_content = "Aku juga sudah bilang bahwa aku akan mendukungmu tidak peduli apa pun, tapi aku tidak pernah mendengar kabar apa pun sampai akhir.",
  ui_story_5082_50821001_94_dialog_content = "Saya hanya tahu bahwa Anda somehow terlibat dalam ledakan laboratorium, tetapi saya tidak memiliki cara untuk menyelidiki masalah itu pada saat itu.",
  ui_story_5082_50821001_95_dialog_content = "Tangan kami sudah terikat dengan Krisis Darkover, dan ada banyak pekerjaan yang harus dilakukan setelah pertempuran.",
  ui_story_5082_50821001_96_dialog_content = "Kamu belum menjadi komandan saat kita bertemu lagi, tetapi kamu sudah siap untuk naik jauh melampaui pangkat itu.",
  ui_story_5082_50821001_97_dialog_content = "Jadi bahkan setelah semua itu terjadi... Reinhardt mendapatkan promosi lagi?",
  ui_story_5082_50821001_98_dialog_content = "Benar, dan dia adalah orang yang benar-benar berbeda pada saat itu juga: teguh, mengesankan, dan benar-benar menakutkan di medan perang. Kekuatannya yang sudah mengesankan tampaknya tumbuh setiap hari.",
  ui_story_5082_50821001_99_dialog_content = "Dibandingkan dengan dia dan pertumbuhannya yang meledak-ledak, aku hanyalah prajurit rendahan yang menginjak-injak lumpur.",
  ui_story_5082_50821001_100_dialog_content = "Jadi, sementara aku menjalankan misiku, aku juga menjalani latihan khusus versi sendiri. Itulah juga saat aku mulai lebih keras pada bawahan-bawahanku!",
  ui_story_5082_50821001_101_dialog_content = "Saya mengerti. Jadi itulah saat 2nd Legion mendapatkan reputasi untuk metode pelatihan yang keras dan tidak mengampuni.",
  ui_story_5082_50821001_102_dialog_content = "<color=#e8d9bb>Dor! Dor!</color>",
  ui_story_5082_50821001_103_dialog_content = "Meong! Dan di sini saya pikir itu sudah selesai!",
  ui_story_5082_50821001_104_dialog_content = "Mengapa mereka terus menabrak dinding?",
  ui_story_5082_50821001_105_dialog_content = "Tempat ini terlalu tidak stabil secara struktural untuk menahan benturan mereka! Kita perlu menghentikan mereka sebelum dinding runtuh dan mengubur kita hidup-hidup!",
  ui_story_5082_50821101_1_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5082_50821101_2_dialog_content = "Apakah semua orang baik-baik saja?",
  ui_story_5082_50821101_3_dialog_content = "Aku baik-baik saja! Tapi, aku lebih baik tidak jatuh lagi dari ketinggian itu dalam waktu dekat.",
  ui_story_5082_50821101_4_dialog_content = "Saya baik-baik saja, Grand Marshal.",
  ui_story_5082_50821101_5_dialog_content = "Bagaimana denganmu, PlayerName?",
  ui_story_5082_50821101_6_dialog_content = "Aku baik-baik saja... Terima kasih sudah menyelamatkan, Barton. Aku pasti akan terluka parah tadi jika bukan karena kamu.",
  ui_story_5082_50821101_7_dialog_content = "Sedikit latihan tambahan dan kamu tidak perlu terlalu bergantung padaku, tahu!",
  ui_story_5082_50821101_8_dialog_content = "Ketika semua ini berakhir, saya akan pastikan untuk menambahkan latihan ketinggian ke rutinitas harianmu!",
  ui_story_5082_50821101_9_dialog_content = "Sepertinya kita mendarat di lantai terendah dari fasilitas penelitian.",
  ui_story_5082_50821101_10_dialog_content = "Mengapa mereka membutuhkan ruang yang begitu luas di sini?",
  ui_story_5082_50821101_11_dialog_content = "Saya bisa menjawab itu tanpa harus menggali ingatan saya. Inilah tempat mereka menyimpannya.",
  ui_story_5082_50821101_12_dialog_content = "Yang aku lihat hanyalah tumpukan tulang besar... Tunggu! Ini adalah Colossus yang aku rasakan sebelumnya!",
  ui_story_5082_50821101_13_dialog_content = "... Mengingat keadaan saat ini, tidak mengherankan jika Undercity mulai runtuh sendiri.",
  ui_story_5082_50821101_14_dialog_content = "... Bisakah kamu masih ingat apa yang terjadi selama eksperimen-eksperimen itu dulu, Reinhardt?",
  ui_story_5082_50821101_15_dialog_content = "Ingatan saya tentang waktu itu tidak sepenuhnya jelas, tetapi saya tahu pasti bahwa dia tidak pernah muncul lagi setelah saya menjadi Legion Commander.",
  ui_story_5082_50821101_16_dialog_content = "Namun, saya memiliki tebakan yang cukup baik tentang apa yang terjadi di sini.",
  ui_story_5082_50821101_17_dialog_content = "Ingatan saya tentang waktu itu tidak sepenuhnya jelas, tetapi saya tahu pasti bahwa dia tidak pernah muncul lagi setelah saya menjadi Legion Commander.",
  ui_story_5082_50821101_18_dialog_content = "Namun, saya memiliki tebakan yang cukup baik tentang apa yang terjadi di sini.",
  ui_story_5082_50821101_19_dialog_content = "Mereka pasti berpikir bahwa mereka telah mengubur semuanya, termasuk masa laluku...",
  ui_story_5082_50821101_20_dialog_content = "Tapi, dia masih bertahan di sini untuk alasan tertentu, seolah-olah dia ingin memberi tahu saya sesuatu.",
  ui_story_5082_50821101_21_dialog_content = "Saya pikir tempat ini, atau lebih tepatnya kecelakaan yang terjadi di sini, adalah potongan terakhir dari teka-teki yang terkait dengannya.",
  ui_story_5082_50821101_22_dialog_content = "Apa pun yang terjadi di sini membuatnya terpisah dari tubuhku...",
  ui_story_5082_50821101_23_dialog_content = "Dan juga memberikan kekuatan luar biasa yang membuat saya menjadi Grand Marshal seperti yang saya miliki hari ini.",
  ui_story_5082_50821101_24_dialog_content = "Setelah mengetahui kebenaran di balik Program Fosfer, saya tidak lagi terkejut dengan apapun tentang diri saya.",
  ui_story_5082_50821101_25_dialog_content = "Ulysses pernah mengatakan bahwa saya membawa dekade perdamaian untuk semua Illumina... Heh, tampaknya saya memang menjadi prajurit-super mereka yang sempurna.",
  ui_story_5082_50821101_26_dialog_content = "...",
  ui_story_5082_50821101_27_dialog_content = "... Jangan langsung menyimpulkan apa-apa dulu. Kami masih memiliki banyak penyelidikan yang harus dilakukan.",
  ui_story_5082_50821101_28_dialog_content = "Kami bahkan mungkin menemukan beberapa bukti baru yang membuktikan bahwa kekuatanmu berasal dari menemukan potensi sejatimu!",
  ui_story_5082_50821101_29_dialog_content = "Bulu-buluku berdiri, artinya kita tidak sendirian di sini!",
  ui_story_5082_50821101_30_dialog_content = "<color=#e8d9bb>Buzz—!</color>",
  ui_story_5082_50821101_31_dialog_content = "(Suara itu... Aku tahu apa itu...)",
  ui_story_5082_50821101_32_option_content = "Mulai telepati!",
  ui_story_5082_50821101_33_dialog_content = "... Tombak Unggul!",
  ui_story_5082_50821101_34_dialog_content = "Kamu datang, seperti yang kamu janjikan.",
  ui_story_5082_50821101_35_dialog_content = "Aku tidak berjanji apa-apa. Kaulah yang memintaku untuk menemukanmu.",
  ui_story_5082_50821101_36_dialog_content = "Tapi sekarang karena aku di sini, aku perlu mengajukan beberapa pertanyaan kepadamu.",
  ui_story_5082_50821101_37_dialog_content = "Aku tahu apa yang kamu cari. Kamu ingin belajar lebih banyak tentang masa lalu seorang gadis, atau masa lalu dua gadis yang berbeda.",
  ui_story_5082_50821101_38_dialog_content = "(Aku tahu itu! Kenangan yang hilang dari Vice dan Reinhardt terkait dengan eksperimen seleksi Navigator yang berlangsung di sini!)",
  ui_story_5082_50821101_39_dialog_content = "Beritahu aku apa yang terjadi pada mereka saat itu!",
  ui_story_5082_50821101_40_dialog_content = "Apa yang kamu cari hanyalah sejumlah kecil data yang disimpan di tempat ini.",
  ui_story_5082_50821101_41_dialog_content = "Tapi, data itu tersebar dan terpecah-pecah. Dalam keadaan rusak seperti ini, aku tidak bisa mengambilnya atau bahkan melihatnya dengan jelas.",
  ui_story_5082_50821101_42_dialog_content = "Apakah kamu meminta saya untuk membantu kamu mengambilnya kembali?",
  ui_story_5082_50821101_43_dialog_content = "Kamu yang mencari data, bukan aku.",
  ui_story_5082_50821101_44_dialog_content = "... Lalu apa yang harus saya lakukan?",
  ui_story_5082_50821101_45_dialog_content = "Orang-orang yang merobekku berusaha membentuk ulang sistemku dengan teknologi usang mereka.",
  ui_story_5082_50821101_46_dialog_content = "Dengan demikian, aku tidak bisa lagi mengembalikan mereka ke keadaan asli mereka, Caelestite.",
  ui_story_5082_50821101_47_dialog_content = "Namun, perangkat itu akan memungkinkan kamu untuk terhubung dengan saya dan menemukan apa yang kamu cari.",
  ui_story_5082_50821101_48_dialog_content = "Saya hanya perlu memakainya, bukan?",
  ui_story_5082_50821101_49_dialog_content = "Tunggu PlayerName, apa yang kaulakukan?",
  ui_story_5082_50821101_50_dialog_content = "Aku baru saja melakukan kontak dengan kesadaran Spearhead. Dia mengatakan bahwa aku mungkin bisa menemukan apa yang kita cari dengan memakai ini.",
  ui_story_5082_50821101_51_dialog_content = "Tidak ingat apa yang kamu katakan padaku sebelum kita turun ke sini?",
  ui_story_5082_50821101_52_dialog_content = "Aku memang punya, tapi dengan keadaan seperti sekarang, ini adalah petunjuk terakhir yang kita miliki.",
  ui_story_5082_50821101_53_dialog_content = "Kami berjuang keras untuk sampai di sini. Saya tidak ingin usaha semua orang sia-sia.",
  ui_story_5082_50821101_54_dialog_content = "Aku tahu ini sedikit berbahaya, tapi kita semua saling mendukung, bukan?",
  ui_story_5082_50821101_55_dialog_content = "Ini juga yang saya maksud ketika saya bilang kamu bukan satu-satunya yang mendukung Illumina. Kamu juga bisa mengandalkan kami, Reinhardt.",
  ui_story_5082_50821101_56_dialog_content = "Meskipun Spearhead mencoba melakukan apa pun, saya yakin semua orang di sini bisa menghentikannya. Lagipula, Illumina sudah pernah mengalahkannya sebelumnya, bukan?",
  ui_story_5082_50821101_57_dialog_content = "Kata-katamu bagus, Anak! Saya tidak pernah bosan melihat kamu membela teman-temanmu di saat mereka membutuhkan! Jadi apa kata kamu, Grand Marshal?",
  ui_story_5082_50821101_58_dialog_content = "Mengerti. Hanya berhati-hatilah, oke?",
  ui_story_5082_50821101_59_dialog_content = "Baiklah.",
  ui_story_5082_50821101_60_dialog_content = "(Jadi pertama-tama, aku harus menaruh ini di kepala ku, dan kemudian...)",
  ui_story_5082_50821101_61_option_content = "Psikis–",
  ui_story_5082_50821101_62_dialog_content = "Penyesuaian pada Colossus hampir selesai. Saya akan memberi tahu Petugas Teknik segera.",
  ui_story_5082_50821101_63_dialog_content = "Semua yang perlu kita lakukan sekarang adalah menemukan \"Navigator\" yang cocok, dan kita bisa mulai melakukan pengujian.",
  ui_story_5082_50821101_64_dialog_content = "Manakah subjek yang memiliki kompatibilitas tertinggi?",
  ui_story_5082_50821101_65_dialog_content = "Setelah tes yang kami lakukan pada tiga kandidat sebelumnya, mereka mulai menghilangkan informasi pribadi untuk subjek tes kami yang lain. Hanya data mereka yang sekarang dapat kami lihat.",
  ui_story_5082_50821101_66_dialog_content = "Aku ingat ketiga orang itu. Data mereka cukup menjanjikan, jika aku tidak salah ingat?",
  ui_story_5082_50821101_67_dialog_content = "Memang. Mereka berasal dari Proyek Matahari Buatan, setelah semua.",
  ui_story_5082_50821101_68_dialog_content = "Namun, ada perbedaan yang mencolok antara penampilan mereka dan hasil tes. Komite memiliki alasan untuk mencurigai bahwa mereka sengaja menyesatkan kemampuan mereka selama eksperimen.",
  ui_story_5082_50821101_69_dialog_content = "Benarkah?",
  ui_story_5082_50821101_70_dialog_content = "Kemudian, terlepas dari kompatibilitas mereka dengan Colossus, jika mereka bersedia berbohong kepada kami selama pengujian, kami tidak membutuhkan mereka.",
  ui_story_5082_50821101_71_dialog_content = "Jika Komite menemukan mereka bersalah atas ini, mereka akan membutuhkan semua keberuntungan yang bisa mereka dapatkan.",
  ui_story_5082_50821101_72_dialog_content = "(Argh, aku tak tahan dengan cara para ilmuwan ini berbicara.)",
  ui_story_5082_50821101_73_dialog_content = "(... Tapi aku harus terus menonton.)",
  ui_story_5082_50821101_74_dialog_content = "Kapan kita akan sampai pada bagian kedua gadis itu, Spearhead?",
  ui_story_5082_50821101_75_dialog_content = "Segera. Aku janji.",
  ui_story_5082_50821101_76_dialog_content = "Tunggu sinyal untuk memperpanjang, Caelestite. Cari tombol khusus, lalu tekan!",
  ui_story_5082_50821101_77_dialog_content = "Tombol spesial, huh...",
  ui_story_5082_50821101_78_dialog_content = "Di sana! Cepat, Caelestite!",
  ui_story_5082_50821101_79_dialog_content = "(Kenapa adegan ini tiba-tiba...?)",
  ui_story_5082_50821101_80_dialog_content = "Cepat... Tekan tombolnya! Cepat—!",
  ui_story_5082_50821101_81_dialog_content = "Urgh, kepalaku... Apa yang kamu pikirkan sedang kamu lakukan, Spearhead?!",
  ui_story_5082_50821101_82_dialog_content = "Tekan tombol, dan biarkan aku bebas!",
  ui_story_5082_50821101_83_dialog_content = "Sebagai senjata dari Eclipse, saya akan menghancurkan semua Aurorian atas nama tuanku!",
  ui_story_5082_50821101_84_dialog_content = "!",
  ui_story_5082_50821101_85_dialog_content = "Kematian untuk Illumina! Kematian bagi orang-orang bodoh yang tidak tahu malu itu, dan terutama pria itu!",
  ui_story_5082_50821101_86_dialog_content = "Karena meninggalkan aku dalam keadaan yang menyedihkan ini... Aku bersumpah untuk membalaskan dendam pada mereka, meski dengan harga keberadaanku sendiri!",
  ui_story_5082_50821101_87_dialog_content = "(Kebencian yang begitu kuat... Apakah aku masih ada di file memori Spearhead, atau ini kesadarannya yang sebenarnya?",
  ui_story_5082_50821101_88_dialog_content = "(... Jika ini membiarkanku melihat ini, itu berarti pikiran Colossus sudah sangat tidak stabil.)",
  ui_story_5082_50821101_89_dialog_content = "(Ini mungkin kesempatan saya untuk mencari titik lemahnya!)",
  ui_story_5082_50821101_90_option_content = "Jangkauan Telepati!",
  ui_story_5082_50821101_91_dialog_content = "<color=#e8d9bb>Tapi bukan titik lemah Spearhead, sebaliknya terdengar jeritan menusuk yang lebih jelas.</color>",
  ui_story_5082_50821101_92_dialog_content = "(Tersebut berteriak... Itu dia!)",
  ui_story_5082_50821101_93_dialog_content = "Ada di sana? Bisakah kamu mendengarku?!",
  ui_story_5082_50821101_94_dialog_content = "Reinhardt!",
  ui_story_5082_50821101_95_dialog_content = "Itu aneh. Kamu adalah pengunjung pertama saya ke tempat ini.",
  ui_story_5082_50821101_96_dialog_content = "Akhirnya saya memiliki kesempatan untuk berbicara dengan Anda!",
  ui_story_5082_50821101_97_dialog_content = "\"Akhirnya\"?",
  ui_story_5082_50821101_98_dialog_content = "Reinhardt dan aku... Kamu yang lain, maksudku! Kami telah mencari kamu selama ini!",
  ui_story_5082_50821101_99_dialog_content = "...",
  ui_story_5082_50821101_100_dialog_content = "Anak itu sudah lama memakai benda itu. Kenapa dia belum bergerak juga?",
  ui_story_5082_50821101_101_dialog_content = "Baru sekitar tiga puluh detik, Komandan Barton! Jangan terburu-buru!",
  ui_story_5082_50821101_102_dialog_content = "PlayerName mengatakan bahwa waktu berjalan berbeda di dalam dunia bawah sadar. Mari kita terus menunggu.",
  ui_story_5082_50821101_103_dialog_content = "PlayerName telah mempercayai kita, jadi kita harus melakukan hal yang sama untuknya.",
  ui_story_5082_50821101_104_dialog_content = "...",
  ui_story_5082_50821101_105_dialog_content = "Sementara itu, kita harus selalu siap untuk pertempuran jika kita akan melindunginya.",
  ui_story_5082_50821101_106_dialog_content = "Awas, arah jam 3 darimu, Barton!",
  ui_story_5082_50821101_107_dialog_content = "Ha! Memang itu yang kutunggu!",
  ui_story_5082_50821101_108_dialog_content = "<color=#e8d9bb>Dor, dor, dor!</color>",
  ui_story_5082_50821101_109_dialog_content = "<color=#e8d9bb>Tiba-tiba, puluhan mesin kecil terbang keluar dari reruntuhan Colossus.</color>",
  ui_story_5082_50821101_110_dialog_content = "Pria besar ini hanya berpura-pura mati!",
  ui_story_5082_50821101_111_dialog_content = "Lindungi PlayerName, dan bersiap untuk bertarung!",
  ui_story_5082_50821201_1_dialog_content = "Dan kurang lebih itulah yang terjadi di luar sana.",
  ui_story_5082_50821201_2_dialog_content = "Reinhardt? Tidakkah kamu mendengarku?",
  ui_story_5082_50821201_3_dialog_content = "Ya.",
  ui_story_5082_50821201_4_dialog_content = "Saya terheran-heran bahwa orang keras kepala itu benar-benar menjadi Grand Marshal.",
  ui_story_5082_50821201_5_dialog_content = "Kamu mengatakannya seolah-olah kamu sedang membicarakan tentang orang yang berbeda.",
  ui_story_5082_50821201_6_dialog_content = "Bukan berarti jauh dari kebenaran. Setelah semua, ada dunia perbedaan antara kita.",
  ui_story_5082_50821201_7_dialog_content = "Saat ini... kau benar-benar terdengar sangat mirip dengannya.",
  ui_story_5082_50821201_8_dialog_content = "Anda pasti seorang Caelestite, bukan?",
  ui_story_5082_50821201_9_dialog_content = "Aku? Y-Ya, itu benar.",
  ui_story_5082_50821201_10_dialog_content = "Pikirkan kamu bisa menggunakan kekuatanmu untuk membiarkan saya berbicara dengannya?",
  ui_story_5082_50821201_11_dialog_content = "Ada sesuatu yang ingin kukatakan padanya.",
  ui_story_5082_50821201_12_dialog_content = "Biasanya itu tidak masalah, tetapi saat ini saya menggunakan salah satu perangkat Spearhead untuk berkomunikasi dengan kamu.",
  ui_story_5082_50821201_13_dialog_content = "Aku tidak bisa membiarkan kesadaran Spearhead semakin tidak stabil, atau nantinya akan semakin sulit untuk menghentikannya.",
  ui_story_5082_50821201_14_dialog_content = "Dan setelah menemukan hubungannya dengan Eclipsite, membawa Reinhardt ke sini akan sangat berbahaya.",
  ui_story_5082_50821201_15_dialog_content = "Yang mengingatkan saya... Apa yang sebenarnya membuatmu tinggal di sini?",
  ui_story_5082_50821201_16_dialog_content = "Jadi maksudmu jika kita bisa mengalihkan perhatian Colossus, kamu akan memiliki cara untuk mengatasinya?",
  ui_story_5082_50821201_17_dialog_content = "Kurasa itu mungkin... Tapi bagaimana kamu akan menarik perhatian Spearhead?",
  ui_story_5082_50821201_18_dialog_content = "Seperti ini, tentu saja—!",
  ui_story_5082_50821201_19_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5082_50821201_20_dialog_content = "<color=#e8d9bb>Saat api liar cepat menyebar ke seluruh ruangan, dia mulai tertawa gila di tengah kobaran api yang mengamuk.</color>",
  ui_story_5082_50821201_21_dialog_content = "Ah, sudah lama sekali sejak aku merasa sebaik ini!",
  ui_story_5082_50821201_22_dialog_content = "Maaf Colossus, tapi setelah mendengar bahwa kamu berteman dengan Eclipsite, aku tidak punya sedikit pun simpati untukmu lagi.",
  ui_story_5082_50821201_23_dialog_content = "Aku tidak bisa menyakiti tubuh fisikmu, jadi membakar seluruh pikiranmu harus cukup! Sakit, bukan?!",
  ui_story_5082_50821201_24_dialog_content = "Anda! Beraninya kamu—!",
  ui_story_5082_50821201_25_dialog_content = "Kamu hanyalah data sisa dalam kesadaranku! Saya bisa menghapus keberadaanmu kapan saja sesuka hati!",
  ui_story_5082_50821201_26_dialog_content = "Ruang itu menghilang... Spearhead pasti sedang menghapus data!",
  ui_story_5082_50821201_27_dialog_content = "Kesadaranmu juga disimpan di sini, bukan? Apakah kamu yakin ini baik-baik saja?",
  ui_story_5082_50821201_28_dialog_content = "Aku akan baik-baik saja selama itu tidak menangkapku.",
  ui_story_5082_50821201_29_dialog_content = "Maksudmu apa, hah?",
  ui_story_5082_50821201_30_dialog_content = "Maksudku adalah—",
  ui_story_5082_50821201_31_dialog_content = "Lari!!!",
  ui_story_5082_50821201_32_dialog_content = "Kamu terdengar begitu percaya diri tadi! Apakah ini benar-benar ide terbaik yang bisa kamu pikirkan?!",
  ui_story_5082_50821201_33_dialog_content = "Hahahaha!",
  ui_story_5082_50821201_34_dialog_content = "Meong!",
  ui_story_5082_50821201_35_dialog_content = "Philyshy! Bagaimana kamu bisa bermain dengan benda-benda itu saat mereka menyerang kita?!",
  ui_story_5082_50821201_36_dialog_content = "Maaf, mereka hanya terlihat seperti ekor panjang dan besar ketika mereka saling berhubungan seperti itu! Saya tidak bisa menahan diri!",
  ui_story_5082_50821201_37_dialog_content = "Masuk akal jika kamu mengatakannya seperti itu. Colossus pasti mengendalikan setiap \"ekor\" itu untuk menyerang kita...",
  ui_story_5082_50821201_38_dialog_content = "Bahkan jika ia tidak bisa menggerakkan tubuhnya, pusat komandonya masih cukup fungsional untuk menyerang kita dengan sisa-sisa kerangkanya!",
  ui_story_5082_50821201_39_dialog_content = "Itulah pikiranku persis!",
  ui_story_5082_50821201_40_dialog_content = "Hmph! Sejauh ini, Colossus yang sudah rusak ini hanya bagus untuk mengibaskan ekornya pada kita sekarang!",
  ui_story_5082_50821201_41_dialog_content = "<color=#e8d9bb>Lubang, tepuk, lubang, tepuk—!</color>",
  ui_story_5082_50821201_42_dialog_content = "Hah? PlayerName?!",
  ui_story_5082_50821201_43_dialog_content = "Dari semua waktu untuk muncul— Tunggu, jangan bergerak!",
  ui_story_5082_50821201_44_dialog_content = "<color=#e8d9bb>Meretih-</color>",
  ui_story_5082_50821201_45_dialog_content = "... Arus listrik?",
  ui_story_5082_50821201_46_dialog_content = "Jauhkan dirimu dari ekor itu, Philyshy! Ada yang tidak beres dengan itu!",
  ui_story_5082_50821201_47_dialog_content = "Buzz—Buzz—",
  ui_story_5082_50821201_48_dialog_content = "Tulang-tulangnya sedang berkembang! Tetap berjaga, setiap orang; Colossus mungkin akan menyerang sebentar lagi—",
  ui_story_5082_50821201_49_dialog_content = "<color=#e8d9bb>Duar! Duar! Duar!</color>",
  ui_story_5082_50821201_50_dialog_content = "Aku bisa mencium bau ledakan yang datang dari dalam dinding!",
  ui_story_5082_50821201_51_dialog_content = "Struktur ini akan runtuh! Kita perlu membersihkan kabel-kabel ini dan mencari tempat untuk berlindung!",
  ui_story_5082_50821201_52_dialog_content = "Tapi bagaimana dengan PlayerName? Lupakan, aku akan membawanya sendiri!",
  ui_story_5082_50821201_53_dialog_content = "Hei! Grand Marshal! Sekarang bukan waktunya untuk—",
  ui_story_5082_50821201_54_dialog_content = "... Saya bisa mendengar hitungan mundur.",
  ui_story_5082_50821201_55_dialog_content = "Reinhardt!",
  ui_story_5082_50821201_56_dialog_content = "... Arus listrik, ledakan, dan... teriakannya.",
  ui_story_5082_50821201_57_dialog_content = "Reinhardt!!!",
  ui_story_5082_50821201_58_dialog_content = "Hal yang sama terjadi saat itu.",
  ui_story_5082_50821201_59_dialog_content = "<color=#e8d9bb>Dinding di dekatnya meledak, mengirim kabel dan batu jatuh menabrak tanah.</color>",
  ui_story_5082_50821201_60_dialog_content = "Endless Slash!",
  ui_story_5082_50821201_61_dialog_content = "<color=#e8d9bb>Barton membelah sepotong besar puing yang jatuh menjadi dua sebelum mendarat di atasnya.</color>",
  ui_story_5082_50821201_62_dialog_content = "<color=#e8d9bb>Kemudian dia terus menjaga momentumnya.</color>",
  ui_story_5082_50821201_63_dialog_content = "Barton...",
  ui_story_5082_50821201_64_dialog_content = "Sekarang bukan waktunya untuk melamun! Juga, apa pendapatmu tentang teknikku barusan?",
  ui_story_5082_50821201_65_dialog_content = "Hahaha, itu seperti biasanya sangat ganas! Terima kasih, Barton.",
  ui_story_5082_50821201_66_dialog_content = "Terima kasih karena selalu bertarung di sisiku!",
  ui_story_5082_50821201_67_dialog_content = "Ini hanya alami, bukan? Ayo, tempat ini terlalu berbahaya untuk—",
  ui_story_5082_50821201_68_dialog_content = "Jangan khawatir, aku baik-baik saja sekarang.",
  ui_story_5082_50821201_69_dialog_content = "Aku hanya perlu mengingat kembali apa yang terjadi saat itu untuk terakhir kalinya.",
  ui_story_5082_50821201_70_dialog_content = "<color=#e8d9bb>Bangunan itu bergemuruh dan runtuh ketika dinding-dinding mulai roboh.</color>",
  ui_story_5082_50821201_71_dialog_content = "<color=#e8d9bb>Seperti mata badai, Reinhardt berdiri dengan tenang di tengah kekacauan; bahkan udara di sekelilingnya tampak sangat tenang.</color>",
  ui_story_5082_50821201_72_dialog_content = "Pergi berlindung.",
  ui_story_5082_50821201_73_dialog_content = "Aku masih berutang pertandingan ulang pada pria ini.",
  ui_story_5082_50821202_1_dialog_content = "Tempat apa ini...?",
  ui_story_5082_50821202_2_dialog_content = "Ini adalah ruang yang dibuat oleh alat tersebut. Ia menggunakan data sistem Spearhead sebagai fondasinya.",
  ui_story_5082_50821202_3_dialog_content = "Berkat kamu yang melukai Spearhead dari luar, kita berhasil berlindung dengan aman di sini.",
  ui_story_5082_50821202_4_dialog_content = "Kekuatanmu jauh lebih mengesankan daripada yang kubayangkan.",
  ui_story_5082_50821202_5_dialog_content = "Tidak hanya bisa membantu saya mengendalikan kesadaran Spearhead, tetapi kamu juga bisa menariknya ke sini segera setelah dia melepaskan Lumina-nya.",
  ui_story_5082_50821202_6_dialog_content = "Ini menyelesaikan pertempuran di luar sambil juga memastikan bahwa operasi perangkat tetap tidak terganggu.",
  ui_story_5082_50821202_7_dialog_content = "Saya yakin Anda akan mencapai hal-hal yang lebih luar biasa dengan kekuatan ini di masa depan.",
  ui_story_5082_50821202_8_dialog_content = "Terima kasih, tapi kaulah yang datang dengan rencana ini... yang menurutku masih terlalu berbahaya! Bagaimana jika datamu terhapus?!",
  ui_story_5082_50821202_9_dialog_content = "Tidak ada pertempuran tanpa risiko.",
  ui_story_5082_50821202_10_dialog_content = "Selain itu, semuanya berhasil pada akhirnya, 'kan?",
  ui_story_5082_50821202_11_dialog_content = "Kami berhasil menghentikan pertempuran di sini dan di luar sana, dan saya bisa belajar lebih banyak tentang kemampuan Caelestite-mu.",
  ui_story_5082_50821202_12_dialog_content = "Dan sekarang setelah aku tahu aku bisa mempercayaimu, aku bisa dengan aman mengatakan...",
  ui_story_5082_50821202_13_dialog_content = "Bahwa orang ini tidak banyak berubah dari apa yang aku ingat tentangnya.",
  ui_story_5082_50821202_14_dialog_content = "Lama tak jumpa, Reinhardt.",
  ui_story_5082_50821202_15_dialog_content = "Rasanya sedikit aneh mendengar itu, mengingat aku baru mulai mengingatmu hari ini...",
  ui_story_5082_50821202_16_dialog_content = "Tapi lama tak jumpa, Reinhardt.",
  ui_story_5082_50821202_17_dialog_content = "Uh, Reinhardt...?",
  ui_story_5082_50821202_18_dialog_content = "Ya?",
  ui_story_5082_50821202_19_dialog_content = "...",
  ui_story_5082_50821202_20_dialog_content = "Hahahaha! Jika itu membuat segalanya lebih mudah, kamu bisa memanggilku \"Renegade\"!",
  ui_story_5082_50821202_21_dialog_content = "Begitulah yang biasanya semua orang panggil aku di belakangku. Aku tahu mereka tidak bermaksud baik dengannya, tapi aku selalu menyukai nama itu.",
  ui_story_5082_50821202_22_dialog_content = "Aku hanya tidak tahu jika kamu masih ingat tentang itu, Reinhardt.",
  ui_story_5082_50821202_23_dialog_content = "Aku mengerti. Kamu tidak yakin apakah aku masih orang yang sama yang pernah kamu kenal, dan aku baru saja ingat bahwa kamu pernah ada.",
  ui_story_5082_50821202_24_dialog_content = "Jadi, mengapa kita tidak saling mengenal lagi?",
  ui_story_5082_50821202_25_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5082_50821202_26_dialog_content = "Apa arti dari gemuruh ini, PlayerName?",
  ui_story_5082_50821202_27_dialog_content = "Ini Spearhead... Ia menemukan kami!",
  ui_story_5082_50821202_28_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5082_50821202_29_option_content = "Force Boost!",
  ui_story_5082_50821202_30_dialog_content = "Itu kamu orang-orang!",
  ui_story_5082_50821202_31_dialog_content = "Kalianlah yang menghancurkan tubuhku! Kalianlah yang menguburku hidup-hidup selama tiga belas tahun!",
  ui_story_5082_50821202_32_dialog_content = "Sekarang mati—!",
  ui_story_5082_50821202_33_option_content = "Force Boost!",
  ui_story_5082_50821202_34_dialog_content = "Argh!",
  ui_story_5082_50821202_35_dialog_content = "Saya bisa membuat penghalang untuk menjaga Spearhead tetap jauh untuk saat ini, tetapi ini masih wilayahnya.",
  ui_story_5082_50821202_36_dialog_content = "Dengan seberapa kacau kesadarannya, saya tidak yakin berapa lama lagi saya bisa bertahan—",
  ui_story_5082_50821202_37_dialog_content = "Siapa yang memintamu untuk menghentikannya?",
  ui_story_5082_50821202_38_dialog_content = "Jika seseorang memukulmu, bukankah reaksi pertamamu harus membalas pukulan mereka?",
  ui_story_5082_50821202_39_dialog_content = "Tidak!",
  ui_story_5082_50821202_40_dialog_content = "Data kamu masih disimpan di sini! Jika kita melawan sekarang—",
  ui_story_5082_50821202_41_dialog_content = "Tidak ada yang lebih sia-sia daripada ragu-ragu dalam pertempuran.",
  ui_story_5082_50821202_42_dialog_content = "Jika kamu memiliki cara untuk menang, maka gunakanlah.",
  ui_story_5082_50821202_43_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5082_50821202_44_dialog_content = "Pemberontak!",
  ui_story_5082_50821202_45_dialog_content = "... Sial!",
  ui_story_5082_50821202_46_dialog_content = "<color=#e8d9bb>Api yang membara kembali membubung tinggi.</color>",
  ui_story_5082_50821202_47_dialog_content = "<color=#e8d9bb>Meskipun kobaran api hanyalah representasi dari data Spearhead yang dihancurkan dalam ruang pikiran, nyala apinya lebih mempesona daripada api nyata.</color>",
  ui_story_5082_50821202_48_dialog_content = "<color=#e8d9bb>Seperti tiran yang tak terbendung, dia menggunakan kekuatan api untuk melahap segala yang ada di jalannya.</color>",
  ui_story_5082_50821202_49_dialog_content = "Apa kau sudah gila?! Keberadaanmu hanyalah serangkaian kode dalam sistemku! Tanpa tubuh fisik, kau akan menghilang!",
  ui_story_5082_50821202_50_dialog_content = "Tapi kita juga akan menang. Tubuhmu sudah hancur lama sekali, dan pikiranmu tidak pernah bisa mengimbangi saya.",
  ui_story_5082_50821202_51_dialog_content = "Kamu benar-benar #%%^$&... Kehilangan akal sehatmu￥%#......%......%！",
  ui_story_5082_50821202_52_dialog_content = "Hahahaha! Maaf Spearhead, tapi kita menang.",
  ui_story_5082_50821202_53_dialog_content = "#%%^$&......!!!",
  ui_story_5082_50821202_54_dialog_content = "Aku tahu kita tidak punya banyak waktu tersisa, PlayerName, tapi bisakah kamu meminjamkan kekuatanmu satu kali lagi?",
  ui_story_5082_50821202_55_dialog_content = "Sebelum aku pergi, aku ingin lebih mengenal diriku yang lain sedikit lebih baik.",
  ui_story_5082_50821202_56_dialog_content = "Tentu!",
  ui_story_5082_50821202_57_dialog_content = "Tidak, tunggu... Itu tidak benar.",
  ui_story_5082_50821202_58_dialog_content = "<color=#e8d9bb>Renegade berjalan tepat menuju Reinhardt. Dari jarak ini, pantulan mereka bisa terlihat di mata satu sama lain.</color>",
  ui_story_5082_50821202_59_dialog_content = "Saya rasa ada cara yang lebih baik untuk kita saling memahami.",
  ui_story_5082_50821202_60_dialog_content = "...",
  ui_story_5082_50821202_61_dialog_content = "Ingat tahun itu kamu pergi untuk pemeriksaan agar bisa masuk ke akademi?",
  ui_story_5082_50821202_62_dialog_content = "Itu saat kita pertama kali bertemu.",
  ui_story_5082_50821202_63_dialog_content = "Setiap orang lainnya sudah pulang ke rumah setelah ujian mereka.",
  ui_story_5082_50821202_64_dialog_content = "Tetapi dokter meminta saya untuk tetap tinggal.",
  ui_story_5082_50821202_65_dialog_content = "Ada apa?",
  ui_story_5082_50821202_66_dialog_content = "Aku tidak tahu.",
  ui_story_5082_50821202_67_dialog_content = "Tapi... Aku sering demam, jadi mungkin ada yang salah dengan diriku?",
  ui_story_5082_50821202_68_dialog_content = "Saya harap itu tidak menghalangi saya masuk akademi.",
  ui_story_5082_50821202_69_dialog_content = "Tidak akan.",
  ui_story_5082_50821202_70_dialog_content = "... Bagaimana kau bisa tahu itu?",
  ui_story_5082_50821202_71_dialog_content = "Karena aku bisa melihatnya.",
  ui_story_5082_50821202_72_dialog_content = "?",
  ui_story_5082_50821202_73_dialog_content = "Kamu tidak sakit atau apa pun. Sumber demammu—",
  ui_story_5082_50821202_74_dialog_content = "Apakah naga merah yang membakar di punggungmu.",
  ui_story_5082_50821301_1_dialog_content = "<color=#e8d9bb>Latihan Tembak Langsung</color>",
  ui_story_5082_50821301_2_dialog_content = "Katakan padaku, apa yang lebih sakit sekarang? Lukamu atau rasa laparmu?",
  ui_story_5082_50821301_3_dialog_content = "Diam.",
  ui_story_5082_50821301_4_dialog_content = "Oh, aku mengerti. Kamu hampir tidak bisa berdiri sekarang, bukan? Kasihan sekali.",
  ui_story_5082_50821301_5_dialog_content = "Aku bilang diam!",
  ui_story_5082_50821301_6_dialog_content = "Apakah ini benar-benar semua yang bisa kamu tanggung?",
  ui_story_5082_50821301_7_dialog_content = "Jika kau kalah seburuk ini dalam pertempuran, diejek hanyalah masalah terkecilmu.",
  ui_story_5082_50821301_8_dialog_content = "Aku tidak akan membuat kesalahan yang sama lagi.",
  ui_story_5082_50821301_9_dialog_content = "Oh benarkah? Karena menurutku, kemampuanmu cacat pada level paling dasar.",
  ui_story_5082_50821301_10_dialog_content = "Jika aku bisa menipumu seperti ini, apa yang membuatmu berpikir kamu memiliki kesempatan dalam pertempuran nyata melawan Eclipsite yang sebenarnya? Mereka seribu kali lebih kejam daripada aku, aku janji.",
  ui_story_5082_50821301_11_dialog_content = "Jika Aurorian bisa menggunakan pengetahuan dari buku teks untuk mengalahkan mereka, kita pasti sudah menang perang sejak lama.",
  ui_story_5082_50821301_12_dialog_content = "Garis pemikiran itu hanya mengarah ke jalan buntu.",
  ui_story_5082_50821301_13_dialog_content = "Jadi jika kamu ingin bertahan dan mewujudkan ambisimu, maka kamu perlu menjadi lebih kuat. Lebih kuat dari Aurorian terkuat di dunia.",
  ui_story_5082_50821301_14_dialog_content = "Dan kamu harus lebih licik daripada Eclipsite paling jahat di malam abadi.",
  ui_story_5082_50821301_15_dialog_content = "Hanya ketika Anda mencapai ketinggian yang tak terbayangkan, Anda akan bisa melancarkan serangan terakhir.",
  ui_story_5082_50821301_16_dialog_content = "Kamu paham?",
  ui_story_5082_50821301_17_dialog_content = "<color=#e8d9bb>Lapangan Latihan Akademi Militer</color>",
  ui_story_5082_50821301_18_dialog_content = "Latihan hari ini sudah selesai, sekarang kembali ke barakmu! Jam malam sudah berlaku, jadi tidak boleh keluar setelah gelap!",
  ui_story_5082_50821301_19_dialog_content = "Ssst! Ayo lihat apa yang terjadi di gerbang akademi, dan jangan biarkan pengajar melihatmu!",
  ui_story_5082_50821301_20_dialog_content = "Ini adalah 1st Legion... Apa yang mereka lakukan di akademi?",
  ui_story_5082_50821301_21_dialog_content = "Dan mengapa mereka pergi dengan membawa persediaan senjata kita?",
  ui_story_5082_50821301_22_dialog_content = "Banyak petugas yang datang dan pergi sejak sore tadi.",
  ui_story_5082_50821301_23_dialog_content = "Mereka mengumpulkan sejumlah besar sumber daya dan peralatan. Bahkan beberapa instruktur terkuat akademi belum kembali setelah pergi bersama mereka.",
  ui_story_5082_50821301_24_dialog_content = "Jika dugaanku benar, akan ada pertempuran di Kota Gannon malam ini.",
  ui_story_5082_50821301_25_dialog_content = "...",
  ui_story_5082_50821301_26_dialog_content = "Saya melihat peta pertahanan di kantor beberapa waktu lalu.",
  ui_story_5082_50821301_27_dialog_content = "Ada area yang kurang terjaga tepat di barat gerbang kota. Tempat itu tidak akan bertahan jika diserang.",
  ui_story_5082_50821301_28_dialog_content = "Ini adalah tempat yang sempurna bagi kita untuk menunjukkan kepada Federasi apa yang bisa kita lakukan!",
  ui_story_5082_50821301_29_dialog_content = "Aku pergi, tapi bukan karena alasan seperti itu.",
  ui_story_5082_50821301_30_dialog_content = "Sebagai seorang prajurit Illumina, perintahku adalah melindungi rakyat kita dengan segala cara.",
  ui_story_5082_50821301_31_dialog_content = "<color=#e8d9bb>Ruang Operasi Khusus 3</color>",
  ui_story_5082_50821301_32_dialog_content = "Groar!",
  ui_story_5082_50821301_33_dialog_content = "Argh…",
  ui_story_5082_50821301_34_dialog_content = "(Pikiranku... Mulai kabur...)",
  ui_story_5082_50821301_35_dialog_content = "Denyut jantung dan tekanan darah subjek menurun, dan pernapasannya menjadi tidak teratur–",
  ui_story_5082_50821301_36_dialog_content = "(Bagaimana bisa aku membiarkan diriku mati dalam eksperimen bodoh seperti ini...?)",
  ui_story_5082_50821301_37_dialog_content = "<color=#e8d9bb>Bip—</color>",
  ui_story_5082_50821301_38_dialog_content = "Tanda-tanda vital tidak lagi terdeteksi. Kematian subjek sekarang sudah dikonfirmasi.",
  ui_story_5082_50821301_39_dialog_content = "...",
  ui_story_5082_50821301_40_dialog_content = "—!",
  ui_story_5082_50821301_41_dialog_content = "Apa-apaan kau ini?!",
  ui_story_5082_50821301_42_dialog_content = "Ini bukan waktumu untuk mati!",
  ui_story_5082_50821301_43_dialog_content = "Buka matamu sekarang juga! Para ilmuwan yang tidak berperasaan itu hanya menonton semua ini terjadi, bergumam pada diri mereka sendiri tanpa sedikit pun penyesalan!",
  ui_story_5082_50821301_44_dialog_content = "Mereka memperlakukanmu seperti alat untuk kenyamanan mereka! Dibandingkan dengan data yang mereka incar, hidupmu tidak berarti apa-apa!",
  ui_story_5082_50821301_45_dialog_content = "Jika kamu tidak ingin mati dengan cara yang tidak berarti, bangunlah sekarang juga!",
  ui_story_5082_50821301_46_dialog_content = "<color=#e8d9bb>... Bip! Bip... Bip... Bip...</color>",
  ui_story_5082_50821301_47_dialog_content = "... Dia masih hidup?",
  ui_story_5082_50821301_48_dialog_content = "Ugh...",
  ui_story_5082_50821301_49_dialog_content = "Mereka benar-benar meningkatkan tingkat kesulitan untuk latihan \"kekuatan ledakan\" yang disebut-sebut ini.",
  ui_story_5082_50821301_50_dialog_content = "Tapi setidaknya... Akhirnya selesai juga.",
  ui_story_5082_50821301_51_dialog_content = "Menarik. Tanda-tanda vitalnya sempat benar-benar hilang barusan, namun dia mampu memulihkan kesadaran dan melanjutkan perjuangan...",
  ui_story_5082_50821301_52_dialog_content = "Kamu melihat itu, 'kan?",
  ui_story_5082_50821301_53_dialog_content = "Bajingan itu tampak lebih kecewa sekarang daripada saat dia pikir kamu sudah mati.",
  ui_story_5082_50821301_54_dialog_content = "Jadi, jangan mati begitu saja lagi.",
  ui_story_5082_50821301_55_dialog_content = "(Hmm...)",
  ui_story_5082_50821301_56_dialog_content = "<color=#e8d9bb>Laboratorium Rahasia</color>",
  ui_story_5082_50821301_57_dialog_content = "Kamu selalu menyuruh kami untuk lebih jujur padamu, tapi kamu tidak pernah memberi tahu kami saat ada sesuatu yang salah denganmu.",
  ui_story_5082_50821301_58_dialog_content = "... Apakah itu jelas?",
  ui_story_5082_50821301_59_dialog_content = "Helios juga melihatnya. Dia hanya tidak mengatakan apa-apa karena dia tidak ingin mengganggu kamu.",
  ui_story_5082_50821301_60_dialog_content = "Tapi aku tidak sebaik dia dalam hal pertimbangan, itulah sebabnya aku memintamu sekarang.",
  ui_story_5082_50821301_61_dialog_content = "Apa yang sebenarnya terjadi, Reinhardt?",
  ui_story_5082_50821301_62_dialog_content = "Tes macam apa yang mereka lakukan padamu sehingga kamu terus muncul dengan luka di seluruh tubuhmu?",
  ui_story_5082_50821301_63_dialog_content = "Kamu adalah orang terkuat di antara teman sebaya, tanpa diragukan lagi. Jadi, mengapa mereka melakukan ini padamu?",
  ui_story_5082_50821301_64_dialog_content = "...",
  ui_story_5082_50821301_65_dialog_content = "Karena meski kamu kuat, kamu memiliki kecenderungan untuk bertindak sendiri saat mereka membutuhkan kamu untuk mengikuti perintah.",
  ui_story_5082_50821301_66_dialog_content = "Mereka ingin meredam semangatmu, menghancurkan kebanggaanmu, dan mengubahmu menjadi seorang prajurit kecil yang baik seperti setiap orang lainnya.",
  ui_story_5082_50821301_67_dialog_content = "Tapi kamu tidak memberi mereka apa yang mereka inginkan, dan sekarang mereka takut padamu. Mereka tidak memerlukan pedang yang melukai pemegangnya.",
  ui_story_5082_50821301_68_dialog_content = "Jika kamu tidak ingin dilempar ke dalam tungku, untuk dibentuk sesuai keinginan mereka, kamu harus berdiri teguh. Ingatlah siapa dirimu, dan terus bertahan.",
  ui_story_5082_50821301_69_dialog_content = "Aku masih belum memahami situasi secara keseluruhan.",
  ui_story_5082_50821301_70_dialog_content = "Jadi, bisa kita tunda jawaban atas pertanyaan itu, Denier? Aku janji akan memberitahu kamu segalanya setelah aku tahu yang sebenarnya.",
  ui_story_5082_50821301_71_dialog_content = "Nah, mencampuri urusan rahasia orang lain tanpa izin adalah pelanggaran tata cara ilmiah.",
  ui_story_5082_50821301_72_dialog_content = "Tapi jika sesuatu terjadi padamu, maka aku akan membuang segala keraguan tanpa mempedulikan siapa pun yang menuntut pertanggungjawaban dariku.",
  ui_story_5082_50821301_73_dialog_content = "Aku janji aku akan berhati-hati.",
  ui_story_5082_50821301_74_dialog_content = "(Hal yang sama berlaku untuk kalian berdua.)",
  ui_story_5082_50821301_75_dialog_content = "<color=#e8d9bb>???</color>",
  ui_story_5082_50821301_76_dialog_content = "Dimana saya...?",
  ui_story_5082_50821301_77_dialog_content = "Apa yang sedang saya lakukan...?",
  ui_story_5082_50821301_78_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_79_dialog_content = "!",
  ui_story_5082_50821301_80_dialog_content = "Auuuum!",
  ui_story_5082_50821301_81_dialog_content = "Aku harus... Melawan Eclipsite...!",
  ui_story_5082_50821301_82_dialog_content = "Graaah—",
  ui_story_5082_50821301_83_dialog_content = "Bertarung...",
  ui_story_5082_50821301_84_dialog_content = "Groar!",
  ui_story_5082_50821301_85_dialog_content = "Bertarung!",
  ui_story_5082_50821301_86_dialog_content = "Ini belum berakhir...",
  ui_story_5082_50821301_87_dialog_content = "Aku harus terus berjalan—!",
  ui_story_5082_50821301_88_dialog_content = "Bangun!",
  ui_story_5082_50821301_89_dialog_content = "Sadarkan dirimu! Jangan biarkan mereka menjadikanmu alat lain yang bisa mereka gunakan!",
  ui_story_5082_50821301_90_dialog_content = "... Aku tahu.",
  ui_story_5082_50821301_91_dialog_content = "Ini hanya refleks buruk yang belum bisa aku hilangkan. Aku tidak akan membiarkan hal semacam ini mengendalikan diriku.",
  ui_story_5082_50821301_92_dialog_content = "Tapi apa yang sedang kamu lakukan di sini juga?",
  ui_story_5082_50821301_93_dialog_content = "Tunggu, jam berapa ini?! Rencananya...",
  ui_story_5082_50821301_94_dialog_content = "Hari ini adalah hari mereka akan menggunakan gadis kecil itu untuk mengaktifkan Colossus.",
  ui_story_5082_50821301_95_dialog_content = "Saya harus tetap pada rencana— Nngh!",
  ui_story_5082_50821301_96_dialog_content = "Agen pemati rasa belum selesai bekerja, jadi berhenti mengoceh.",
  ui_story_5082_50821301_97_dialog_content = "Setelah semua, jelas bahwa seseorang mengetahui tentang rencana kami.",
  ui_story_5082_50821301_98_dialog_content = "... Di mana yang lainnya?",
  ui_story_5082_50821301_99_dialog_content = "Seperti apa saya ini, sistem pengawasan Illumina? Saya hanya bisa mengawasi Anda.",
  ui_story_5082_50821301_100_dialog_content = "Kita masih dekat dengan basis. Latihan harianmu membuat mereka mudah untuk melacakmu, tapi teman-temanmu masih punya waktu untuk kembali.",
  ui_story_5082_50821301_101_dialog_content = "Jika kamu ingin memeriksa mereka, pilihan satu-satunya adalah melarikan diri.",
  ui_story_5082_50821301_102_dialog_content = "Sekarang cepat! Setelah peneliti itu datang, akan terlambat.",
  ui_story_5082_50821301_103_dialog_content = "...",
  ui_story_5082_50821301_104_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5082_50821301_105_dialog_content = "Oh? Sudah bangun, begitu. Sepertinya tubuhmu jadi jauh lebih kuat belakangan ini.",
  ui_story_5082_50821301_106_dialog_content = "Silakan berbaring lagi. Kami akan menyuntikkan pengobatan berikutnya pada Anda sebentar lagi.",
  ui_story_5082_50821301_107_dialog_content = "... Maaf, tapi perawatan yang baru-baru ini aku terima...",
  ui_story_5082_50821301_108_dialog_content = "Suppressant #05... Putaran 13 dari pengobatan...",
  ui_story_5082_50821301_109_dialog_content = "Apa dengan tatapan menyedihkan di wajahmu itu?! Dia punya pistol, jadi ambil dan bunuh dia! Itu akan menjadi kesempatan kita untuk kabur!",
  ui_story_5082_50821301_110_dialog_content = "<color=#e8d9bb>Reinhardt berdiri dan menarik lengan peneliti, tetapi segera pusing karena rasa pusing yang luar biasa.</color>",
  ui_story_5082_50821301_111_dialog_content = "<color=#e8d9bb>Dua peneliti lagi bergegas masuk ke ruangan. Sementara salah satu dari mereka menenangkan Reinhardt, yang lainnya menjauhkan senjata dari dia—</color>",
  ui_story_5082_50821301_112_dialog_content = "(Tidak—!)",
  ui_story_5082_50821301_113_dialog_content = "<color=#e8d9bb>Sejumlah besar supresan disuntikkan ke dalam tubuh Renegade.</color>",
  ui_story_5082_50821301_114_dialog_content = "Kamu...",
  ui_story_5082_50821301_115_dialog_content = "Lari!",
  ui_story_5082_50821301_116_dialog_content = "Jangan biarkan mereka mencuri kekuatanmu! Sekarang lari—!!",
  ui_story_5082_50821301_117_dialog_content = "<color=#e8d9bb>Reinhardt menggigit giginya saat dia berlari keluar dari pintu.</color>",
  ui_story_5082_50821301_118_dialog_content = "Hosh... Hosh...",
  ui_story_5082_50821301_119_dialog_content = "Tubuhku... Terbakar...",
  ui_story_5082_50821301_120_dialog_content = "(Dan pikiranku... Mengapa ini...)",
  ui_story_5082_50821301_121_dialog_content = "(Tidak, ini tidak benar... Aku tidak di lapangan latihan, tapi aku...)",
  ui_story_5082_50821301_122_dialog_content = "<color=#e8d9bb>Dor! Dor!</color>",
  ui_story_5082_50821301_123_dialog_content = "!",
  ui_story_5082_50821301_124_dialog_content = "Jangan berhenti!",
  ui_story_5082_50821301_125_dialog_content = "Ini kamu! Kau baik-baik saja?!",
  ui_story_5082_50821301_126_dialog_content = "Berhenti bicara dan lari!",
  ui_story_5082_50821301_127_dialog_content = "... Baik.",
  ui_story_5082_50821301_128_dialog_content = "Tidak ada jalan kembali untuk kita sekarang. Kita harus terus masuk lebih dalam.",
  ui_story_5082_50821301_129_dialog_content = "Helios menandai ruangan tempat mereka menyimpan Colossus di peta miliknya. Itu berada di ujung lain dari basis penelitian, dan dekat dengan bagian luar.",
  ui_story_5082_50821301_130_dialog_content = "Kita bisa mencari jalan keluar dari sana, dan kemudian menemukan Undercity lain—",
  ui_story_5082_50821301_131_dialog_content = "\"Rencana B\"...",
  ui_story_5082_50821301_132_dialog_content = "Saya yakin Anda menyesal tidak mendengarkan Denier atau mempertimbangkan rencananya lebih jauh, bukan?",
  ui_story_5082_50821301_133_dialog_content = "Saya lebih menyalahkan diri sendiri daripada apapun.",
  ui_story_5082_50821301_134_dialog_content = "Ini semua karena ketidaktahuan dan kebanggaan saya.",
  ui_story_5082_50821301_135_dialog_content = "Ketidaktahuan saya membuat saya mengikuti perintah secara membabi buta...",
  ui_story_5082_50821301_136_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_137_dialog_content = "Reinhardt, melapor untuk tugas.",
  ui_story_5082_50821301_138_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_139_dialog_content = "Maaf, aku sedikit lelah jadi aku akan langsung tidur.",
  ui_story_5082_50821301_140_dialog_content = "<color=#e8d9bb>Brr-brr-brrrrr—</color>",
  ui_story_5082_50821301_141_dialog_content = "...",
  ui_story_5082_50821301_142_dialog_content = "Dan kebanggaan saya menipu saya untuk berpikir bahwa saya bisa mencapai impian saya suatu hari nanti selama saya bertahan dengan itu.",
  ui_story_5082_50821301_143_dialog_content = "Eclipsite yang sedang kamu hadapi saat ini adalah spesimen terlemah dalam eksperimen.",
  ui_story_5082_50821301_144_dialog_content = "Pelatihan ini dirancang untuk membentuk kamu menjadi prajurit paling kuat Illumina. Jika kamu tidak mampu mengalahkan mereka, kami harus mempertimbangkan kembali kandidatmu untuk program ini.",
  ui_story_5082_50821301_145_dialog_content = "Heh... Siapa bilang aku tidak bisa mengalahkan mereka?!",
  ui_story_5082_50821301_146_dialog_content = "Ayo, lagi!",
  ui_story_5082_50821301_147_dialog_content = "Ternyata ketika orang-orang terperangkap dalam jaring, \"perjuangan\" mereka yang disebut-sebut itu tidak lain hanya mempercepat mereka untuk tercekik.",
  ui_story_5082_50821301_148_dialog_content = "Hentikan pembicaraan seperti itu! Ini bukan waktu dan tempatnya untuk merasa kasihan pada diri sendiri!",
  ui_story_5082_50821301_149_dialog_content = "Mimpi tidak harus menjadi hal yang mustahil untuk dicapai, kamu tahu.",
  ui_story_5082_50821301_150_dialog_content = "?",
  ui_story_5082_50821301_151_dialog_content = "Saya tidak tahan mengikuti rutinitas, dan saya benci perasaan menjalani hidup seolah-olah saya sedang membaca dari naskah.",
  ui_story_5082_50821301_152_dialog_content = "Jika mereka terus mencoba memasukkan saya ke dalam kotak, maka saya akan terus keluar dari kotak itu, bahkan jika saya harus membakarnya hingga menjadi abu.",
  ui_story_5082_50821301_153_dialog_content = "Tapi, kamu berbeda.",
  ui_story_5082_50821301_154_dialog_content = "Meskipun semua orang mengagumi dan memuji kekuatan serta kecerdasanmu, kamu tetap saja sama bodohnya dengan orang lain.",
  ui_story_5082_50821301_155_dialog_content = "Keras kepala itu tidak fleksibel, toleran terhadap kesalahan, dan tidak mau bergerak bahkan ketika kamu menabrak dinding.",
  ui_story_5082_50821301_156_dialog_content = "Saya sudah berulang kali memberitahu kamu bahwa ujian itu dimaksudkan untuk membunuhmu, bukan membuatmu lebih kuat.",
  ui_story_5082_50821301_157_dialog_content = "Tapi kamu tidak pernah mendengarkan, dan itulah mengapa kita berakhir dalam kekacauan ini.",
  ui_story_5082_50821301_158_dialog_content = "Aku…",
  ui_story_5082_50821301_159_dialog_content = "Tetapi karena kamu tidak mendengarkan...",
  ui_story_5082_50821301_160_dialog_content = "Bahwa kamu telah mengasah dirimu menjadi pedang yang paling tajam dan paling cemerlang dari Illumina.",
  ui_story_5082_50821301_161_dialog_content = "Itulah sebabnya para bajingan itu akan melakukan apa saja untuk mengendalikanmu, bahkan jika itu berarti membahayakan diri mereka sendiri.",
  ui_story_5082_50821301_162_dialog_content = "Mereka pengecut, tetapi ketamakan mereka mengalahkan rasa takut mereka. Mereka ingin memangkas cabang-cabangmu sampai kamu menjadi prajurit sempurna mereka.",
  ui_story_5082_50821301_163_dialog_content = "Sebagai saya, saya hanyalah salah satu dari cabang-cabang tersebut.",
  ui_story_5082_50821301_164_dialog_content = "Itu cukup! Saya tidak perlu mendengar sisanya.",
  ui_story_5082_50821301_165_dialog_content = "Aku tahu kamu pikir aku keras kepala, tapi itu hanya berarti aku tidak akan pernah menyerah pada hal-hal yang paling penting bagiku.",
  ui_story_5082_50821301_166_dialog_content = "Haha, ini mungkin pertama kalinya aku mendengar kamu mengaku ini pada dirimu sendiri.",
  ui_story_5082_50821301_167_dialog_content = "Sayangnya untukmu, aku masih bukan tipe yang mengikuti perintah orang lain.",
  ui_story_5082_50821301_168_dialog_content = "Alasan semua perawatan penekan itu tidak bisa membuat saya menghilang adalah karena saya tidak membiarkan mereka.",
  ui_story_5082_50821301_169_dialog_content = "Tapi sekarang karena kamu ingin aku tinggal, aku memutuskan untuk berubah pikiran.",
  ui_story_5082_50821301_170_dialog_content = "Kamu bisa melakukannya tanpa saya di sekitar. Kamu bahkan berhasil mewujudkan mimpimu menjadi Grand Marshal.",
  ui_story_5082_50821301_171_dialog_content = "Jangan bilang begitu! Saya tidak akan menjadi orang yang sama jika bukan karena kamu!",
  ui_story_5082_50821301_172_dialog_content = "<color=#e8d9bb>Bip-bip-bip-bip-bip!!!!</color>",
  ui_story_5082_50821301_173_dialog_content = "Sebuah alarm?",
  ui_story_5082_50821301_174_dialog_content = "Lokasi aktivasi Colossus tepat di depan. Pasti ada yang salah.",
  ui_story_5082_50821301_175_dialog_content = "—!",
  ui_story_5082_50821301_176_dialog_content = "Teriakan ini... Itu gadis itu yang meminta tolong!",
  ui_story_5082_50821301_177_dialog_content = "Hei!",
  ui_story_5082_50821301_178_dialog_content = "<color=#e8d9bb>Ruang Kontrol</color>",
  ui_story_5082_50821301_179_dialog_content = "<color=#e8d9bb>Bip-bip-bip-bip—</color>",
  ui_story_5082_50821301_180_dialog_content = "... Kecocokannya menurun?",
  ui_story_5082_50821301_181_dialog_content = "Ada yang salah, Tech Officer?",
  ui_story_5082_50821301_182_dialog_content = "Parameter <color=#FFB400>sebenarnya</color> untuk Navigator Cadangan berbeda dari yang ada di laporan. Apakah ada yang pernah melihat subjek tes secara langsung?",
  ui_story_5082_50821301_183_dialog_content = "Tidak, Bu... Komite tidak akan mengizinkannya, tapi saya tahu saya telah membaca parameter-parameter dalam laporan itu—",
  ui_story_5082_50821301_184_dialog_content = "Tidak masalah sekarang! Colossus itu hampir kehilangan kendali—",
  ui_story_5082_50821301_185_dialog_content = "T-Tech Officer! Kau mau ke mana?!",
  ui_story_5082_50821301_X185_dialog_content = "Aku harus ada di sana sekarang! Subjek dalam bahaya!",
  ui_story_5082_50821301_186_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5082_50821301_187_dialog_content = "<color=#e8d9bb>—!</color>",
  ui_story_5082_50821301_188_dialog_content = "Semua personel, evakuasi segera! Semua personel, evakuasi segera!",
  ui_story_5082_50821301_189_dialog_content = "... Co-Colossus telah menjadi liar!",
  ui_story_5082_50821301_190_dialog_content = "Menyesuaikan parameter tidak berpengaruh lagi!",
  ui_story_5082_50821301_191_dialog_content = "Dalam situasi ini, gadis di dalam ruang pilot...",
  ui_story_5082_50821301_192_dialog_content = "Menarik pilot keluar dari sana sekarang hanya akan memperburuk keadaan.",
  ui_story_5082_50821301_193_dialog_content = "Kekacauan ini sekarang ada di tangan Tech Officer, bukan kita. Saya yakin Komite akan menemukan solusinya.",
  ui_story_5082_50821301_194_dialog_content = "Lebih jauh lagi, satu-satunya cara kita bisa mendapatkan data yang kita butuhkan untuk upaya aktivasi di masa depan adalah dengan menjaga anak kecil itu di sana.",
  ui_story_5082_50821301_195_dialog_content = "...",
  ui_story_5082_50821301_196_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5082_50821301_197_dialog_content = "Lihat ke bawah sana... Apa yang terjadi pada tempat ini?",
  ui_story_5082_50821301_198_dialog_content = "...",
  ui_story_5082_50821301_199_dialog_content = "Berhenti! Saya tahu apa yang sedang Anda pikirkan, tetapi Anda baru saja berhasil menghindari kematian!",
  ui_story_5082_50821301_200_dialog_content = "Jika kamu turun ke sana dalam keadaanmu sekarang, kamu bisa lupakan tentang menjadi Grand Marshal, atau apapun itu sebenarnya!",
  ui_story_5082_50821301_201_dialog_content = "Jika saya hanya berdiri dan menyaksikan gadis kecil malang itu mati, maka saya juga tidak pantas menjadi Grand Marshal.",
  ui_story_5082_50821301_202_dialog_content = "Aku ingin memberitahumu sesuatu sebelumnya. Aku tahu kamu selalu menunjukkan dirimu kepada ku seperti ini...",
  ui_story_5082_50821301_203_dialog_content = "Tapi pada akhirnya, kita akan selalu menjadi orang yang sama.",
  ui_story_5082_50821301_204_dialog_content = "Jadi berhentilah memandangku seolah-olah aku sangat mengecewakan! Bahkan aku—",
  ui_story_5082_50821301_205_dialog_content = "Bisa saja aku memiliki momen-momen pemberontak!",
  ui_story_5082_50821301_206_dialog_content = "Mereka bilang impianku menjadi Grand Marshal seperti lubang tanpa dasar, yang terus menerus memikatku dan menghisap semangatku...",
  ui_story_5082_50821301_207_dialog_content = "Sebuah mimpi yang akan menghabisiku dan pada akhirnya membunuhku.",
  ui_story_5082_50821301_208_dialog_content = "Tapi Grand Marshal yang ingin saya jadikan teladan tidak peduli tentang status atau kemuliaan.",
  ui_story_5082_50821301_209_dialog_content = "Yang dia butuhkan hanyalah kekuatan dan otoritas untuk melindungi yang terluka dan menderita di bawah pengawasannya.",
  ui_story_5082_50821301_210_dialog_content = "Itulah mengapa tidak masalah apakah Illumina menerima saya atau tidak.",
  ui_story_5082_50821301_211_dialog_content = "Setidaknya, aku akan menjadi Grand Marshal untuk gadis kecil itu!!!",
  ui_story_5082_50821301_212_dialog_content = "Ketika kita pertama kali bertemu, kamu bilang ada naga yang terbakar di punggungku.",
  ui_story_5082_50821301_213_dialog_content = "Saya masih belum sepenuhnya mengerti apa yang kamu maksud dengan itu, tetapi jika saya memiliki kekuatan untuk menjadi api...",
  ui_story_5082_50821301_214_dialog_content = "Maka biarkan aku menjadi api yang membakar habis status quo busuk ini!",
  ui_story_5082_50821301_215_dialog_content = "...",
  ui_story_5082_50821301_216_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5082_50821301_217_dialog_content = "(Aku masih bisa mendengar suaranya! Dia ada di suatu tempat di dalam Colossus!)",
  ui_story_5082_50821301_218_dialog_content = "<color=#e8d9bb>Gemuruh-!</color>",
  ui_story_5082_50821301_219_dialog_content = "(Tapi jika aku tidak menangani ekornya terlebih dahulu— Huh?!)",
  ui_story_5082_50821301_220_dialog_content = "(Penekan yang mereka suntikkan ke dalam diriku... Apakah itu juga menekan Luminatics-ku?!)",
  ui_story_5082_50821301_221_dialog_content = "Kau benar-benar seorang bodoh...",
  ui_story_5082_50821301_222_dialog_content = "Mereka memanggilku alter-ego mu dan mengatakan bahwa aku adalah sisi pemberontak dari kepribadianmu yang biasanya patuh.",
  ui_story_5082_50821301_223_dialog_content = "Mereka mencoba untuk menghilangkan saya sehingga hanya sisi \"berguna\" Anda yang tersisa.",
  ui_story_5082_50821301_224_dialog_content = "Tapi untuk semua kecerdasan yang mereka klaim, mereka tidak pernah melihat kita apa adanya.",
  ui_story_5082_50821301_225_dialog_content = "Pemberontakan dan ketaatan hanyalah dua jenis kayu bakar yang berbeda. Dengan jumlah panas yang tepat—",
  ui_story_5082_50821301_226_dialog_content = "Kedua-duanya akan menyala dan menjadi bola api yang tak terhentikan!",
  ui_story_5082_50821301_227_dialog_content = "Hei! Reinhardt!",
  ui_story_5082_50821301_228_dialog_content = "<color=#e8d9bb>Ujung gaun merah darahnya bergetar dalam panasnya pertempuran</color>",
  ui_story_5082_50821301_229_dialog_content = "<color=#e8d9bb>Dengan senyuman nakal dan tantangan, dia berbalik dan memandang dirinya yang lain dari kejauhan.</color>",
  ui_story_5082_50821301_230_dialog_content = "Kekuatanku kini ada di tanganmu. Gunakanlah dengan baik!",
  ui_story_5082_50821301_231_dialog_content = "<color=#e8d9bb>Ledakan-!!!</color>",
  ui_story_5082_50821301_232_dialog_content = "<color=#e8d9bb>Gelombang Lumina melalui api yang menari.</color>",
  ui_story_5082_50821301_233_dialog_content = "<color=#e8d9bb>Partikel-partikel berkilau tersebar di seluruh panas yang menyala, dan mulai berkumpul pada saat berikutnya...</color>",
  ui_story_5082_50821301_234_dialog_content = "<color=#e8d9bb>Sebuah naga raksasa yang terbuat dari api murni melingkari Reinhardt saat menembus ekor Colossus.</color>",
  ui_story_5082_50821301_235_dialog_content = "<color=#e8d9bb>Renegade menghilang dengan ledakan, tetapi tawanya dan tatapan membara masih tertinggal.</color>",
  ui_story_5082_50821301_236_dialog_content = "Bakar semuanya sesuka hatimu!",
  ui_story_5082_50821301_237_dialog_content = "Jangan biarkan salah satu dari mereka mencuri kekuatanmu!",
  ui_story_5082_50821301_238_dialog_content = "Tentu saja!",
  ui_story_5082_50821301_239_dialog_content = "Finale yang Diterangi—!!",
  ui_story_5082_50821400_1_dialog_content = "Apakah kita di luar lagi?",
  ui_story_5082_50821400_2_dialog_content = "Ah! Tapi bagaimana dengan Spearhead dan Reinhardt lainnya?!",
  ui_story_5082_50821400_3_dialog_content = "Makhluk besar itu telah berubah menjadi tumpukan besi tua sejak lama.",
  ui_story_5082_50821400_4_dialog_content = "Ia hanya bisa melawan kita dengan satu ekor saja. Sisanya tubuhnya benar-benar tidak berfungsi.",
  ui_story_5082_50821400_5_dialog_content = "Jika benda itu masih bisa bergerak, kita tidak akan pernah punya kesempatan!",
  ui_story_5082_50821400_6_dialog_content = "Mengenai Reinhardt, bukankah itu dia di sana?",
  ui_story_5082_50821400_7_dialog_content = "Tidak, saya tidak sedang membicarakan tentang...",
  ui_story_5082_50821400_8_dialog_content = "<color=#e8d9bb>Reinhardt berjalan dengan tenang. Di tangannya adalah mesin yang telah mengikat begitu banyak takdir orang bersama-sama.</color>",
  ui_story_5082_50821400_9_dialog_content = "...Dia sudah tidak di sini lagi, bukan?",
  ui_story_5082_50821400_10_dialog_content = "Tidak, tapi dia menang. Dia selalu menang, bahkan melawan diriku yang sekarang.",
  ui_story_5082_50821400_11_dialog_content = "Uh... Apa yang sebenarnya terjadi di sana?",
  ui_story_5082_50821400_12_dialog_content = "Mungkin itu hanya keberuntunganku...",
  ui_story_5082_50821400_13_dialog_content = "Menurut prosedur normal, dia seharusnya telah menghilang dari hidupku setelah demamku mereda waktu itu.",
  ui_story_5082_50821400_14_dialog_content = "Tapi dia sama sekali tidak pernah menghilang...",
  ui_story_5082_50821400_15_dialog_content = "Mereka berhasil membunuh saya, tapi mereka tidak berhasil menghancurkan kita.",
  ui_story_5082_50821400_16_dialog_content = "...",
  ui_story_5082_50821400_17_dialog_content = "<color=#e8d9bb>Bzzt, bzzt—</color>",
  ui_story_5082_50821400_18_dialog_content = "(Itu Spearhead...)",
  ui_story_5082_50821400_19_dialog_content = "Mati... Kalian semua...",
  ui_story_5082_50821400_20_dialog_content = "Kau masih belum menerima kekalahan?",
  ui_story_5082_50821400_21_dialog_content = "Sikapmu membuatku jijik, Caelestite.",
  ui_story_5082_50821400_22_dialog_content = "Saya tidak punya alasan untuk bersikap ramah terhadap orang yang telah menipu saya dan membahayakan sekutu saya.",
  ui_story_5082_50821400_23_dialog_content = "Aurorian tidak memiliki cara untuk menerima kekuatanku.",
  ui_story_5082_50821400_24_dialog_content = "Adalah rasa lapar mereka akan kekuatan itu, yang sebenarnya bukan milik mereka, yang membawa mereka pada kehancuran mereka yang terakhir.",
  ui_story_5082_50821400_25_dialog_content = "Tapi dia dan gadis kecil itu berbeda...",
  ui_story_5082_50821400_26_dialog_content = "Kekuatan mereka lebih besar daripada Aurorian lainnya, dan oleh karena itu, aku juga terpaksa membayar harga.",
  ui_story_5082_50821400_27_dialog_content = "Kamu benar-benar pikir kamu bisa membandingkan dirimu dengan Reinhardt...?",
  ui_story_5082_50821400_28_dialog_content = "Bagaimana dengan Vice? Apa jenis kekuatan yang tersembunyi di dalam gadis berusia empat tahun itu?",
  ui_story_5082_50821400_29_dialog_content = "Kekuatan untuk mengendalikan diriku...",
  ui_story_5082_50821400_30_dialog_content = "... Pilot kamu?",
  ui_story_5082_50821400_31_dialog_content = "Pendaratan darurat terakhirku telah merenggut sayapku.",
  ui_story_5082_50821400_32_dialog_content = "Dan pertempuran terakhirku telah merenggut tubuhku.",
  ui_story_5082_50821400_33_dialog_content = "Tidak ada yang tersisa dari diri saya yang dulu. Saya tidak bisa mencapai apa pun dalam keadaan saya saat ini.",
  ui_story_5082_50821400_34_dialog_content = "Hanya karena aku bersimpati denganmu tidak berarti aku bisa memaafkanmu atas hal-hal yang telah kamu lakukan di masa lalu.",
  ui_story_5082_50821400_35_dialog_content = "Namun, saya bisa menyampaikan pesan di tempatmu.",
  ui_story_5082_50821400_36_dialog_content = "Kamu pasti tahu banyak tentang Eclipsite, kan? Sebagai imbalan atas informasi itu, Illumina mungkin bersedia untuk membuatkan tubuh baru untukmu.",
  ui_story_5082_50821400_37_dialog_content = "... Kamu ingin memerintahku? Dibandingkan dengan Navigator sebelumnya, kamu tidak layak sama sekali.",
  ui_story_5082_50821400_38_dialog_content = "Apakah Navigator sebelummu... juga Caelestite?",
  ui_story_5082_50821400_39_dialog_content = "Hmph. Navigator terakhirku adalah pengkhianat, tidak lebih.",
  ui_story_5082_50821400_40_dialog_content = "Tidak! Kamu yang mengikuti perintah! Kedua gadis itu dan saya sekarang menempuh jalan kami sendiri. Kami setia pada diri kami sendiri!",
  ui_story_5082_50821400_41_dialog_content = "Diri kalian?",
  ui_story_5082_50821400_42_dialog_content = "Hmm. Saya sendiri tidak lagi yakin siapa diri saya.",
  ui_story_5082_50821400_43_dialog_content = "Baik siapa pun kamu, kamu tidak diizinkan untuk menyakiti lebih banyak orang lagi, tidak peduli alasanmu.",
  ui_story_5082_50821400_44_dialog_content = "Katakan apa yang kamu mau, tapi aku masih tidak punya alasan untuk menuruti perintahmu.",
  ui_story_5082_50821400_45_dialog_content = "%$^#$^%^!......",
  ui_story_5082_50821400_46_dialog_content = "...",
  ui_story_5082_50821400_47_dialog_content = "Jadi Grand Marshal yang lain dan Yumi... Mereka bukan orang yang sama, kan? Masuk akal, karena hanya Grand Marshal yang bisa melihatnya...",
  ui_story_5082_50821400_48_dialog_content = "Tunggu...",
  ui_story_5082_50821400_49_dialog_content = "Vice, seorang gadis berusia empat tahun, dan Reinhardt, bintang yang sedang naik daun di Federasi pada saat itu... Keduanya terlibat dalam eksperimen tersebut...",
  ui_story_5082_50821400_50_dialog_content = "Jadi mengapa saya tidak menyadari itu...?",
  ui_story_5082_50821400_51_dialog_content = "B-Beri aku waktu sebentar! Aku... Aku perlu menyelesaikan beberapa hal...",
  ui_story_5082_50821400_52_dialog_content = "Saya tahu bahwa Tech Officer Gronru ditunjuk ke posisinya selama Krisis Darkover, dan tugas pertamanya adalah mengaktifkan Colossus.",
  ui_story_5082_50821400_53_dialog_content = "Aku pernah mencoba menanyakan hal itu padanya... Bahkan dengan sangat hati-hati!",
  ui_story_5082_50821400_54_dialog_content = "Tapi dia terus saja mengabaikanku dan mengetik kata \"parameter\" berulang-ulang di komputernya...",
  ui_story_5082_50821400_55_dialog_content = "Nah, sepertinya aku telah menemukan lebih kurang informasi yang aku cari!",
  ui_story_5082_50821400_56_dialog_content = "Selain keterlibatan Gronru dalam insiden itu... banyak subjek tes lainnya yang mengalami luka serius.",
  ui_story_5082_50821400_57_dialog_content = "Saya bahkan tidak ingin berpikir tentang apa yang akan terjadi jika Grand Marshal tidak menyelamatkan Vice waktu itu...",
  ui_story_5082_50821400_58_dialog_content = "Mengingat semua yang telah saya lakukan hingga saat itu, menyelamatkan Vice hanyalah puncak dari cerita saya.",
  ui_story_5082_50821400_59_dialog_content = "Aku tidak tahu siapa Vice pada saat itu. Yang aku inginkan hanyalah menjadi Grand Marshal-nya pada saat itu.",
  ui_story_5082_50821400_60_dialog_content = "...",
  ui_story_5082_50821400_61_dialog_content = "Dalam pandanganmu, Grand Marshal adalah seseorang dengan \"kekuatan dan otoritas untuk melindungi yang terluka dan menderita di bawah pengawasannya.\"",
  ui_story_5082_50821400_62_dialog_content = "Bukankah itu membuatmu satu-satunya orang yang cocok untuk pekerjaan itu, Reinhardt?",
  ui_story_5082_50821400_63_dialog_content = "Tapi kekuatan ini adalah cap yang ditanamkan pada kita oleh pemberontakan kita yang tak kenal menyerah.",
  ui_story_5082_50821400_64_dialog_content = "Saat itu, aku hanya orang yang berapi-api, sepenuhnya didorong oleh kemarahan. Aku tidak mengerti apa artinya menjadi Grand Marshal—yang aku pedulikan hanyalah memberikan keadilan versi sendiri dan tidak ada yang lain.",
  ui_story_5082_50821400_65_dialog_content = "Mengenai otoritasku...",
  ui_story_5082_50821400_66_dialog_content = "Tak kusangka eksperimen itu bisa mengikat takdir kita seperti ini.",
  ui_story_5082_50821400_67_dialog_content = "Helios, Denier, dan diriku... Kami tumbuh menjadi sangat dekat satu sama lain.",
  ui_story_5082_50821400_68_dialog_content = "Tapi pada akhirnya, kami harus berpisah.",
  ui_story_5082_50821400_69_dialog_content = "Helios telah melalui banyak penderitaan. Cologne dan Vaughn dikirim ke garis depan pertempuran yang paling berbahaya dan tidak pernah terdengar kabarnya lagi.",
  ui_story_5082_50821400_70_dialog_content = "Tapi dibandingkan dengan mereka, Denier... atau lebih tepatnya Forsakin, adalah orang yang keputusannya paling sejalan dengan niat awal kita.",
  ui_story_5082_50821400_71_dialog_content = "Aku menyaksikan setiap sekutu terdekatku menghilang satu per satu.",
  ui_story_5082_50821400_72_dialog_content = "Dan sekarang setelah mereka semua pergi, akhirnya aku menjadi Grand Marshal di Illumina. Itulah ironi dari otoritasku.",
  ui_story_5082_50821400_73_dialog_content = "Itu tidak benar, Reinhardt.",
  ui_story_5082_50821400_74_dialog_content = "Yang aku lihat hanyalah seseorang yang tidak pernah menyerah pada ide-ide lamanya.",
  ui_story_5082_50821400_75_dialog_content = "Kamu masih melindungi yang lemah dan tak berdaya tanpa memandang biaya. Sejauh ini, hal itu tentangmu belum berubah.",
  ui_story_5082_50821400_76_dialog_content = "Meski aku mulai terlihat seperti salah satu \"orang penting\" dari zaman dulu?",
  ui_story_5082_50821400_X76_dialog_content = "Aku yang kamu lihat sekarang adalah aku yang telah berkomitmen demi Illumina. Aku telah menyimpang dari idealisme awalku, gagal memberikan mereka pencerahan yang mereka layak dapatkan.",
  ui_story_5082_50821400_X77_dialog_content = "Benar, bahkan kamu telah berkorban cukup banyak... itulah sebabnya kamu adalah Grand Marshal. Kamu telah membayar hutangmu... bukankah itu sudah cukup?",
  ui_story_5082_50821400_77_dialog_content = "...",
  ui_story_5082_50821400_78_dialog_content = "Reinhardt, aku telah memikirkan masa lalu... Aku harus mengakui, semuanya sedikit kabur sekarang.",
  ui_story_5082_50821400_79_dialog_content = "Kalau hari ini aku tidak mengalami semua ini, aku tidak akan pernah tahu... Betapa berbedanya kamu sekarang dibandingkan dengan dirimu saat remaja.",
  ui_story_5082_50821400_80_dialog_content = "Kuat, menentukan, dan tak terhindarkan di jantung setiap pertempuran.",
  ui_story_5082_50821400_81_dialog_content = "Aku masih ingat saat kita tidak memiliki begitu banyak tanggung jawab untuk ditanggung... Hal-hal yang harus kita lakukan, cara segala sesuatu harus berakhir...",
  ui_story_5082_50821400_82_dialog_content = "Bahkan menaklukkan seluruh Astra adalah sesuatu yang kami pikir kami bisa capai!",
  ui_story_5082_50821400_83_dialog_content = "... Saya tidak yakin apa yang ingin saya katakan, tetapi sebagai Grand Marshal dan prajurit kita, semua yang kamu menangkan hingga hari ini adalah melalui kekuatanmu sendiri.",
  ui_story_5082_50821400_84_dialog_content = "Terlepas dari apakah aku tahu apa yang terjadi di balik layar, aku melihat kekuatanmu bertambah setiap hari...",
  ui_story_5082_50821400_85_dialog_content = "Dan melihat saat kamu memimpin prajuritmu dalam pertempuran tak terhitung jumlahnya yang akan tetap terukir di hati orang-orang Illumina sepanjang hidup mereka.",
  ui_story_5082_50821400_86_dialog_content = "Jadi ketika berita tentang promosi kamu menjadi Grand Marshal mulai menyebar, setiap orang di Federasi merasa tidak ada selain kebahagiaan untukmu.",
  ui_story_5082_50821400_87_dialog_content = "Setidaknya di mataku, tatapan yang kamu berikan padaku sebagai Grand Marshal tidak berbeda dengan tatapan yang kamu berikan saat kita bertarung sisi dengan sisi.",
  ui_story_5082_50821400_88_dialog_content = "... Kamu tidak berpikir ini semua bagian dari rencana Komite?",
  ui_story_5082_50821400_89_dialog_content = "Ketika saya dipromosikan menjadi Grand Marshal selama Krisis Darkover terakhir, sepertinya seolah-olah Komite tidak memiliki pilihan lain...",
  ui_story_5082_50821400_90_dialog_content = "Tapi untuk bom waktu yang sudah dingin seperti diriku, cara terbaik untuk mengendalikanku adalah dengan meninggalkan detonator di tangan saya.",
  ui_story_5082_50821400_91_dialog_content = "Sejauh ini menyangkut para ilmuwan di Komite, tindakan ini sepenuhnya tepat.",
  ui_story_5082_50821400_92_dialog_content = "Saat mengirim Wrath untuk bertempur dalam pertempuran mengerikan di Twilight.",
  ui_story_5082_50821400_93_dialog_content = "Sebenarnya, menurutku upaya Komite untuk menghancurkan seseorang yang sekuat kamu adalah kesalahan terbesar mereka.",
  ui_story_5082_50821400_94_dialog_content = "Meskipun mereka menolak untuk mengakuinya, setiap tentara di Illumina dan bahkan bangsawan Lumopolis melihatnya...",
  ui_story_5082_50821400_95_dialog_content = "Selama Krisis Darkover, kamu adalah pilihan yang paling realistis untuk menjadi Grand Marshal berikutnya.",
  ui_story_5082_50821400_96_dialog_content = "Jika kamu memiliki setengah niat untuk melakukannya, tidak ada yang bisa menghentikanmu untuk menjatuhkan Komite dan menjadi pemimpin tertinggi Illumina.",
  ui_story_5082_50821400_97_dialog_content = "Hahahaha! Itu mungkin sesuatu yang akan dilakukan Renegade, tetapi saya adalah jenis Grand Marshal yang berbeda, Barton.",
  ui_story_5082_50821400_98_dialog_content = "Anda tidak kecewa padaku, kan?",
  ui_story_5082_50821400_99_dialog_content = "Kecewa?",
  ui_story_5082_50821400_100_dialog_content = "Sama sekali tidak. Saya telah melihat semua yang telah Anda capai sejauh ini, dan saya tahu eksperimen-eksperimen itu tidak menjadikan Anda monster jenis apa pun.",
  ui_story_5082_50821400_101_dialog_content = "Dan setelah melihat apa yang telah Forsakin lakukan dalam beberapa tahun terakhir... Mari kita katakan saja saya senang kekuatan seperti itu ada di tangan Anda dan bukan orang lain...",
  ui_story_5082_50821400_102_dialog_content = "Aku memilihmu sebagai Grand Marshal-ku, Reinhardt. Hidupku telah berada di tanganmu untuk waktu yang lama sekarang.",
  ui_story_5082_50821400_103_dialog_content = "Kecewa padamu? Ha! Kamu tahu aku lebih baik dari itu!",
  ui_story_5082_50821400_104_dialog_content = "Meong... Sesuatu memberitahu saya bahwa Komandan Barton sedikit kesal...",
  ui_story_5082_50821400_105_dialog_content = "Itu karena aku kesal, kebanyakan pada diriku sendiri!",
  ui_story_5082_50821400_106_dialog_content = "Semakin saya memikirkan hal-hal ini, semakin buruk rasanya bagi saya... Sekutu terdekat saya mengalami begitu banyak penderitaan, tapi apa yang telah saya lakukan tentang itu?",
  ui_story_5082_50821400_107_dialog_content = "Seharusnya aku bertanya lebih banyak! Seharusnya aku... Argh!",
  ui_story_5082_50821400_108_dialog_content = "Barton.",
  ui_story_5082_50821400_109_dialog_content = "Terima kasih.",
  ui_story_5082_50821400_110_dialog_content = "...",
  ui_story_5082_50821400_111_dialog_content = "Tidak peduli seperti apa Grand Marshal yang mungkin kamu jadi... Kamu tetap Grand Marshal Illumina!",
  ui_story_5082_50821400_112_dialog_content = "Dan bahkan Grand Marshal yang pemberontak pun bisa membawa perubahan yang sangat dibutuhkan di Federasi, dan meningkatkan kehidupan setiap orang!",
  ui_story_5082_50821400_113_dialog_content = "Yumi mencintai ikan kering sebanyak aku, yang membuatnya sama seperti aku!",
  ui_story_5082_50821400_114_dialog_content = "Dan aku akan selalu berterima kasih karena kamu menjadi Grand Marshal kami. Bahkan, aku berharap itu tetap seperti itu selamanya!",
  ui_story_5082_50821400_115_dialog_content = "Haha, aku tidak bisa berjanji seperti itu; setelah semua, setiap hari baru membawa perubahan baru. Mungkin akan ada hari ketika aku bukan lagi Grand Marshal di Illumina.",
  ui_story_5082_50821400_116_dialog_content = "Dan mungkin saja sama tak terduganya dengan semua yang terjadi di sini hari ini.",
  ui_story_5082_50821400_117_dialog_content = "Namun bahkan dari perspektif itu, kita akan dapat menyaksikan sejarah terungkap dengan kedua mata kita sendiri.",
  ui_story_5082_50821400_118_dialog_content = "Aku masih merasa seolah-olah belum sepenuhnya menguasai kekuatan yang dia berikan padaku waktu itu.",
  ui_story_5082_50821400_119_dialog_content = "Tapi sekarang, aku masih memegang gelar Grand Marshal, jadi aku akan terus melakukan hal-hal yang hanya bisa aku lakukan.",
  ui_story_5082_50821400_120_dialog_content = "Ini satu-satunya cara aku bisa mencegah tragedi itu terjadi lagi.",
  ui_story_5082_50821400_121_dialog_content = "Aku akan mewujudkan idealisme masa lalu kita.",
  ui_story_5082_50821400_122_dialog_content = "Apakah itu Eclipsites atau mereka yang berusaha menyakiti kawan-kawan kita, kita masih memiliki banyak pertempuran panjang dan sulit di depan kita.",
  ui_story_5082_50821400_123_dialog_content = "Dapatkah saya mengandalkan dukungan semua orang untuk menjaga Illumina tetap bergerak ke arah yang benar?",
  ui_story_5082_50821400_124_dialog_content = "Kami selalu siap menerima perintah Anda, Grand Marshal!",
  ui_story_5082_50821400_125_dialog_content = "Seperti yang selalu saya katakan, kamu tidak boleh mengesampingkan saya dalam hal apapun!",
  ui_story_5082_50821400_126_dialog_content = "Kamu selalu diterima untuk bertanya kepada saya tentang intelijen terbaru juga, Grand Marshal!",
  ui_story_5082_50821400_127_dialog_content = "Kemudian setelah kita kembali, kita akan mulai dengan menyelidiki dampak dari eksperimen Colossus di masa lalu.",
  ui_story_5082_50821400_128_dialog_content = "Paham!",
  ui_story_5082_50821400_129_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian</color>",
  ui_story_5082_50821400_130_dialog_content = "Semua orang sudah kembali. Kenapa kamu masih di sini?",
  ui_story_5082_50821400_131_dialog_content = "Saya bisa menanyakan hal yang sama kepada kamu.",
  ui_story_5082_50821400_132_dialog_content = "Kamu masih memikirkan Renegade, bukan?",
  ui_story_5082_50821400_133_dialog_content = "... Aku hanya merasa sedikit menyesal, itu saja.",
  ui_story_5082_50821400_134_dialog_content = "Aku tidak mengira akan melihat sebagian dari diriku mati seperti itu.",
  ui_story_5082_50821400_135_dialog_content = "Sebelum dia pergi, Renegade menitipkan sebuah pertanyaan untukmu padaku.",
  ui_story_5082_50821400_136_dialog_content = "?",
  ui_story_5082_50821400_137_dialog_content = "Dia ingin tahu...",
  ui_story_5082_50821400_138_dialog_content = "Jika kamu masih marah tentang segala hal.",
  ui_story_5082_50821400_139_dialog_content = "...",
  ui_story_5082_50821400_140_dialog_content = "Ketika kami pertama kali sampai di sini, aku selalu mendengar dia berteriak setiap kali aku merasakan kehadirannya.",
  ui_story_5082_50821400_141_dialog_content = "Aku pikir dia berteriak karena rasa sakit atau kesedihan.",
  ui_story_5082_50821400_142_dialog_content = "Tapi setelah melihat kenanganmu, akhirnya saya mengerti. Dia tidak berteriak kesakitan—",
  ui_story_5082_50821400_143_dialog_content = "Dia menjerit dengan amarah.",
  ui_story_5082_50821400_144_dialog_content = "Dia marah, Reinhardt.",
  ui_story_5082_50821400_145_dialog_content = "Marah untuk setiap korban tak bersalah dari ketidakadilan, dan untuk setiap kehidupan yang telah diperlakukan dengan kekejaman dan penghinaan.",
  ui_story_5082_50821400_146_dialog_content = "Kemarahan abadi itu terukir dalam hatinya dan di kedalaman terdalam kesadarannya.",
  ui_story_5082_50821400_147_dialog_content = "Dia adalah seorang pemberontak yang lahir dari api kemarahan.",
  ui_story_5082_50821400_148_dialog_content = "Anda harus memberinya jawaban.",
  ui_story_5082_50821400_149_dialog_content = "Jujur saja, saya tidak berpikir dia akan menyukai jawaban saya.",
  ui_story_5082_50821400_150_dialog_content = "Dan itu karena sekarang aku adalah Grand Marshal di Illumina.",
  ui_story_5082_50821400_151_dialog_content = "Saya pernah mendengar seseorang mengatakan bahwa Grand Marshal itu seperti api.",
  ui_story_5082_50821400_152_dialog_content = "Satu yang dinyalakan dan diberi bahan bakar oleh tubuh para prajurit yang gugur.",
  ui_story_5082_50821400_153_dialog_content = "Tapi nyala api yang terang dan membakar tidak akan lama menyala ketika ditutupi.",
  ui_story_5082_50821400_154_dialog_content = "Api dalam diri seseorang tidak akan pernah cukup terang atau cukup kuat untuk menerangi malam yang abadi.",
  ui_story_5082_50821400_155_dialog_content = "Itulah mengapa saya tidak bisa membiarkan harapan banyak orang tetap terperangkap dalam orang yang dikenal sebagai Reinhardt.",
  ui_story_5082_50821400_156_dialog_content = "Tapi yang terpenting, aku tidak bisa menganggap diriku sendiri hanya sebagai penyelamat.",
  ui_story_5082_50821400_157_dialog_content = "Sebuah dunia yang benar-benar cemerlang yang bersinar dengan cahaya iluminasi... itu adalah dunia yang akan kita bentuk bersama.",
  ui_story_5082_50821400_158_dialog_content = "Itulah mengapa saya perlu mengasah beberapa sisi saya sendiri... sisi yang mungkin masih terlalu tajam.",
  ui_story_5082_50821400_159_dialog_content = "Dan itulah mengapa aku harus menguburkannya di sini.",
  ui_story_5082_50821400_160_dialog_content = "<color=#e8d9bb>Reinhardt membungkuk dan menaruh perangkat itu di tanah sebelum menaburkan sedikit tanah di atasnya.</color>",
  ui_story_5082_50821400_161_dialog_content = "<color=#e8d9bb>Seolah-olah meletakkan seseorang untuk beristirahat.</color>",
  ui_story_5082_50821400_162_dialog_content = "Setelah hari ini, hanya akan ada aku saja.",
  ui_story_5082_50821400_163_dialog_content = "Selamat tinggal, Reinhardt.",
  ui_story_5082_50821400_164_dialog_content = "Seandainya saja kita punya kesempatan untuk berbicara lebih banyak sebelum akhir.",
  ui_story_5082_50821400_165_dialog_content = "Tapi aku akan selalu mengingatmu. Kaulah yang membuatku merasa lengkap.",
  ui_story_5082_50821400_166_dialog_content = "May Aku tak pernah melupakan kemarahan yang pernah memicu dan membawaku sampai di titik ini.",
  ui_story_5082_50821400_167_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5082_50821400_168_dialog_content = "<color=#e8d9bb>Sebagai respons terakhir, debu di helm itu ditiup perlahan.</color>",
  ui_story_5082_50821400_169_dialog_content = "Anda tidak akan melakukannya.",
  ui_story_5082_50821400_170_dialog_content = "Jadi kamu telah datang, \"kemarahanku.\"",
  ui_story_5082_50821400_171_dialog_content = "Dan bahkan jika kamu lupa, aku akan selalu ada untuk mengingatkanmu.",
  ui_story_5082_50821400_172_dialog_content = "Saya sekarang menjadi bagian dari kekuatanmu, dan tak seorang pun yang akan bisa mengambilnya dari dirimu.",
  ui_story_5082_50821400_173_dialog_content = "Apakah kamu telah menerima apa yang telah aku jadi? Selama bertahun-tahun aku telah belajar untuk berkompromi dan jatuh ke dalam peran naga jahat yang kamu lihat.",
  ui_story_5082_50821400_174_dialog_content = "Tapi, kamu mengingat saya berarti kamu belum benar-benar melupakan dari mana asal kemarahan kita.",
  ui_story_5082_50821400_175_dialog_content = "Kamu adalah orang yang menumbangkan saya, namun api yang sama yang menghabisi saya akhirnya membentukmu menjadi apa yang kamu sekarang—pencahayaan yang telah kita semua tunggu.",
  ui_story_5082_50821400_176_dialog_content = "Mengetahui kamu masih di jalan yang benar, saya tidak memiliki keluhan.",
  ui_story_5082_50821400_177_dialog_content = "Aku akan selalu mengawasimu di dalam hatimu... Dan jika suatu hari kamu mulai tersesat—",
  ui_story_5082_50821400_178_dialog_content = "Aku akan memberontak melawanmu.",
  ui_story_5082_50821400_179_dialog_content = "<color=#e8d9bb>Senyumnya selalu membawa intensitas yang membara. Setiap kali Reinhardt melihatnya, dia merasa aneh tapi tenang.</color>",
  ui_story_5082_50821400_180_dialog_content = "Nah, kau bilang sendiri.",
  ui_story_5082_50821400_181_dialog_content = "Sepakat."
}
return config
